/* Nightdesk primitives — plain CSS, tokens only. */

/* ---------- provider / shared ---------- */

.nd-root {
  min-height: 100vh;
  background:
    radial-gradient(900px 520px at 88% -12%, color-mix(in srgb, var(--nd-accent) 12%, transparent), transparent 58%),
    radial-gradient(720px 420px at -8% 18%, rgba(110, 168, 255, 0.08), transparent 55%),
    linear-gradient(180deg, var(--nd-bg-surface) 0%, var(--nd-bg-canvas) 42%, var(--nd-bg-inset) 100%);
  color: var(--nd-text-primary);
  font-family: var(--nd-font-body);
  font-size: var(--nd-text-14);
}

.nd-micro-label {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}

.nd-link {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-accent-text);
}

.nd-link:hover {
  color: var(--nd-accent-hover);
}

.nd-section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--nd-space-3);
  padding-bottom: var(--nd-space-2);
  border-bottom: 1px solid var(--nd-border-default);
}

.nd-section-header__meta {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
}

/* ---------- app shell ---------- */

.nd-shell {
  display: flex;
  min-height: 100vh;
  max-width: 100%;
  overflow-x: clip;
}

.nd-shell__sidebar {
  width: var(--nd-sidebar-w);
  flex: 0 0 var(--nd-sidebar-w);
  display: flex;
  flex-direction: column;
  gap: var(--nd-space-3);
  background:
    linear-gradient(180deg, rgba(24, 30, 42, 0.96) 0%, rgba(14, 18, 26, 0.98) 100%);
  border-right: 1px solid var(--nd-border-subtle);
  box-shadow: 1px 0 0 rgba(255, 255, 255, 0.02);
  padding: 16px 12px 14px;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}

.nd-shell__main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  max-width: 100%;
  overflow-x: clip;
}

.nd-shell__topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  min-width: 0;
  gap: var(--nd-space-3);
  min-height: var(--nd-topbar-h);
  padding: 8px var(--nd-content-pad-x);
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border-subtle) 80%, var(--nd-accent) 22%);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 5%, transparent), transparent 70%),
    color-mix(in srgb, var(--nd-bg-canvas) 68%, transparent);
  backdrop-filter: blur(16px) saturate(1.25);
  -webkit-backdrop-filter: blur(16px) saturate(1.25);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.04),
    0 12px 28px rgba(0, 0, 0, 0.18);
}

.nd-shell__content {
  flex: 1;
  min-width: 0;
  width: 100%;
  padding: var(--nd-content-pad-y) var(--nd-content-pad-x) 40px;
  overflow-x: clip;
}

@media (max-width: 1320px) {
  .nd-shell__sidebar {
    --nd-sidebar-w: 208px;
  }

  .nd-shell__topbar .nt-global-search {
    order: 10;
    flex: 1 0 100%;
    width: 100% !important;
    margin-left: 0 !important;
  }
}

@media (max-width: 820px) {
  .nd-shell {
    display: block;
  }

  .nd-shell__sidebar {
    display: none;
  }

  .nd-shell__topbar {
    position: relative;
    flex-wrap: wrap;
    width: 100%;
    max-width: 100vw;
    gap: 8px;
    padding: 10px 16px;
  }

  .nd-shell__content {
    padding: 14px 16px 40px;
  }
}

@media (max-width: 760px) {
  .nd-section-header {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .nd-section-header__meta {
    max-width: 100%;
    overflow-wrap: anywhere;
  }
}

.nd-navitem {
  display: flex;
  align-items: center;
  gap: var(--nd-space-2);
  width: 100%;
  text-align: left;
  font-family: var(--nd-font-body);
  font-size: var(--nd-text-12);
  font-weight: 500;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: var(--nd-radius-md);
  background: none;
  color: var(--nd-text-secondary);
  cursor: pointer;
  transition:
    background var(--nd-duration-fast) var(--nd-ease),
    color var(--nd-duration-fast) var(--nd-ease),
    border-color var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease);
}

.nd-navitem:hover {
  color: var(--nd-text-primary);
  background: color-mix(in srgb, var(--nd-accent) 6%, rgba(255, 255, 255, 0.02));
  border-color: color-mix(in srgb, var(--nd-border-subtle) 70%, var(--nd-accent) 30%);
  box-shadow: inset 2px 0 0 color-mix(in srgb, var(--nd-accent) 45%, transparent);
}

.nd-navitem--active,
.nd-navitem--active:hover {
  color: var(--nd-accent-text);
  background: linear-gradient(
    90deg,
    var(--nd-accent-subtle),
    color-mix(in srgb, var(--nd-accent) 4%, transparent)
  );
  border-color: color-mix(in srgb, var(--nd-accent) 28%, transparent);
  box-shadow:
    inset 2px 0 0 var(--nd-accent),
    0 0 18px color-mix(in srgb, var(--nd-accent) 12%, transparent);
  text-shadow: 0 0 14px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}

/* ---------- card / divider / headings ---------- */

.nd-card {
  border-radius: var(--nd-radius-lg);
  min-width: 0;
  overflow-x: clip;
}

.nd-card--soft {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 5%, transparent), transparent 32%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.02), transparent 28%),
    var(--nd-bg-surface);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-default));
  box-shadow:
    var(--nd-shadow-soft),
    inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 8%, transparent);
  padding: var(--nd-space-4);
}

.nd-card--plain {
  background: transparent;
}

.nd-divider {
  border: none;
}

.nd-divider--default {
  height: 1px;
  background: var(--nd-border-subtle);
}

.nd-divider--flair {
  height: 2px;
  width: 48px;
  border-radius: var(--nd-radius-full);
  background: linear-gradient(
    90deg,
    var(--nd-accent),
    color-mix(in srgb, var(--nd-accent) 35%, transparent)
  );
  box-shadow: 0 0 16px color-mix(in srgb, var(--nd-accent) 40%, transparent);
  margin: 12px 0;
}

.nd-heading {
  margin: 0;
  font-family: var(--nd-font-display);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.025em;
  color: var(--nd-text-primary);
}

.nd-heading--1 {
  font-size: var(--nd-text-34);
  letter-spacing: -0.03em;
}

.nd-heading--2 {
  font-size: var(--nd-text-26);
}

.nd-heading--3 {
  font-size: var(--nd-text-18);
  font-weight: 600;
}

.nd-heading--4 {
  font-size: var(--nd-text-16);
  font-weight: 600;
}

.nd-heading__overline {
  display: block;
  margin-bottom: 6px;
}

/* ---------- code / kbd ---------- */

.nd-code {
  font-family: var(--nd-font-mono);
  font-size: 0.92em;
  color: var(--nd-text-primary);
  background: var(--nd-bg-inset);
  border: 1px solid var(--nd-border-subtle);
  border-radius: var(--nd-radius-sm);
  padding: 1px 5px;
}

.nd-code-block {
  margin: 0;
  background: var(--nd-bg-inset);
  border: 1px solid var(--nd-border-subtle);
  border-radius: var(--nd-radius-md);
  padding: 14px 16px;
  overflow-x: auto;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-12);
  line-height: 1.6;
  color: var(--nd-text-secondary);
  white-space: pre;
}

.nd-kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-secondary);
  background: var(--nd-bg-raised);
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-sm);
}

/* ---------- table (open frame) ---------- */

.nd-table-scroll {
  width: 100%;
  overflow-x: auto;
  border: 1px solid color-mix(in srgb, var(--nd-border-subtle) 85%, var(--nd-accent) 15%);
  border-radius: var(--nd-radius-lg);
  background: color-mix(in srgb, var(--nd-bg-surface) 88%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 8%, transparent),
    0 8px 28px color-mix(in srgb, var(--nd-bg-inset) 55%, transparent);
}

.nd-table-scroll--virtual {
  max-height: min(70vh, 720px);
  overflow-y: auto;
}

.nd-table {
  width: 100%;
  border-collapse: collapse;
}

.nd-table__th {
  text-align: left;
  font-family: var(--nd-font-mono);
  font-weight: 500;
  font-size: var(--nd-text-10);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  padding: 10px 16px 10px;
  border-bottom: 1px solid var(--nd-border-default);
  white-space: nowrap;
}

.nd-table__td {
  font-size: var(--nd-text-12);
  color: var(--nd-text-primary);
  padding: var(--nd-row-pad-y) 14px;
  border-bottom: 1px solid var(--nd-border-subtle);
  vertical-align: middle;
}

/* Sticky column headers keep a long table's column context on scroll. The
   surface token matches the soft Card a table sits on; 10 lifts the header
   above its rows but keeps it under the sticky topbar (z-index 20). */
.nd-table__th {
  position: sticky;
  top: 0;
  z-index: 10;
  background: color-mix(in srgb, var(--nd-bg-surface) 90%, var(--nd-bg-inset) 10%);
  backdrop-filter: blur(10px) saturate(1.08);
  box-shadow: 0 1px 0 color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border-default));
}

.nd-table--compact .nd-table__th {
  padding: 4px 12px 6px;
}

.nd-table--compact .nd-table__td {
  padding: 6px 12px;
}

.nd-table--open .nd-table__th:first-child,
.nd-table--open .nd-table__td:first-child {
  padding-left: 0;
}

.nd-table--open .nd-table__th:last-child,
.nd-table--open .nd-table__td:last-child {
  padding-right: 0;
}

.nd-table__th--numeric,
.nd-table__td--numeric {
  text-align: right;
  font-family: var(--nd-font-mono);
  font-variant-numeric: tabular-nums;
}

.nd-table__tr--interactive {
  box-shadow: inset 2px 0 0 transparent;
  cursor: pointer;
  transition:
    background var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease);
}

.nd-table__tr--interactive:hover {
  background: var(--nd-bg-surface);
  box-shadow: inset 2px 0 0 var(--nd-accent);
}

.nd-table__tr--interactive:focus-visible {
  outline: 2px solid var(--nd-accent);
  outline-offset: -2px;
  background: var(--nd-bg-surface);
}

/* ---------- data table superpowers ---------- */

/* Threshold-tint cells: a ~12%-alpha tone wash, straight from the -subtle
   token family. Mechanics only — a column opts in via its definition. */
.nd-table__td--tint-success {
  background: var(--nd-success-subtle);
}

.nd-table__td--tint-warning {
  background: var(--nd-warning-subtle);
}

.nd-table__td--tint-danger {
  background: var(--nd-danger-subtle);
}

.nd-table__td--tint-info {
  background: var(--nd-info-subtle);
}

.nd-table__td--tint-neutral {
  background: var(--nd-neutral-subtle);
}

.nd-table__td--tint-accent {
  background: var(--nd-accent-subtle);
}

/* The focused-row / selected-row states of a keyboard grid. Focus reuses the
   interactive row's outline above; selection is the accent edge-bar from the
   hover state, held on, over a faint glow so it reads as a state, not a
   pointer position. */
.nd-table__tr--selected {
  background: color-mix(in srgb, var(--nd-accent) 9%, var(--nd-bg-surface));
  box-shadow: inset 2px 0 0 var(--nd-accent);
}

/* Edge-drag resize handle. The th is already positioned (sticky), so the
   handle parks on its right edge with an invisible grip wide enough to hit. */
.nd-table__resize {
  position: absolute;
  top: 0;
  /* Inside the header cell: a -5px overhang past the last column counts as
     scrollable overflow in .nd-table-scroll and paints a phantom horizontal
     scrollbar even when the table fits. */
  right: 0;
  width: 10px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
  z-index: 11;
}

.nd-table__resize::after {
  content: '';
  position: absolute;
  top: 20%;
  bottom: 20%;
  right: 4px;
  width: 2px;
  border-radius: var(--nd-radius-full);
  background: transparent;
  transition: background var(--nd-duration-fast) var(--nd-ease);
}

.nd-table__resize:hover::after,
.nd-table__resize:active::after {
  background: var(--nd-accent);
}

/* Header sort control: an unstyled button carrying the header's own
   typography; the mark stays muted until the column drives the order. */
.nd-table__sort {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  color: inherit;
  cursor: pointer;
}

.nd-table__sort:hover {
  color: var(--nd-text-primary);
}

.nd-table__sort-mark {
  font-size: var(--nd-text-10);
  color: var(--nd-text-faint, var(--nd-text-muted));
  opacity: 0.55;
}

.nd-table__sort-mark--active {
  color: var(--nd-accent);
  opacity: 1;
}

/* ---------- view options (column manager popover) ---------- */

.nd-viewopts {
  position: relative;
  display: inline-flex;
}

.nd-viewopts__panel {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: var(--nd-z-dropdown);
  min-width: 224px;
  padding: 10px;
  background: var(--nd-bg-raised);
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-lg);
  box-shadow: var(--nd-shadow-overlay);
  animation: nd-fade var(--nd-duration-fast) var(--nd-ease);
}

.nd-viewopts__heading {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  padding: 0 6px 6px;
}

.nd-viewopts__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.nd-viewopts__item {
  display: flex;
  align-items: center;
  gap: var(--nd-space-2);
  padding: 2px 6px;
  border-radius: var(--nd-radius-md);
}

.nd-viewopts__item:hover {
  background: var(--nd-bg-surface);
}

.nd-viewopts__check {
  flex: 1;
  min-width: 0;
  color: var(--nd-text-primary);
}

.nd-viewopts__moves {
  display: inline-flex;
  gap: 2px;
}

.nd-viewopts__move {
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-sm);
  background: none;
  color: var(--nd-text-secondary);
  font-size: var(--nd-text-11);
  line-height: 1;
  cursor: pointer;
}

.nd-viewopts__move:hover:not(:disabled),
.nd-viewopts__move:focus-visible {
  color: var(--nd-text-primary);
  border-color: var(--nd-border-strong);
}

.nd-viewopts__move:disabled {
  opacity: 0.35;
  cursor: default;
}

.nd-viewopts__reset {
  margin-top: 8px;
  width: 100%;
  padding: 5px 6px;
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-md);
  background: none;
  color: var(--nd-accent-text);
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  cursor: pointer;
}

.nd-viewopts__reset:hover,
.nd-viewopts__reset:focus-visible {
  border-color: var(--nd-accent);
}

/* ---------- keyboard shortcuts overlay ---------- */

.nd-shortcuts__trigger {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-full);
  background: none;
  color: var(--nd-text-muted);
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  cursor: pointer;
}

.nd-shortcuts__trigger:hover,
.nd-shortcuts__trigger:focus-visible {
  color: var(--nd-text-primary);
  border-color: var(--nd-border-strong);
}

.nd-shortcuts-root {
  position: fixed;
  inset: 0;
  z-index: var(--nd-z-overlay);
  display: flex;
  align-items: center;
  justify-content: center;
}

.nd-shortcuts-overlay {
  position: absolute;
  inset: 0;
  background: var(--nd-overlay-scrim);
  animation: nd-fade var(--nd-duration-base) var(--nd-ease);
}

.nd-shortcuts {
  position: relative;
  width: 400px;
  max-width: calc(100vw - 32px);
  max-height: calc(100vh - 64px);
  overflow-y: auto;
  padding: 20px 24px 24px;
  background: var(--nd-bg-surface);
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-xl);
  box-shadow: var(--nd-shadow-overlay);
}

.nd-shortcuts__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.nd-shortcuts__title {
  font-family: var(--nd-font-display);
  font-size: var(--nd-text-16);
  color: var(--nd-text-primary);
  line-height: 1.25;
}

.nd-shortcuts__close {
  border: 0;
  background: none;
  color: var(--nd-text-secondary);
  cursor: pointer;
  font-size: 24px;
  line-height: 1;
  padding: 0 2px;
}

.nd-shortcuts__close:hover,
.nd-shortcuts__close:focus-visible {
  color: var(--nd-text-primary);
}

.nd-shortcuts__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.nd-shortcuts__item {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
}

.nd-shortcuts__item .nd-kbd {
  min-width: 72px;
  height: auto;
  padding: 3px 8px;
  text-align: center;
  flex: 0 0 auto;
}

/* ---------- stat ---------- */

.nd-stat {
  position: relative;
  padding: 12px 14px;
  border-radius: var(--nd-radius-lg);
  border: 1px solid color-mix(in srgb, var(--nd-border-default) 85%, var(--nd-accent) 15%);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 5%, transparent), transparent 42%),
    var(--nd-bg-surface);
  box-shadow: var(--nd-shadow-soft);
  overflow: hidden;
  transition:
    border-color var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease);
}
.nd-stat:hover {
  border-color: color-mix(in srgb, var(--nd-border-default) 60%, var(--nd-accent) 40%);
  box-shadow:
    var(--nd-shadow-soft),
    0 0 20px color-mix(in srgb, var(--nd-accent) 10%, transparent);
}

.nd-stat::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 2px;
  background: linear-gradient(180deg, var(--nd-accent), transparent 85%);
  opacity: 0.9;
}

.nd-stat__rule {
  width: 18px;
  height: 2px;
  background: var(--nd-accent);
  margin-bottom: 7px;
  border-radius: var(--nd-radius-full);
}

.nd-stat__value {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-22);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-primary);
  margin-top: 4px;
  letter-spacing: -0.02em;
}

.nd-stat__delta {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  line-height: 1.4;
  margin-top: 4px;
}

.nd-stat__delta--positive {
  color: var(--nd-success);
}

.nd-stat__delta--negative {
  color: var(--nd-danger);
}

.nd-stat__delta--neutral {
  color: var(--nd-text-muted);
}

/* ---------- badge ---------- */

.nd-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.06em;
  line-height: 1.4;
  padding: 3px 8px;
  border-radius: var(--nd-radius-full);
  border: 1px solid transparent;
  white-space: nowrap;
}

.nd-badge--success {
  color: var(--nd-success);
  background: var(--nd-success-subtle);
}

.nd-badge--warning {
  color: var(--nd-warning);
  background: var(--nd-warning-subtle);
}

.nd-badge--danger {
  color: var(--nd-danger);
  background: var(--nd-danger-subtle);
}

.nd-badge--info {
  color: var(--nd-info);
  background: var(--nd-info-subtle);
}

.nd-badge--neutral {
  color: var(--nd-text-secondary);
  background: rgba(255, 255, 255, 0.03);
  border-color: var(--nd-border-default);
}

.nd-badge--accent {
  color: var(--nd-accent-text);
  background: var(--nd-accent-subtle);
  border-color: color-mix(in srgb, var(--nd-accent) 22%, transparent);
}

.nd-badge__dot {
  width: 5px;
  height: 5px;
  border-radius: var(--nd-radius-full);
  background: currentColor;
  flex: 0 0 auto;
}

/* ---------- avatar ---------- */

.nd-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  border-radius: var(--nd-radius-full);
  background: var(--nd-accent-subtle);
  color: var(--nd-accent-text);
  font-family: var(--nd-font-mono);
  text-transform: uppercase;
}

.nd-avatar--sm {
  width: 24px;
  height: 24px;
  font-size: var(--nd-text-10);
}

.nd-avatar--md {
  width: 32px;
  height: 32px;
  font-size: var(--nd-text-11);
}

/* ---------- alert ---------- */

.nd-alert {
  display: flex;
  gap: var(--nd-space-3);
  padding: 12px 14px;
  border-radius: var(--nd-radius-lg);
  border: 1px solid var(--nd-border-subtle);
  border-left: 3px solid transparent;
  box-shadow: var(--nd-shadow-soft);
}

.nd-alert--success {
  background: var(--nd-success-subtle);
  border-left-color: var(--nd-success);
}

.nd-alert--warning {
  background: var(--nd-warning-subtle);
  border-left-color: var(--nd-warning);
}

.nd-alert--danger {
  background: var(--nd-danger-subtle);
  border-left-color: var(--nd-danger);
}

.nd-alert--info {
  background: var(--nd-info-subtle);
  border-left-color: var(--nd-info);
}

.nd-alert--neutral {
  background: var(--nd-bg-raised);
  border-left-color: var(--nd-border-strong);
}

.nd-alert__content {
  flex: 1;
  min-width: 0;
}

.nd-alert__title {
  font-size: var(--nd-text-14);
  font-weight: 500;
  color: var(--nd-text-primary);
  line-height: 1.35;
}

.nd-alert__body {
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
  line-height: 1.5;
  margin-top: 3px;
}

.nd-alert__dismiss {
  flex: 0 0 auto;
  align-self: flex-start;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}

.nd-alert__dismiss:hover {
  color: var(--nd-text-primary);
}

/* ---------- empty state / progress / spinner / skeleton ---------- */

.nd-empty {
  padding: 48px 24px;
  text-align: center;
}

.nd-empty__title {
  font-size: var(--nd-text-14);
  font-weight: 500;
  color: var(--nd-text-primary);
}

.nd-empty__desc {
  font-size: var(--nd-text-12);
  color: var(--nd-text-muted);
  margin-top: 6px;
}

.nd-progress__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--nd-space-3);
  margin-bottom: 7px;
}

.nd-progress__note {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
}

.nd-progress__track {
  height: 3px;
  background: var(--nd-bg-inset);
  border-radius: var(--nd-radius-full);
  overflow: hidden;
}

.nd-progress__fill {
  height: 3px;
  border-radius: var(--nd-radius-full);
  transition: width var(--nd-duration-base) var(--nd-ease);
}

.nd-progress__fill--accent {
  background: var(--nd-accent);
}

.nd-progress__fill--success {
  background: var(--nd-success);
}

.nd-progress__fill--warning {
  background: var(--nd-warning);
}

.nd-progress__fill--danger {
  background: var(--nd-danger);
}

.nd-spinner {
  display: inline-block;
  border-radius: 50%;
  border: 2px solid var(--nd-border-strong);
  border-top-color: var(--nd-accent);
  animation: nd-spin 0.8s linear infinite;
}

.nd-spinner--sm {
  width: 14px;
  height: 14px;
}

.nd-spinner--md {
  width: 18px;
  height: 18px;
}

@keyframes nd-spin {
  to {
    transform: rotate(360deg);
  }
}

.nd-skeleton {
  background:
    linear-gradient(
      105deg,
      var(--nd-bg-raised) 0%,
      color-mix(in srgb, var(--nd-accent) 10%, var(--nd-bg-raised)) 42%,
      var(--nd-bg-raised) 78%
    );
  background-size: 220% 100%;
  border-radius: var(--nd-radius-sm);
  animation:
    nd-pulse 1.6s var(--nd-ease) infinite,
    nd-shimmer 2.4s var(--nd-ease) infinite;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 6%, transparent);
}

@keyframes nd-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.55;
  }
}

@keyframes nd-shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}

/* ---------- toast ---------- */

.nd-toast-region {
  position: fixed;
  right: 20px;
  bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: var(--nd-space-2);
  z-index: var(--nd-z-toast);
}

.nd-toast {
  min-width: min(260px, calc(100vw - 40px));
  max-width: min(360px, calc(100vw - 40px));
  background: color-mix(in srgb, var(--nd-bg-raised) 88%, transparent);
  backdrop-filter: blur(14px) saturate(1.15);
  -webkit-backdrop-filter: blur(14px) saturate(1.15);
  border: 1px solid color-mix(in srgb, var(--nd-border-default) 80%, var(--nd-accent) 20%);
  border-left: 2px solid var(--nd-accent);
  border-radius: var(--nd-radius-md);
  box-shadow:
    var(--nd-shadow-overlay),
    0 0 24px color-mix(in srgb, var(--nd-accent) 10%, transparent);
  padding: 10px 14px;
  animation: nd-toast-in var(--nd-duration-base) var(--nd-ease);
}

.nd-toast--success {
  border-left-color: var(--nd-success);
}

.nd-toast--warning {
  border-left-color: var(--nd-warning);
}

.nd-toast--danger {
  border-left-color: var(--nd-danger);
}

.nd-toast--info {
  border-left-color: var(--nd-info);
}

.nd-toast__title {
  font-size: var(--nd-text-12);
  font-weight: 500;
  color: var(--nd-text-primary);
}

.nd-toast__desc {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
  margin-top: 3px;
}

@keyframes nd-toast-in {
  from {
    transform: translateY(6px);
    opacity: 0;
  }
}

/* ---------- breadcrumbs / pagination ---------- */

.nd-crumbs {
  display: flex;
  align-items: center;
  gap: var(--nd-space-2);
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  min-width: 0;
}

.nd-crumbs__item {
  color: var(--nd-text-muted);
}

.nd-crumbs__item--current {
  color: color-mix(in srgb, var(--nd-text-secondary) 70%, var(--nd-accent-text));
  text-shadow: 0 0 12px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}

.nd-crumbs__link {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  color: var(--nd-text-muted);
}

.nd-crumbs__link:hover {
  color: var(--nd-accent-text);
}

.nd-crumbs__sep {
  color: color-mix(in srgb, var(--nd-text-muted) 70%, var(--nd-accent));
  opacity: 0.7;
}

.nd-pagination {
  display: flex;
  align-items: center;
  gap: 2px;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
}

.nd-pagebtn {
  min-width: 24px;
  height: 24px;
  padding: 0 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  border-radius: var(--nd-radius-sm);
  color: var(--nd-text-muted);
  cursor: pointer;
  font: inherit;
}

.nd-pagebtn:hover:not(:disabled) {
  color: var(--nd-text-primary);
  background: var(--nd-bg-raised);
}

.nd-pagebtn--current,
.nd-pagebtn--current:hover {
  color: var(--nd-accent-text);
  background: var(--nd-accent-subtle);
}

.nd-pagebtn:disabled {
  opacity: 0.4;
  cursor: default;
}

.nd-pagination__gap {
  color: var(--nd-text-muted);
  padding: 0 2px;
}

/* ---------- button ---------- */

.nd-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-family: var(--nd-font-body);
  font-weight: 600;
  font-size: var(--nd-text-12);
  border: 1px solid transparent;
  border-radius: var(--nd-radius-md);
  cursor: pointer;
  white-space: nowrap;
  transition:
    background var(--nd-duration-fast) var(--nd-ease),
    border-color var(--nd-duration-fast) var(--nd-ease),
    color var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease),
    transform var(--nd-duration-fast) var(--nd-ease);
}

.nd-btn--sm {
  height: 26px;
  padding: 0 10px;
  font-size: var(--nd-text-11);
}

.nd-btn--md {
  height: 32px;
  padding: 0 12px;
}

.nd-btn--lg {
  height: 38px;
  padding: 0 16px;
  font-size: var(--nd-text-14);
}

.nd-btn--primary {
  background: linear-gradient(180deg, var(--nd-accent-hover), var(--nd-accent));
  color: var(--nd-text-inverse);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.18) inset, 0 6px 16px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}

.nd-btn--primary:hover {
  background: linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 70%, white), var(--nd-accent-hover));
}

.nd-btn--primary:active {
  background: var(--nd-accent-active);
  transform: translateY(0.5px);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.1) inset;
}

.nd-btn--secondary {
  background: rgba(255, 255, 255, 0.02);
  border-color: var(--nd-border-default);
  color: var(--nd-text-primary);
}

.nd-btn--secondary:hover {
  border-color: var(--nd-border-strong);
  background: rgba(255, 255, 255, 0.04);
}

.nd-btn--ghost {
  background: transparent;
  color: var(--nd-text-secondary);
}

.nd-btn--ghost:hover {
  color: var(--nd-text-primary);
  background: rgba(255, 255, 255, 0.04);
}

/* Destructive actions. Outlined rather than filled: the weight matches the
   secondary button it sits beside, and the colour comes from the existing
   danger token pair — no new palette entry. */
.nd-btn--danger {
  background: transparent;
  border-color: var(--nd-danger);
  color: var(--nd-danger);
}

.nd-btn--danger:hover {
  background: var(--nd-danger-subtle);
}

.nd-btn--danger:active {
  background: var(--nd-danger-subtle);
  border-color: var(--nd-danger);
  color: var(--nd-danger);
}

.nd-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.nd-btn:focus-visible,
.nd-navitem:focus-visible,
.nd-seg__btn:focus-visible,
.nd-pagebtn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--nd-ring-color);
}

/* ---------- input / textarea / select ---------- */

.nd-input,
.nd-textarea,
.nd-select {
  width: 100%;
  background: var(--nd-bg-inset);
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-md);
  color: var(--nd-text-primary);
  font-family: var(--nd-font-body);
  font-size: var(--nd-text-12);
  outline: none;
  transition:
    border-color var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease);
}

.nd-input {
  padding: 0 10px;
}

.nd-input--sm {
  height: 26px;
}

.nd-input--md {
  height: 32px;
}

.nd-input--lg {
  height: 38px;
}

.nd-input--mono,
.nd-textarea--mono {
  font-family: var(--nd-font-mono);
}

.nd-input::placeholder,
.nd-textarea::placeholder {
  color: var(--nd-text-muted);
}

.nd-input:focus,
.nd-textarea:focus,
.nd-select:focus {
  border-color: var(--nd-accent);
  box-shadow: 0 0 0 2px var(--nd-ring-color);
}

.nd-input:disabled,
.nd-textarea:disabled,
.nd-select:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.nd-textarea {
  padding: 8px 10px;
  min-height: 72px;
  resize: vertical;
  line-height: 1.5;
}

.nd-select-wrap {
  position: relative;
  display: block;
  width: 100%;
}

.nd-select-wrap::after {
  content: "↓";
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--nd-text-muted);
  font-size: var(--nd-text-11);
  pointer-events: none;
}

.nd-select {
  appearance: none;
  -webkit-appearance: none;
  padding: 0 26px 0 10px;
}

.nd-select--sm {
  height: 26px;
}

.nd-select--md {
  height: 32px;
}

.nd-select--lg {
  height: 38px;
}

/* ---------- checkbox / switch / field ---------- */

.nd-checkbox {
  display: inline-flex;
  align-items: center;
  gap: var(--nd-space-2);
  cursor: pointer;
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
}

.nd-checkbox input {
  appearance: none;
  -webkit-appearance: none;
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
  margin: 0;
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-sm);
  background: var(--nd-bg-inset);
  position: relative;
  cursor: pointer;
}

.nd-checkbox input:checked {
  background: var(--nd-accent);
  border-color: var(--nd-accent);
}

.nd-checkbox input:checked::after {
  content: "";
  position: absolute;
  left: 4px;
  top: 1px;
  width: 4px;
  height: 8px;
  border: solid var(--nd-text-inverse);
  border-width: 0 1.5px 1.5px 0;
  transform: rotate(45deg);
}

.nd-checkbox input:focus-visible {
  box-shadow: 0 0 0 2px var(--nd-ring-color);
}

.nd-switch {
  display: inline-flex;
  align-items: center;
  gap: var(--nd-space-2);
  cursor: pointer;
}

.nd-switch--disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.nd-switch__track {
  position: relative;
  width: 28px;
  height: 16px;
  flex: 0 0 auto;
  padding: 0;
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-full);
  background: var(--nd-bg-inset);
  cursor: pointer;
  transition:
    background var(--nd-duration-fast) var(--nd-ease),
    border-color var(--nd-duration-fast) var(--nd-ease);
}

.nd-switch__track--sm {
  width: 24px;
  height: 14px;
}

.nd-switch__knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 10px;
  height: 10px;
  border-radius: var(--nd-radius-full);
  background: var(--nd-text-muted);
  transition:
    transform var(--nd-duration-fast) var(--nd-ease),
    background var(--nd-duration-fast) var(--nd-ease);
}

.nd-switch__track--sm .nd-switch__knob {
  width: 8px;
  height: 8px;
}

.nd-switch__track--on {
  background: var(--nd-accent);
  border-color: var(--nd-accent);
  box-shadow: 0 0 14px color-mix(in srgb, var(--nd-accent) 35%, transparent);
}

.nd-switch__track--on .nd-switch__knob {
  transform: translateX(12px);
  background: var(--nd-text-inverse);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--nd-bg-canvas) 50%, transparent);
}

.nd-switch__track:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--nd-accent) 55%, transparent);
  outline-offset: 2px;
}

.nd-switch__track--sm.nd-switch__track--on .nd-switch__knob {
  transform: translateX(10px);
}

.nd-switch__label {
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
}

.nd-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.nd-field__help {
  font-family: var(--nd-font-body);
  font-size: 11.5px;
  color: var(--nd-text-muted);
}

/* ---------- drawer ---------- */

.nd-drawer-root {
  position: fixed;
  inset: 0;
  z-index: var(--nd-z-overlay);
}

.nd-drawer-overlay {
  position: absolute;
  inset: 0;
  background: var(--nd-overlay-scrim);
  animation: nd-fade var(--nd-duration-base) var(--nd-ease);
}

.nd-drawer {
  position: absolute;
  top: 0;
  bottom: 0;
  width: var(--nd-overlay-w, 440px);
  max-width: 100vw;
  display: flex;
  flex-direction: column;
  background: color-mix(in srgb, var(--nd-bg-surface) 94%, transparent);
  backdrop-filter: blur(16px) saturate(1.12);
  -webkit-backdrop-filter: blur(16px) saturate(1.12);
  box-shadow:
    var(--nd-shadow-overlay),
    0 0 40px color-mix(in srgb, var(--nd-accent) 8%, transparent);
  animation: nd-slide var(--nd-duration-base) var(--nd-ease);
}

.nd-drawer--right {
  right: 0;
  border-left: 1px solid color-mix(in srgb, var(--nd-border-default) 70%, var(--nd-accent) 30%);
}

.nd-drawer--left {
  left: 0;
  border-right: 1px solid var(--nd-border-default);
  animation-name: nd-slide-left;
}

.nd-drawer__header {
  padding: 20px 24px 16px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border-subtle) 80%, var(--nd-accent) 20%);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--nd-accent) 6%, transparent),
    transparent 70%
  );
}

.nd-drawer__header > div:first-child {
  min-width: 0;
  overflow-wrap: anywhere;
}

.nd-drawer__title {
  font-family: var(--nd-font-display);
  font-size: var(--nd-text-18);
  color: var(--nd-text-primary);
  line-height: 1.25;
}

.nd-drawer__close {
  border: 0;
  background: none;
  color: var(--nd-text-secondary);
  cursor: pointer;
  font-size: 24px;
  line-height: 1;
  padding: 0 2px;
}

.nd-drawer__close:hover,
.nd-drawer__close:focus-visible {
  color: var(--nd-text-primary);
}

.nd-drawer__description {
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
  line-height: 1.5;
  margin-top: 4px;
}

.nd-drawer__body {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 20px 24px 32px;
}

@keyframes nd-fade {
  from {
    opacity: 0;
  }
}

@keyframes nd-slide {
  from {
    transform: translateX(24px);
    opacity: 0.6;
  }
}

@keyframes nd-slide-left {
  from {
    transform: translateX(-24px);
    opacity: 0.6;
  }
}

/* ---------- segmented control ---------- */

.nd-seg {
  display: inline-flex;
  gap: 4px;
  padding: 3px;
  border: 1px solid color-mix(in srgb, var(--nd-border-subtle) 80%, var(--nd-accent) 20%);
  border-radius: var(--nd-radius-md);
  background: color-mix(in srgb, var(--nd-bg-surface) 70%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 6%, transparent);
}

.nd-seg__btn {
  height: 24px;
  padding: 0 11px;
  display: inline-flex;
  align-items: center;
  background: transparent;
  border: none;
  border-radius: var(--nd-radius-sm);
  font-family: var(--nd-font-mono);
  font-weight: 500;
  font-size: 10.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  cursor: pointer;
  transition:
    background var(--nd-duration-fast) var(--nd-ease),
    color var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease);
}

.nd-seg__btn:hover {
  color: var(--nd-text-secondary);
}

.nd-seg__btn--active,
.nd-seg__btn--active:hover {
  color: var(--nd-accent-text);
  background: var(--nd-accent-subtle);
  box-shadow: 0 0 12px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}

/* -- sidebar chrome ------------------------------------------------------- */

.nt-shell-brand {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--nd-space-2);
  padding: 0 8px;
}

.nt-shell-brand__kicker {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.18em;
  color: var(--nd-accent-text);
  text-transform: uppercase;
}

.nt-shell-brand__name {
  font-family: var(--nd-font-display);
  font-weight: 600;
  font-size: 17px;
  letter-spacing: -0.02em;
  color: var(--nd-text-primary);
  line-height: 1.15;
  margin-top: 2px;
  white-space: nowrap;
}

.nt-shell-rail-toggle {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  margin-top: 1px;
  border: 1px solid transparent;
  border-radius: var(--nd-radius-md);
  background: none;
  color: var(--nd-text-muted);
  cursor: pointer;
  transition:
    color var(--nd-duration-fast) var(--nd-ease),
    background var(--nd-duration-fast) var(--nd-ease);
}

.nt-shell-rail-toggle:hover {
  color: var(--nd-text-primary);
  background: var(--nd-bg-raised);
}

.nt-shell-navgroup {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.nt-shell-navgroup__label {
  padding: 0 8px 2px;
}

.nd-navitem__icon {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  color: var(--nd-text-muted);
}

.nd-navitem:hover .nd-navitem__icon,
.nd-navitem--active .nd-navitem__icon {
  color: inherit;
}

.nd-navitem__label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nt-shell-workspace {
  margin-top: auto;
  padding: 10px 8px 0;
  border-top: 1px solid var(--nd-border-subtle);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nt-shell-workspace__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.nt-shell-workspace__name {
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nt-shell-workspace__tag,
.nt-shell-workspace__linked {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
}

/* -- collapsed rail -------------------------------------------------------
   Twelve destinations never fill a 100vh column, so the sidebar can hand ~185px
   back to the table the operator is actually reading. Every control keeps its
   accessible name (set on the button, not the hidden label), so collapsing
   changes the presentation only. */

.nd-shell--rail .nd-shell__sidebar {
  --nd-sidebar-w: 52px;
  padding-inline: 6px;
  align-items: stretch;
  overflow: visible;
}

.nd-shell--rail .nd-navitem__label,
.nd-shell--rail .nt-shell-brand__copy,
.nd-shell--rail .nt-shell-navgroup__label,
.nd-shell--rail .nt-shell-workspace__name,
.nd-shell--rail .nt-shell-workspace__linked,
.nd-shell--rail .nt-shell-workspace .nd-micro-label {
  display: none;
}

.nd-shell--rail .nt-shell-brand {
  justify-content: center;
  padding: 0;
}

.nd-shell--rail .nd-navitem {
  justify-content: center;
  padding: 7px 0;
}

.nd-shell--rail .nt-shell-navgroup {
  gap: 3px;
  padding-top: 6px;
  border-top: 1px solid var(--nd-border-subtle);
}

.nd-shell--rail .nt-shell-navgroup:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.nd-shell--rail .nt-shell-workspace {
  align-items: center;
  padding: 10px 0 0;
}

.nd-shell--rail .nt-shell-workspace__row {
  justify-content: center;
}

/* ---------- NightDesk 2.0 overlays, shift strip, skeletons ---------- */

.nd-heading--2 {
  font-size: var(--nd-text-26);
}

.nd-badge--plane {
  color: var(--nd-text-secondary);
  background: var(--nd-neutral-subtle);
  border-color: var(--nd-border-default);
  font-family: var(--nd-font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.nd-shell__topbar {
  z-index: var(--nd-z-topbar);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 6%, transparent), transparent 72%),
    var(--nd-bg-glass);
  backdrop-filter: blur(18px) saturate(1.3);
  -webkit-backdrop-filter: blur(18px) saturate(1.3);
  border-bottom-color: color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border-subtle));
  box-shadow:
    0 1px 0 color-mix(in srgb, var(--nd-accent) 10%, transparent),
    0 14px 32px rgba(0, 0, 0, 0.22);
}

.nd-shell__sidebar {
  box-shadow: 1px 0 0 rgba(255, 255, 255, 0.02), 8px 0 32px rgba(0, 0, 0, 0.18);
}

/* Shift strip — global trust chrome */
.nt-shift-strip {
  position: sticky;
  top: 0;
  z-index: var(--nd-z-shift);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  min-height: var(--nd-shift-h);
  padding: 6px var(--nd-content-pad-x);
  border-bottom: 1px solid var(--nd-border-subtle);
  border-bottom-color: color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
  background:
    linear-gradient(180deg, color-mix(in srgb, color-mix(in srgb, var(--nd-bg-canvas) 82%, var(--nd-accent) 18%) 88%, var(--nd-accent)), color-mix(in srgb, var(--nd-bg-canvas) 94%, transparent));
  box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--nd-accent) 8%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
/* Bleed to content edges so the strip reads as shell chrome, not a page card */
.nd-shell__content > .nt-shift-strip {
  margin: calc(var(--nd-content-pad-y) * -1) calc(var(--nd-content-pad-x) * -1) var(--nd-space-3);
  width: calc(100% + (var(--nd-content-pad-x) * 2));
  max-width: none;
}

.nt-shift-strip__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: var(--nd-tracking-label);
  text-transform: uppercase;
  color: var(--nd-text-secondary);
  padding: 3px 8px;
  border-radius: var(--nd-radius-full);
  border: 1px solid var(--nd-border-subtle);
  background: rgba(255, 255, 255, 0.02);
  cursor: default;
}
button.nt-shift-strip__chip {
  appearance: none;
  font: inherit;
  color: inherit;
  line-height: inherit;
  cursor: pointer;
  transition:
    border-color 120ms ease,
    background 120ms ease,
    box-shadow 120ms ease;
}
button.nt-shift-strip__chip:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-raised) 88%, var(--nd-accent));
}
button.nt-shift-strip__chip:focus-visible {
  outline: 2px solid var(--nd-accent);
  outline-offset: 2px;
}

.nt-shift-strip__chip--accent {
  color: var(--nd-accent-text);
  border-color: var(--nd-border-glow);
  background: var(--nd-accent-subtle);
  box-shadow: 0 0 16px var(--nd-glow);
}

.nt-shift-strip__chip--danger {
  color: var(--nd-danger);
  border-color: rgba(255, 111, 122, 0.35);
  background: var(--nd-danger-subtle);
}

.nt-shift-strip__chip--warning {
  color: var(--nd-warning);
  border-color: rgba(240, 195, 74, 0.3);
  background: var(--nd-warning-subtle);
}

.nt-shift-strip__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex: 0 0 auto;
}

.nt-shift-strip__spacer {
  flex: 1 1 auto;
  min-width: 8px;
}

.nt-shift-strip__meta {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* Incident spine strip */
.nt-incident-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  margin: 0 0 var(--nd-block-gap);
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--nd-danger) 34%, var(--nd-border-subtle));
  border-radius: var(--nd-radius-md);
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nd-danger) 18%, transparent), transparent 62%),
    linear-gradient(180deg, color-mix(in srgb, var(--nd-bg-raised) 88%, var(--nd-danger) 12%), color-mix(in srgb, var(--nd-bg-canvas) 92%, transparent));
  box-shadow:
    var(--nd-shadow-glow),
    inset 0 1px 0 color-mix(in srgb, var(--nd-danger) 18%, transparent);
  animation: nt-incident-wake 420ms var(--nd-ease, ease) both;
}
@keyframes nt-incident-wake {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .nt-incident-strip {
    animation: none;
  }
}

.nt-incident-strip__label {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-accent-text);
}

.nt-incident-strip__title {
  font-size: var(--nd-text-12);
  color: var(--nd-text-primary);
  min-width: 0;
}

.nt-incident-strip__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-left: auto;
}

/* Page skeletons */
.nd-page-skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--nd-screen-gap);
  padding-top: 4px;
  animation: nd-skeleton-in var(--nd-duration-slow) var(--nd-ease);
}

@keyframes nd-skeleton-in {
  from {
    opacity: 0.2;
    filter: saturate(0.7);
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    filter: none;
    transform: none;
  }
}

.nd-page-skeleton__header {
  display: flex;
  justify-content: space-between;
  gap: var(--nd-space-4);
  padding-bottom: 10px;
  border-bottom: 1px solid var(--nd-border-subtle);
}

.nd-page-skeleton__stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: var(--nd-space-3);
}

.nd-page-skeleton__row {
  height: var(--nd-row-h);
  border-radius: var(--nd-radius-md);
}

.nd-page-skeleton__grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: var(--nd-space-4);
}

@media (max-width: 900px) {
  .nd-page-skeleton__stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .nd-page-skeleton__grid {
    grid-template-columns: 1fr;
  }
}

/* Modal */
.nd-modal-root {
  position: fixed;
  inset: 0;
  z-index: var(--nd-z-overlay);
  display: grid;
  place-items: center;
  padding: 24px;
}

.nd-modal__scrim {
  position: absolute;
  inset: 0;
  border: 0;
  background: var(--nd-overlay-scrim);
  cursor: pointer;
}

.nd-modal {
  position: relative;
  z-index: 1;
  max-width: min(92vw, 560px);
  width: var(--nd-overlay-w, 100%);
  border: 1px solid color-mix(in srgb, var(--nd-border-default) 75%, var(--nd-accent) 25%);
  border-radius: var(--nd-radius-lg);
  background: color-mix(in srgb, var(--nd-bg-raised) 92%, transparent);
  backdrop-filter: blur(18px) saturate(1.12);
  -webkit-backdrop-filter: blur(18px) saturate(1.12);
  box-shadow: var(--nd-shadow-overlay), var(--nd-shadow-glow);

  padding: 18px 20px;
  animation: nd-fade var(--nd-duration-base) var(--nd-ease);
}

.nd-modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.nd-modal__title {
  font-size: var(--nd-text-16);
  font-weight: 600;
  color: var(--nd-text-primary);
}

.nd-modal__desc {
  margin-top: 6px;
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
  line-height: 1.45;
}

.nd-modal__close {
  border: 0;
  background: none;
  color: var(--nd-text-muted);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  padding: 0 4px;
}

.nd-modal__close:hover {
  color: var(--nd-text-primary);
}

.nd-modal__body {
  margin-top: 14px;
}

.nd-modal__footer {
  margin-top: 18px;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* Tooltip */
.nd-tooltip {
  position: relative;
  display: inline-flex;
}

.nd-tooltip__bubble {
  position: absolute;
  z-index: var(--nd-z-dropdown);
  left: 50%;
  transform: translateX(-50%);
  max-width: 240px;
  padding: 6px 8px;
  border-radius: var(--nd-radius-md);
  border: 1px solid var(--nd-border-default);
  background: var(--nd-bg-raised);
  box-shadow: var(--nd-shadow-raised);
  color: var(--nd-text-secondary);
  font-size: var(--nd-text-11);
  line-height: 1.35;
  white-space: normal;
  pointer-events: none;
}

.nd-tooltip__bubble--top {
  bottom: calc(100% + 6px);
}

.nd-tooltip__bubble--bottom {
  top: calc(100% + 6px);
}

/* Tabs */
.nd-tabs__list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 3px;
  border: 1px solid var(--nd-border-subtle);
  border-radius: var(--nd-radius-md);
  background: rgba(255, 255, 255, 0.02);
  width: fit-content;
  max-width: 100%;
}

.nd-tabs__trigger {
  height: 28px;
  padding: 0 12px;
  border: 0;
  border-radius: var(--nd-radius-sm);
  background: transparent;
  color: var(--nd-text-muted);
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
}

.nd-tabs__trigger:hover {
  color: var(--nd-text-secondary);
}

.nd-tabs__trigger--active,
.nd-tabs__trigger--active:hover {
  color: var(--nd-accent-text);
  background: var(--nd-accent-subtle);
}

.nd-tabs__content {
  margin-top: var(--nd-space-4);
}

/* Menu */
.nd-menu {
  position: relative;
  display: inline-flex;
}

.nd-menu__trigger {
  display: inline-flex;
}

.nd-menu__panel {
  position: absolute;
  top: calc(100% + 6px);
  z-index: var(--nd-z-dropdown);
  width: var(--nd-overlay-w, auto);
  padding: 4px;
  border-radius: var(--nd-radius-md);
  border: 1px solid var(--nd-border-default);
  background: var(--nd-bg-raised);
  box-shadow: var(--nd-shadow-overlay);
}

.nd-menu__panel--end {
  right: 0;
}

.nd-menu__panel--start {
  left: 0;
}

.nd-menu__item {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--nd-radius-sm);
  background: transparent;
  color: var(--nd-text-primary);
  font-size: var(--nd-text-12);
  text-align: left;
  cursor: pointer;
}

.nd-menu__item:hover:not(:disabled) {
  background: var(--nd-bg-hover, var(--nd-bg-surface));
}

.nd-menu__item--danger {
  color: var(--nd-danger);
}

.nd-menu__item:disabled {
  opacity: var(--nd-opacity-disabled);
  cursor: default;
}

.nd-menu__sep {
  height: 1px;
  margin: 4px 6px;
  background: var(--nd-border-subtle);
}

/* Brand polish */
.nt-shell-brand__kicker {
  color: var(--nd-accent-text);
  letter-spacing: 0.16em;
}

.nt-shell-brand__tagline {
  margin-top: 2px;
  font-family: var(--nd-font-mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-faint);
}

.nt-shell-navgroup__toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  border: 0;
  background: none;
  padding: 0 8px 2px;
  cursor: pointer;
  color: inherit;
}

.nt-shell-navgroup__toggle:hover .nd-micro-label {
  color: var(--nd-text-secondary);
}

.nt-shell-navgroup--collapsed .nt-shell-navgroup__items {
  display: none;
}

.nd-table-scroll--virtual {
  max-height: min(70vh, 820px);
  overflow: auto;
}

/* Auth gate on-system panel */
.nt-auth-panel {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(800px 420px at 80% -10%, color-mix(in srgb, var(--nd-accent) 14%, transparent), transparent 55%),
    var(--nd-bg-canvas);
  padding: 32px;
}

.nt-auth-card {
  max-width: 460px;
  width: 100%;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border-default));
  background:
    radial-gradient(90% 70% at 10% 0%, color-mix(in srgb, var(--nd-accent) 12%, transparent), transparent 55%),
    linear-gradient(180deg, color-mix(in srgb, var(--nd-bg-raised) 92%, color-mix(in srgb, var(--nd-bg-canvas) 82%, var(--nd-accent) 18%)), var(--nd-bg-surface));
  box-shadow:
    var(--nd-shadow-overlay),
    var(--nd-shadow-glow),
    0 0 40px color-mix(in srgb, var(--nd-accent) 12%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 14%, transparent);
  border-radius: var(--nd-radius-lg);
  padding: 28px 32px;
  backdrop-filter: blur(12px);
}

.nt-auth-card__eyebrow {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--nd-accent-text);
  text-shadow: 0 0 16px color-mix(in srgb, var(--nd-accent) 30%, transparent);
}

.nt-auth-card__title {
  margin: 10px 0 0;
  font-size: var(--nd-text-22);
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--nd-text-primary);
}

.nt-auth-card__body {
  margin-top: 10px;
  font-size: var(--nd-text-13, var(--nd-text-12));
  color: var(--nd-text-secondary);
  line-height: 1.5;
}

.nt-note {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
  line-height: 1.45;
}


/* ---------- NightDesk utilities (inline burn) ---------- */
.nt-stack {
  display: flex;
  flex-direction: column;
  gap: var(--nd-block-gap);
}
.nt-stack--tight { gap: 8px; }
.nt-stack--loose { gap: 22px; }
.nt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.nt-row--end { align-items: flex-end; }
.nt-mono {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
}
.nt-mono-label {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: var(--nd-tracking-label);
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
.nt-body-sm {
  font-size: var(--nd-text-13);
  color: var(--nd-text-primary);
  line-height: 1.4;
}
.nt-muted {
  font-size: var(--nd-text-12);
  color: var(--nd-text-muted);
}
.nt-filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
  padding: 10px 12px 8px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 8%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 4%, transparent), transparent 80%),
    color-mix(in srgb, var(--nd-bg-surface) 40%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nt-filter-bar__count {
  margin-left: auto;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: color-mix(in srgb, var(--nd-text-muted) 80%, var(--nd-accent-text));
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding-bottom: 8px;
}

/* Empty states — less shrug, more instrument */
.nd-empty {
  border: 1px dashed var(--nd-border-default);
  border-radius: var(--nd-radius-lg);
  background:
    radial-gradient(420px 180px at 20% 0%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 60%),
    rgba(255, 255, 255, 0.015);
  padding: 28px 22px;
  text-align: left;
}
.nd-empty__title {
  font-size: var(--nd-text-14);
  font-weight: 600;
  color: var(--nd-text-primary);
  letter-spacing: -0.01em;
}
.nd-empty__desc {
  margin-top: 6px;
  max-width: 42ch;
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
  line-height: 1.5;
}

/* Shift strip ECG pulse */
.nt-shift-strip__dot--live {
  box-shadow: 0 0 0 0 currentColor;
  animation: nt-ecg-pulse 2.2s var(--nd-ease) infinite;
}
.nt-shift-strip__chip--danger .nt-shift-strip__dot,
.nt-shift-strip__chip--warning .nt-shift-strip__dot {
  animation: nt-ecg-pulse 1.4s var(--nd-ease) infinite;
}
@keyframes nt-ecg-pulse {
  0% { box-shadow: 0 0 0 0 color-mix(in srgb, currentColor 55%, transparent); }
  70% { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@media (prefers-reduced-motion: reduce) {
  .nt-shift-strip__dot--live,
  .nt-shift-strip__chip--danger .nt-shift-strip__dot,
  .nt-shift-strip__chip--warning .nt-shift-strip__dot {
    animation: none;
  }
}

/* ⌘K cinema */
.nt-global-search {
  position: relative;
  margin-left: auto;
  width: min(420px, 100%);
}
.nt-global-search__field {
  padding-right: 74px !important;
}
.nt-global-search__hotkeys {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  gap: 4px;
  align-items: center;
  pointer-events: none;
  z-index: 1;
}
.nt-global-search__panel {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  z-index: var(--nd-z-dropdown);
  padding: 8px;
  max-height: min(420px, 70vh);
  overflow: auto;
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-lg);
  background: var(--nd-bg-glass-strong);
  backdrop-filter: blur(18px) saturate(1.2);
  -webkit-backdrop-filter: blur(18px) saturate(1.2);
  box-shadow: var(--nd-shadow-overlay), 0 0 40px color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-global-search__hint {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 6px 8px 10px;
  border-bottom: 1px solid var(--nd-border-subtle);
  margin-bottom: 6px;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
/* Loop 189 — recent multi-select bulk bar beside replay hits. */
.nt-global-search__recent-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.nt-global-search__recent-row > .nt-global-search__hit {
  flex: 1;
  min-width: 0;
}
.nt-global-search__recent-bulk {
  margin-top: 6px;
}
.nt-global-search__hit {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  background: none;
  border: none;
  text-align: left;
  padding: 8px 10px;
  border-radius: var(--nd-radius-md);
  cursor: pointer;
  color: var(--nd-text-primary);
}
.nt-global-search__hit:hover,
.nt-global-search__hit--active {
  background: linear-gradient(90deg, var(--nd-accent-subtle), transparent 80%);
  box-shadow: inset 2px 0 0 var(--nd-accent);
}
.nt-global-search__kind {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.1em;
  color: var(--nd-text-muted);
  width: 56px;
  flex: 0 0 56px;
  text-transform: uppercase;
}
.nt-global-search__label {
  font-size: var(--nd-text-13);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nt-global-search__meta {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
  max-width: 38%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nt-global-search__empty {
  padding: 14px 10px;
  font-size: var(--nd-text-12);
  color: var(--nd-text-muted);
  font-family: var(--nd-font-display);
  font-style: italic;
  line-height: 1.45;
}
.nt-global-search__warn {
  padding: 8px 10px;
  margin-top: 4px;
  border-top: 1px solid var(--nd-border-subtle);
  font-size: var(--nd-text-11);
  color: var(--nd-warning);
  font-family: var(--nd-font-display);
}

/* Topbar identity */
.nt-shell-identity {
  position: relative;
  padding-left: 14px;
}
.nt-shell-identity::before {
  content: '';
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 1px;
  background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--nd-accent) 45%, transparent), transparent);
}
.nt-shell-identity {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-left: 10px;
  border-left: 1px solid var(--nd-border-subtle);
}
.nt-shell-identity__text {
  text-align: right;
  line-height: 1.25;
}
.nt-shell-identity__name {
  font-size: var(--nd-text-12);
  color: var(--nd-text-primary);
}
.nt-shell-identity__meta {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.nt-shell-assistant {
  color: var(--nd-text-secondary);
}
.nt-shell-assistant:hover {
  color: var(--nd-text-primary);
}
.nt-shell-settings-error {
  max-width: 260px;
  color: var(--nd-danger);
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
}

/* Tickets workspace */
.nt-tickets {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.nt-tickets__grid {
  display: grid;
  grid-template-columns: minmax(260px, 300px) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}
@media (max-width: 900px) {
  .nt-tickets__grid { grid-template-columns: 1fr; }
}
.nt-tickets__queue {
  display: flex;
  flex-direction: column;
  gap: 2px;
  border: 1px solid var(--nd-border-subtle);
  border-radius: var(--nd-radius-md);
  background: rgba(255,255,255,0.015);
  overflow: hidden;
}
.nt-tickets__queue-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
  text-align: left;
  border: 0;
  border-left: 2px solid transparent;
  background: transparent;
  color: inherit;
  padding: 12px 12px 12px 14px;
  cursor: pointer;
}
.nt-tickets__queue-item:hover {
  background: var(--nd-bg-hover);
}
.nt-tickets__queue-item--active {
  border-left-color: var(--nd-accent);
  background: var(--nd-bg-raised);
}
.nt-tickets__workspace {
  display: flex;
  flex-direction: column;
  gap: 22px;
  min-width: 0;
}
.nt-tickets__meta-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px 14px;
}
@media (max-width: 760px) {
  .nt-tickets__meta-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
.nt-tickets__meta-k {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
.nt-tickets__meta-v {
  margin-top: 3px;
  font-size: var(--nd-text-13);
  color: var(--nd-text-secondary);
}
.nt-tickets__evidence {
  display: flex;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--nd-border-subtle);
}
.nt-tickets__evidence-time {
  width: 88px;
  flex: 0 0 88px;
  padding-top: 1px;
}
.nt-tickets__evidence-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.nt-tickets__evidence-raw {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
  line-height: 1.4;
}


/* ---------- NightDesk focus floor ---------- */
:where(a, button, input, select, textarea, [role="button"], [tabindex]:not([tabindex="-1"])):focus {
  outline: none;
}
:where(a, button, input, select, textarea, [role="button"], [tabindex]:not([tabindex="-1"])):focus-visible {
  outline: 2px solid var(--nd-ring-color);
  outline-offset: 2px;
}
.nd-input:focus-visible,
.nd-textarea:focus-visible,
.nd-select:focus-visible {
  border-color: var(--nd-accent);
  box-shadow: 0 0 0 3px var(--nd-accent-subtle);
  outline: none;
}

/* Content canvas subtle vignette — depth without noise */
.nd-shell__content {
  background:
    radial-gradient(900px 420px at 100% 0%, color-mix(in srgb, var(--nd-accent) 5%, transparent), transparent 55%),
    var(--nd-bg-canvas);
}


/* ---------- Wave 3: panels, alerts, NOC wall ---------- */
.nt-panel {
  border: 1px solid color-mix(in srgb, var(--nd-border-default) 82%, var(--nd-accent) 18%);
  border-radius: var(--nd-radius-md);
  background: color-mix(in srgb, var(--nd-bg-raised) 94%, transparent);
  box-shadow:
    var(--nd-shadow-sm),
    inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 7%, transparent);
  overflow: hidden;
}
.nt-panel__head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
  padding: 10px 14px;
  border-bottom: 1px solid var(--nd-border-default);
  background: linear-gradient(180deg, rgba(255,255,255,0.02), transparent);
}
.nt-panel__title {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-secondary);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.nt-panel__hint {
  font-size: var(--nd-text-12);
  color: var(--nd-text-muted);
}
.nt-panel__actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
}
.nt-panel__note {
  padding: 8px 14px;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
  border-bottom: 1px solid var(--nd-border-default);
}
.nt-panel__row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 8px 14px;
  border-bottom: 1px solid var(--nd-border-subtle);
}
.nt-panel__row:last-child {
  border-bottom: 0;
}
.nt-panel__empty {
  padding: 10px 14px;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
}

.nt-alerts {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.nt-alerts__toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding-bottom: 4px;
}
.nt-alerts__count {
  margin-left: auto;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
}
.nt-alerts__ack {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  padding: 12px 14px;
  border: 1px solid var(--nd-border-glow);
  border-radius: var(--nd-radius-md);
  background: linear-gradient(90deg, var(--nd-accent-subtle), var(--nd-bg-raised) 55%);
  box-shadow: var(--nd-shadow-glow);
}
.nt-alerts__tabs {
  margin-top: 2px;
}
.nt-alerts .nd-tabs__list {
  margin-bottom: 14px;
}

.nt-configure {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.nt-configure__col {
  display: flex;
  flex-direction: column;
  gap: 26px;
  min-width: 0;
}
.nt-configure__queue {
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-lg);
  background: var(--nd-bg-raised);
  box-shadow: var(--nd-shadow-raised), 0 0 28px color-mix(in srgb, var(--nd-accent) 6%, transparent);
  padding: 14px;
}
.nt-configure__queue-title {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-accent-text);
  margin-bottom: 8px;
}

/* NOC wall — larger type/rows for shared displays */
html.nd-noc-wall {
  --nd-text-10: 11px;
  --nd-text-11: 12.5px;
  --nd-text-12: 14px;
  --nd-text-13: 15px;
  --nd-text-14: 16px;
  --nd-text-16: 18px;
  --nd-row-h: 46px;
  --nd-row-pad-y: 10px;
  --nd-topbar-h: 56px;
  --nd-shift-h: 38px;
  --nd-content-pad-y: 24px;
}
html.nd-noc-wall .nd-shell__content {
  background:
    radial-gradient(1000px 480px at 100% 0%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 55%),
    var(--nd-bg-canvas);
}


/* ---------- Wave 4: clients chips, filter fields, drawer stack, freshness ---------- */
.nt-chip-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}
.nt-chip-row__label {
  font-size: var(--nd-text-11);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
.nt-chip {
  background: none;
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-sm, 4px);
  padding: 2px 8px;
  cursor: pointer;
  display: inline-flex;
  gap: 6px;
  align-items: center;
  color: inherit;
  font: inherit;
  transition: background 120ms ease, border-color 120ms ease, box-shadow 120ms ease;
}
.nt-chip:hover {
  border-color: var(--nd-border-strong, var(--nd-border-default));
  background: var(--nd-bg-inset);
}
.nt-chip--active {
  background: var(--nd-bg-inset);
  border-color: var(--nd-border-glow, var(--nd-accent));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}
.nt-chip__count {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-text-muted);
}
.nt-filter-field {
  min-width: 0;
}
.nt-filter-field--sm { width: 150px; }
.nt-filter-field--md { width: 160px; }
.nt-filter-field--lg { width: 190px; }
.nt-filter-field--xl { width: 230px; }

.nt-drawer-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.nt-drawer-stack--tight {
  gap: 12px;
}
.nt-drawer-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.nt-shift-strip__fresh {
  font-variant-numeric: tabular-nums;
}
.nt-shift-strip__chip--ok .nt-shift-strip__dot {
  color: var(--nd-success);
  background: var(--nd-success);
}
.nt-systems__lower-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 28px;
  align-items: start;
}
@media (max-width: 960px) {
  .nt-systems__lower-grid {
    grid-template-columns: 1fr;
  }
  .nt-filter-field--xl,
  .nt-filter-field--lg,
  .nt-filter-field--md,
  .nt-filter-field--sm {
    width: 100%;
    max-width: 280px;
  }
}


.nt-overview__layout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: 34px;
  align-items: start;
}
@media (max-width: 960px) {
  .nt-overview__layout {
    grid-template-columns: 1fr;
  }
}
.nt-overview .nt-plane-mini {
  border-radius: var(--nd-radius-md);
  transition: box-shadow 160ms ease, border-color 160ms ease;
}
.nt-overview .nt-plane-mini:hover {
  box-shadow: var(--nd-shadow-sm), 0 0 20px color-mix(in srgb, var(--nd-accent) 8%, transparent);
  border-color: var(--nd-border-glow, var(--nd-border-default));
}
.nt-overview .nd-stat-row,
.nt-overview .nt-stat-grid {
  filter: drop-shadow(0 10px 28px rgba(0, 0, 0, 0.22));
}

.nt-health-bar {
  width: 64px;
  height: 3px;
  background: var(--nd-bg-inset);
  border-radius: 99px;
  overflow: hidden;
}
.nt-health-bar__fill {
  height: 3px;
  border-radius: 99px;
}
.nt-linkish {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font-family: var(--nd-font-body);
  font-size: var(--nd-text-12);
  color: var(--nd-text-primary);
  text-align: left;
}
.nt-linkish:hover {
  color: var(--nd-accent-text);
}


/* copper empty elevation */
.nd-empty {
  border: 1px solid var(--nd-border-default);
  border-radius: var(--nd-radius-lg);
  background:
    radial-gradient(520px 180px at 20% 0%, color-mix(in srgb, var(--nd-accent) 7%, transparent), transparent 60%),
    var(--nd-bg-raised);
  box-shadow: var(--nd-shadow-sm);
  padding: 28px 22px;
}
.nd-empty__title {
  letter-spacing: -0.01em;
}

.nt-tickets__id {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
  color: var(--nd-accent-text);
}
.nt-tickets__age,
.nt-tickets__site {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
}
.nt-tickets__title {
  font-size: var(--nd-text-13);
  color: var(--nd-text-primary);
  line-height: 1.35;
}
.nt-tickets__meta-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  padding: 14px 0;
  border-top: 1px solid var(--nd-border-subtle);
  border-bottom: 1px solid var(--nd-border-subtle);
}
.nt-tickets__meta-k {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
.nt-tickets__sla {
  margin-left: auto;
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11);
}
.nt-tickets__sla--open { color: var(--nd-warning); }
.nt-tickets__sla--done { color: var(--nd-text-muted); }
@media (max-width: 900px) {
  .nt-tickets__meta-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

.nt-fact-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.nt-fact-grid__k {
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
}
.nt-metric-tile {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.nt-metric-tile__k {
  font-family: var(--nd-font-mono);
  font-size: 9.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
.nt-metric-tile__v {
  font-family: var(--nd-font-mono);
  font-size: 15px;
  color: var(--nd-text-primary);
}
.nt-metric-tile__v[data-warn="true"] {
  color: var(--nd-warning);
}
.nt-metric-tile__note {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  color: var(--nd-text-muted);
}

.nt-fact-row {
  display: flex;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--nd-border-subtle);
}
.nt-fact-row__k {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-10);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  width: 92px;
  flex: 0 0 92px;
  padding-top: 2px;
}
.nt-fact-row__k--wide {
  width: 104px;
  flex: 0 0 104px;
  font-size: 9.5px;
  letter-spacing: 0.12em;
}
.nt-fact-row__v {
  flex: 1;
  min-width: 0;
  font-family: var(--nd-font-mono);
  font-size: 11.5px;
  color: var(--nd-text-secondary);
  overflow-wrap: anywhere;
}
.nt-btn-danger-ghost {
  color: var(--nd-danger) !important;
}
.nt-btn-danger-ghost:hover {
  background: color-mix(in srgb, var(--nd-danger) 12%, transparent) !important;
}

.nt-plane-mini--ecg {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--nd-warning) 75%, transparent);
  animation: nt-ecg-glow 2.4s ease-in-out infinite;
}
@keyframes nt-ecg-glow {
  0%, 100% { background-color: transparent; }
  50% { background-color: color-mix(in srgb, var(--nd-warning) 8%, transparent); }
}
@media (prefers-reduced-motion: reduce) {
  .nt-plane-mini--ecg { animation: none; }
}
.nt-launchpad-row {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  background: none;
  border: none;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 8%, var(--nd-border-subtle));
  border-left: 2px solid transparent;
  padding: 10px 8px;
  cursor: pointer;
  text-align: left;
  color: inherit;
  border-radius: 0 var(--nd-radius-sm) var(--nd-radius-sm) 0;
  transition:
    background var(--nd-duration-fast) var(--nd-ease),
    border-color var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease);
}
.nt-launchpad-row:hover {
  border-left-color: var(--nd-accent);
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
