/* ---------- Wave 14: plane ECG + reconciliation reveal ---------- */
.nt-plane-ecg {
  position: relative;
  height: 3px;
  width: 64px;
  border-radius: 999px;
  background: var(--nd-bg-sunken);
  overflow: hidden;
  box-shadow: inset 0 0 0 1px var(--nd-border-subtle);
}
.nt-plane-ecg__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  transition: width var(--nd-duration-med) var(--nd-ease);
  box-shadow: 0 0 12px color-mix(in srgb, var(--nd-accent) 35%, transparent);
}
.nt-plane-ecg__fill--ok { background: var(--nd-success); box-shadow: 0 0 12px color-mix(in srgb, var(--nd-success) 40%, transparent); }
.nt-plane-ecg__fill--warn { background: var(--nd-warning); box-shadow: 0 0 12px color-mix(in srgb, var(--nd-warning) 40%, transparent); }
.nt-plane-ecg__fill--danger { background: var(--nd-danger); box-shadow: 0 0 12px color-mix(in srgb, var(--nd-danger) 45%, transparent); }
.nt-plane-ecg__fill--muted { background: var(--nd-border-strong); box-shadow: none; }

@keyframes nt-recon-reveal {
  from { opacity: 0; transform: translateY(6px); filter: blur(2px); }
  to { opacity: 1; transform: none; filter: none; }
}
.nt-recon-reveal {
  animation: nt-recon-reveal 480ms var(--nd-ease) both;
}
.nt-recon-reveal > * {
  animation: nt-recon-reveal 520ms var(--nd-ease) both;
}
.nt-recon-reveal > *:nth-child(1) { animation-delay: 40ms; }
.nt-recon-reveal > *:nth-child(2) { animation-delay: 90ms; }
.nt-recon-reveal > *:nth-child(3) { animation-delay: 140ms; }
.nt-recon-reveal > *:nth-child(4) { animation-delay: 190ms; }
.nt-recon-reveal > *:nth-child(5) { animation-delay: 240ms; }
.nt-recon-reveal > *:nth-child(6) { animation-delay: 290ms; }

