  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border-default));
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-bg-raised) 88%, transparent);
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 24px color-mix(in srgb, var(--nd-bg-inset) 30%, transparent);
  margin-bottom: 10px;
  position: sticky;
  top: 0;
  z-index: 6;
}
.nt-bulk-bar__count {
  font-family: var(--nd-font-mono);
  font-size: 11px;
  color: var(--nd-text-muted);
}

/* cmdk densify */
.nd-cmdk,
.nt-cmdk {
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border-default));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 40%),
    var(--nd-bg-raised);
  box-shadow:
    0 28px 80px color-mix(in srgb, var(--nd-bg-inset) 70%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 6%, transparent);
