  overflow: hidden;
}
.nd-cmdk__input,
.nt-cmdk__input {
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: transparent;
}
.nd-cmdk__item[aria-selected='true'],
.nt-cmdk__item[data-active='true'] {
  background: color-mix(in srgb, var(--nd-accent) 14%, var(--nd-bg-hover));
  box-shadow: inset 3px 0 0 var(--nd-accent);
}

/* toast copper edge */
.nd-toast {
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border-default));
  box-shadow: 0 12px 32px color-mix(in srgb, var(--nd-bg-inset) 45%, transparent);
}
.nd-toast[data-tone='danger'] { box-shadow: inset 3px 0 0 var(--nd-danger), 0 12px 32px color-mix(in srgb, var(--nd-bg-inset) 45%, transparent); }
.nd-toast[data-tone='success'] { box-shadow: inset 3px 0 0 var(--nd-success), 0 12px 32px color-mix(in srgb, var(--nd-bg-inset) 45%, transparent); }
.nd-toast[data-tone='warning'] { box-shadow: inset 3px 0 0 var(--nd-warning), 0 12px 32px color-mix(in srgb, var(--nd-bg-inset) 45%, transparent); }

html[data-nd-theme='light'] .nt-bulk-bar,
html[data-nd-theme='light'] .nt-tickets__workspace {
  box-shadow: 0 8px 20px color-mix(in srgb, var(--nd-bg-inset) 10%, transparent);
}

/* ── Wave 19gc — site detail theaters · SLE · DS gallery ── */
.nt-plane-theater--compact {
  padding: 4px 2px 8px;
  margin-bottom: 8px;
  font-size: 9px;
  letter-spacing: 0.12em;
}
.nt-sle-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
  align-items: baseline;
  padding: 8px 10px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid transparent;
}
.nt-sle-row:hover {
  background: color-mix(in srgb, var(--nd-bg-hover) 45%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
.nt-note-danger {
  border-color: color-mix(in srgb, var(--nd-danger) 28%, var(--nd-border-default)) !important;
  background: color-mix(in srgb, var(--nd-danger) 8%, var(--nd-bg-raised)) !important;
  color: var(--nd-text-primary);
}

/* design system gallery chrome */
.nt-dsg-workspace {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.nt-dsg-brand-kicker {
  color: var(--nd-accent-text, var(--nd-accent));
  letter-spacing: 0.16em;
}
.nt-dsg-brand-title {
  font-size: clamp(1.4rem, 2vw, 1.85rem);
