  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-elevated) 88%, transparent);
  box-shadow: var(--nd-shadow-xs);
  transition: border-color 140ms ease, box-shadow 140ms ease, background 140ms ease;
}
.nt-severity-chips .nt-chip:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border-default));
}
.nt-severity-chips .nt-chip--active,
.nt-severity-chips .nt-chip[aria-pressed='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 42%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-accent-muted) 55%, var(--nd-bg-elevated));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 18%, transparent), var(--nd-shadow-sm);
}
.nt-severity-chips .nt-chip[data-sev='critical'] .nt-chip__count,
.nt-severity-chips .nt-chip[data-sev='high'] .nt-chip__count {
  color: var(--nd-danger);
}
.nt-severity-chips .nt-chip[data-sev='medium'] .nt-chip__count {
  color: var(--nd-warning);
}
.nt-severity-chips .nt-chip[data-sev='low'] .nt-chip__count {
  color: var(--nd-text-secondary);
}

/* ── Wave 20eg — copper density continuum ── */
.nt-compliance-grid {
  display: grid;
  gap: 22px;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.9fr);
  align-items: start;
}
@media (max-width: 1100px) {
  .nt-compliance-grid {
    grid-template-columns: 1fr;
  }
}

/* ── Wave 20eh — copper density continuum ── */
.nt-drift-card {
  display: grid;
  gap: 8px;
  padding: 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-warning) 22%, var(--nd-border-subtle));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-warning) 7%, transparent), transparent 48%),
    var(--nd-bg-surface);
  box-shadow: var(--nd-shadow-xs);
}
.nt-drift-card__title {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: baseline;
  font-size: 13px;
  font-weight: 600;
  color: var(--nd-text-primary);
}
.nt-drift-card__meta {
  font-size: 11px;
  color: var(--nd-text-secondary);
  font-family: var(--nd-font-mono);
}

/* ── Wave 20ei — copper density continuum ── */
.nt-plane-theater {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 28px;
  padding: 0 2px;
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-text-tertiary));
}
.nt-plane-theater::before {
  content: '';
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--nd-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}

/* ── Wave 20ej — copper density continuum ── */
html[data-nd-theme='light'] .nt-severity-chips .nt-chip {
  background: color-mix(in srgb, var(--nd-bg-elevated) 96%, white);
}
html[data-nd-theme='light'] .nt-drift-card {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-warning) 10%, transparent), transparent 50%),
    var(--nd-bg-elevated);
}
html[data-nd-theme='light'] .nt-baseline-bar__track {
  background: color-mix(in srgb, var(--nd-bg-inset) 80%, white);
}

/* ── Wave 20ek — copper density continuum ── */
.nt-backup-diff .nd-code,
.nt-backup-diff pre,
.nt-backup-diff code {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  margin: 0;
  padding: 0;
}
.nt-backup-diff {
  position: relative;
}
.nt-backup-diff::before {
  content: 'DIFF';
  position: absolute;
  top: 8px;
  right: 10px;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: color-mix(in srgb, var(--nd-accent) 50%, var(--nd-text-tertiary));
  pointer-events: none;
}

/* ── Wave 20el — copper density continuum ── */
.nt-ticket-workspace {
  display: grid;
  gap: 16px;
}
.nt-ticket-workspace__rail {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 8px 10px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-elevated) 92%, transparent);
  box-shadow: var(--nd-shadow-xs);
}
.nt-ticket-workspace__rail[data-pri='p1'] {
  box-shadow: inset 2px 0 0 var(--nd-danger), var(--nd-shadow-xs);
}
.nt-ticket-workspace__rail[data-pri='p2'] {
  box-shadow: inset 2px 0 0 var(--nd-warning), var(--nd-shadow-xs);
}

/* ── Wave 20em — copper density continuum ── */
.nt-alert-spine {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  min-height: 36px;
  padding: 6px 10px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 42%),
    var(--nd-bg-surface);
}
.nt-alert-spine__step {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-alert-spine__step[data-active='true'] {
  color: var(--nd-text-primary);
  font-weight: 600;
}
.nt-alert-spine__step::after {
  content: '▸';
  margin-left: 4px;
  opacity: 0.45;
  color: var(--nd-text-tertiary);
}
.nt-alert-spine__step:last-child::after {
  content: none;
}

/* ── Wave 20en — copper density continuum ── */
.nt-client-session {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-surface);
}
.nt-client-session[data-tone='danger'] {
  box-shadow: inset 2px 0 0 var(--nd-danger);
}
.nt-client-session[data-tone='warning'] {
  box-shadow: inset 2px 0 0 var(--nd-warning);
}
.nt-client-session__id {
  font-family: var(--nd-font-mono);
  font-size: 12px;
  color: var(--nd-text-primary);
}
.nt-client-session__meta {
  font-size: 11px;
  color: var(--nd-text-secondary);
}

/* ── Wave 20eo — copper density continuum ── */
.nt-screen-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 58%, var(--nd-text-tertiary));
}
.nt-screen-kicker::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--nd-accent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--nd-accent) 55%, transparent);
}

/* ── Wave 20ep — copper density continuum ── */
html[data-nd-theme='light'] .nt-ticket-workspace__rail,
html[data-nd-theme='light'] .nt-alert-spine,
html[data-nd-theme='light'] .nt-client-session {
  background: color-mix(in srgb, var(--nd-bg-elevated) 96%, white);
}
html[data-nd-theme='light'] .nt-backup-diff {
  background: color-mix(in srgb, var(--nd-bg-inset) 70%, white);
}

/* ── Wave 20eq — copper density continuum ── */
.nt-alert-spine.nt-incident-spine .nt-alert-spine__step::after {
  content: none;
}
.nt-incident-spine.nt-alert-spine {
  /* prefer dual-class glass treatment already defined */
}
.nt-tickets__workspace.nt-ticket-workspace {
  gap: 16px;
}

/* ── Wave 20er — copper density continuum ── */
.nt-write-ritual {
  position: relative;
  overflow: hidden;
}
.nt-write-ritual::after {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 2px;
  background: linear-gradient(180deg, transparent, var(--nd-accent), transparent);
  opacity: 0.75;
}
.nt-write-ritual__title {
  font-size: 13px;
  font-weight: 600;
  color: var(--nd-text-primary);
}
.nt-write-ritual__meta {
  font-size: 11px;
  font-family: var(--nd-font-mono);
  color: var(--nd-text-secondary);
}

/* ── Wave 20es — copper density continuum ── */
.nt-cmdk-cinema {
  border-radius: var(--nd-radius-lg);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border-subtle));
  background:
    radial-gradient(120% 80% at 10% -20%, color-mix(in srgb, var(--nd-accent) 16%, transparent), transparent 55%),
    var(--nd-bg-elevated);
  box-shadow: var(--nd-shadow-lg), 0 0 0 1px color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-cmdk-cinema__input {
  border: 0;
  background: transparent;
  box-shadow: none;
}
.nt-cmdk-cinema__group {
  padding: 6px 8px 10px;
}
.nt-cmdk-cinema__item[data-active='true'] {
  background: color-mix(in srgb, var(--nd-accent-muted) 60%, transparent);
  box-shadow: inset 2px 0 0 var(--nd-accent);
}

/* ── Wave 20et — copper density continuum ── */
.nt-empty-wake {
  display: grid;
  place-items: center;
  gap: 10px;
  padding: 28px 18px;
  border-radius: var(--nd-radius-lg);
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border-subtle));
  background:
    radial-gradient(80% 60% at 50% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 70%),
    var(--nd-bg-surface);
}
.nt-empty-wake__mark {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--nd-accent);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-accent-muted) 45%, var(--nd-bg-elevated));
  box-shadow: var(--nd-shadow-sm);
}

/* ── Wave 20eu — copper density continuum ── */
.nt-empty-wake.nd-empty,
.nt-empty-wake.nt-empty-cinema {
  justify-items: center;
  text-align: center;
}
.nt-empty-wake .nd-empty__actions,
.nt-empty-wake > :last-child:not(.nt-empty-wake__mark) {
  margin-top: 4px;
}
.nt-global-search.nt-cmdk-cinema {
  /* host already positions; cinema adds material */
}
.nt-global-search.nt-cmdk-cinema .nt-global-search__panel {
  border-color: color-mix(in srgb, var(--nd-accent) 20%, var(--nd-border-subtle));
  box-shadow: var(--nd-shadow-lg);
}

/* ── Wave 20ev — copper density continuum ── */
.nt-license-track {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: var(--nd-bg-surface);
}
.nt-license-track__head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-license-track__bar {
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: var(--nd-bg-inset);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
}
.nt-license-track__fill {
  height: 100%;
  width: var(--nd-health, 0%);
  background: linear-gradient(90deg, var(--nd-accent), color-mix(in srgb, var(--nd-accent) 55%, var(--nd-warning)));
}
.nt-license-track[data-tone='danger'] .nt-license-track__fill {
  background: linear-gradient(90deg, var(--nd-danger), color-mix(in srgb, var(--nd-danger) 60%, var(--nd-warning)));
}
.nt-license-track[data-tone='warning'] .nt-license-track__fill {
  background: linear-gradient(90deg, var(--nd-warning), color-mix(in srgb, var(--nd-warning) 55%, var(--nd-accent)));
}

/* ── Wave 20ew — copper density continuum ── */
.nt-site-card {
  display: grid;
  gap: 8px;
  padding: 12px 14px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-accent) 7%, transparent), transparent 42%),
    var(--nd-bg-surface);
  box-shadow: var(--nd-shadow-xs);
  transition: border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}
.nt-site-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border-default));
  box-shadow: var(--nd-shadow-sm);
}
.nt-site-card__name {
  font-size: 13px;
  font-weight: 600;
  color: var(--nd-text-primary);
}
.nt-site-card__meta {
  font-size: 11px;
  font-family: var(--nd-font-mono);
  color: var(--nd-text-secondary);
}

/* ── Wave 20ex — copper density continuum ── */
.nt-ssl-cert-row,
.nt-smtp-probe-row,
.nt-outbox-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-surface);
}
.nt-ssl-cert-row[data-tone='danger'],
.nt-smtp-probe-row[data-tone='danger'],
.nt-outbox-row[data-tone='danger'] {
  box-shadow: inset 2px 0 0 var(--nd-danger);
}
.nt-ssl-cert-row[data-tone='warning'],
.nt-smtp-probe-row[data-tone='warning'],
.nt-outbox-row[data-tone='warning'] {
  box-shadow: inset 2px 0 0 var(--nd-warning);
}

/* ── Wave 20ey — copper density continuum ── */
html[data-nd-theme='light'] .nt-site-card,
html[data-nd-theme='light'] .nt-license-track,
html[data-nd-theme='light'] .nt-ssl-cert-row,
html[data-nd-theme='light'] .nt-smtp-probe-row,
html[data-nd-theme='light'] .nt-outbox-row {
  background: color-mix(in srgb, var(--nd-bg-elevated) 96%, white);
}

/* ── Wave 20ez — copper density continuum ── */
.nt-sites-stack .nd-table tbody tr {
  transition: background 120ms ease;
}
.nt-sites-stack .nd-table tbody tr:hover td {
  background: color-mix(in srgb, var(--nd-accent) 5%, transparent);
}
.nt-sites-stack .nt-health-chip[aria-pressed='true'],
.nt-sites-stack .nt-toggle-chip[aria-pressed='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border-default));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 16%, transparent);
}

/* ── Wave 20fa — copper density continuum ── */
.nt-device-fact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
}
.nt-device-fact {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-surface);
}
.nt-device-fact__label {
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-device-fact__value {
  font-size: 13px;
  font-weight: 600;
  color: var(--nd-text-primary);
  font-variant-numeric: tabular-nums;
}

/* ── Wave 20fb — copper density continuum ── */
.nt-config-queue {
  display: grid;
  gap: 8px;
}
.nt-config-queue__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
  padding: 10px 12px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: var(--nd-bg-surface);
}
.nt-config-queue__item[data-state='ready'] {
  box-shadow: inset 2px 0 0 var(--nd-success);
}
.nt-config-queue__item[data-state='blocked'],
.nt-config-queue__item[data-state='error'] {
  box-shadow: inset 2px 0 0 var(--nd-danger);
}
.nt-config-queue__item[data-state='pending'],
.nt-config-queue__item[data-state='review'] {
  box-shadow: inset 2px 0 0 var(--nd-warning);
}

/* ── Wave 20fc — copper density continuum ── */
.nt-auth-event-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 8px 10px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-surface);
}
.nt-auth-event-row[data-result='fail'],
.nt-auth-event-row[data-result='deny'] {
  box-shadow: inset 2px 0 0 var(--nd-danger);
}
.nt-auth-event-row[data-result='ok'],
.nt-auth-event-row[data-result='accept'] {
  box-shadow: inset 2px 0 0 var(--nd-success);
}

/* ── Wave 20fd — copper density continuum ── */
.nt-clearpass-hero {
  display: grid;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--nd-radius-lg);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border-subtle));
  background:
    radial-gradient(90% 80% at 0% 0%, color-mix(in srgb, var(--nd-accent) 14%, transparent), transparent 55%),
    var(--nd-bg-elevated);
  box-shadow: var(--nd-shadow-sm);
}
.nt-clearpass-hero__title {
  font-size: 14px;
  font-weight: 650;
  color: var(--nd-text-primary);
}
.nt-clearpass-hero__meta {
  font-size: 12px;
  color: var(--nd-text-secondary);
}

/* ── Wave 20fe — copper density continuum ── */
html[data-nd-theme='light'] .nt-device-fact,
html[data-nd-theme='light'] .nt-config-queue__item,
html[data-nd-theme='light'] .nt-auth-event-row,
html[data-nd-theme='light'] .nt-clearpass-hero {
  background: color-mix(in srgb, var(--nd-bg-elevated) 96%, white);
}

/* ── Wave 20ff — copper density continuum ── */
.nt-fact-row.nt-device-fact {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
}
.nt-configure__queue.nt-write-ritual {
  position: relative;
  padding: 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 6%, transparent), transparent 40%),
    var(--nd-bg-surface);
  box-shadow: var(--nd-shadow-xs);
}
.nt-configure__queue.nt-write-ritual::after {
  /* sheen rail from write-ritual */
}

/* ── Wave 20fg — copper density continuum ── */
.nt-shift-strip {
  backdrop-filter: blur(10px);
}
.nt-shift-strip__fresh {
  font-variant-numeric: tabular-nums;
}
.nt-shift-strip[data-p1='true'] {
  box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--nd-danger) 35%, transparent);
}
.nt-shift-strip[data-degraded='true'] {
  box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--nd-warning) 35%, transparent);
}

/* ── Wave 20fh — copper density continuum ── */
.nt-notify-item[data-unread='true'] {
  position: relative;
  background: color-mix(in srgb, var(--nd-accent) 6%, var(--nd-bg-surface));
}
.nt-notify-item[data-unread='true']::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 50%;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  transform: translateY(-50%);
  background: var(--nd-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}

/* ── Wave 20fi — copper density continuum ── */
.nt-topo-host {
  border-radius: var(--nd-radius-lg);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
  background:
    radial-gradient(70% 50% at 50% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 60%),
    var(--nd-bg-inset);
  box-shadow: var(--nd-shadow-sm);
  overflow: hidden;
}
.nt-topo-host canvas {
  display: block;
}

/* ── Wave 20fj — copper density continuum ── */
html[data-nd-theme='light'] .nt-configure__queue.nt-write-ritual,
html[data-nd-theme='light'] .nt-fact-row.nt-device-fact,
html[data-nd-theme='light'] .nt-topo-host {
  background: color-mix(in srgb, var(--nd-bg-elevated) 96%, white);
}

/* ── Wave 20fk — copper density continuum ── */
.nt-uxi-detail {
  display: grid;
  gap: 8px;
  padding: 12px 14px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
