  background: color-mix(in srgb, var(--nd-surface-2) 55%, transparent);
}
.nt-status-chip,
.nd-badge.nt-status-chip {
  border-radius: 999px;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.nt-plane-chip,
.nd-badge--plane.nt-plane-chip {
  background: color-mix(in srgb, var(--nd-surface-3) 80%, transparent);
