  border-radius: var(--nd-radius-md, 10px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
}
.nt-text-pri-12 {
  font-size: var(--nd-text-12, 12px);
  color: var(--nd-text-primary);
}
.nt-pad-y-8,
.nt-pad-y-8-2 {
  padding-top: 8px;
  padding-bottom: 8px;
}
html[data-nd-theme='light'] .nt-dpi-grid,
html[data-nd-theme='light'] .nt-dpi-row:hover {
  background: color-mix(in srgb, var(--nd-surface-0, white) 70%, var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jp — ** plane head · ECG chrome ── ** ── */
.nt-plane-head,
.nt-filter-bar.nt-plane-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md, 10px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 75%, transparent), var(--nd-surface-1));
  box-shadow: var(--nd-shadow-sm);
  position: relative;
  overflow: hidden;
}
.nt-plane-head::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: color-mix(in srgb, var(--nd-accent) 55%, transparent);
}
.nt-plane-head[data-tone='danger']::before { background: var(--nd-danger); }
.nt-plane-head[data-tone='warning']::before { background: var(--nd-warning); }
.nt-plane-head[data-tone='success']::before { background: var(--nd-success); }
.nt-plane-head[data-live='1'] {
  box-shadow:
    var(--nd-shadow-sm),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-plane-head__meta {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.04em;
}
.nt-plane-head__link {
  text-decoration: none;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 30%, transparent);
}
.nt-plane-head__link:hover {
  color: var(--nd-text-primary);
  border-bottom-color: color-mix(in srgb, var(--nd-accent) 70%, transparent);
}
.nt-flex-only {
  flex: 1 1 auto;
  min-width: 8px;
}
.nt-accent-text {
  color: var(--nd-accent-text, var(--nd-accent));
}
html[data-nd-theme='light'] .nt-plane-head,
html[data-nd-theme='light'] .nt-filter-bar.nt-plane-head {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 72%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jq — ** cmdk kind chips · residual polish ── ** ── */
.nt-cmdk-cinema .nt-chip-row,
.nt-global-search .nt-chip-row {
  padding: 4px 2px 2px;
}
.nt-chip-row--tight {
  gap: 6px;
}
.nt-global-search__field:focus,
.nt-cmdk-cinema__input:focus {
  box-shadow: var(--nd-focus-ring, 0 0 0 3px color-mix(in srgb, var(--nd-accent) 28%, transparent));
}
.nt-cmdk-cinema [role='listbox'] {
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  margin-top: 6px;
  padding-top: 6px;
}
.nt-cmdk-cinema [role='option'][aria-selected='true'],
.nt-cmdk-cinema [data-active='true'] {
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  box-shadow: inset 2px 0 0 var(--nd-accent);
}
html[data-nd-theme='light'] .nt-cmdk-cinema [role='option'][aria-selected='true'] {
  background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-0, white));
}

/* ── ** ── ** Wave 20jr — ** Topology3D glass · brand strip ── ** ── */
.nt-topo3d,
.nt-topo-host {
  position: relative;
  min-height: 360px;
  border-radius: var(--nd-radius-lg, 14px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    radial-gradient(circle at 30% 20%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 45%),
    color-mix(in srgb, var(--nd-surface-2) 70%, var(--nd-surface-1));
  overflow: hidden;
  box-shadow: var(--nd-shadow-md);
}
.nt-topo3d__canvas {
  position: absolute;
  inset: 0;
}
.nt-topo3d__brand {
  position: absolute;
  z-index: 2;
  top: 10px;
  left: 12px;
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
  pointer-events: none;
}
.nt-topo3d__glass {
  position: absolute;
  z-index: 2;
  max-width: min(280px, 46%);
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, var(--nd-accent) 14%);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 88%, transparent), var(--nd-surface-1));
  box-shadow:
    var(--nd-shadow-md),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
  backdrop-filter: blur(12px) saturate(1.08);
  -webkit-backdrop-filter: blur(12px) saturate(1.08);
}
.nt-topo3d__glass--tl { top: 36px; left: 12px; }
.nt-topo3d__glass--br { right: 12px; bottom: 12px; }
.nt-topo3d__title {
  font-weight: 700;
  color: var(--nd-text-primary);
  font-size: var(--nd-text-13, 13px);
}
.nt-topo3d__meta,
.nt-topo3d__stat {
  margin-top: 4px;
  font-size: var(--nd-text-11, 11px);
  color: var(--nd-text-secondary);
  font-family: var(--nd-font-mono);
}
html[data-nd-theme='light'] .nt-topo3d__glass {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 75%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20js — ** overview change strip · war-room ── ** ── */
.nt-overview {
  min-width: 0;
}
.nt-change-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md, 10px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 75%, transparent), var(--nd-surface-1));
  box-shadow: var(--nd-shadow-sm);
}
.nt-change-strip__kicker {
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
  margin-right: 4px;
}
.nt-change-strip__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-3) 55%, transparent);
  color: var(--nd-text-primary);
  font-size: var(--nd-text-12, 12px);
  font-weight: 600;
  cursor: pointer;
  font: inherit;
}
.nt-change-strip__chip--danger {
  border-color: color-mix(in srgb, var(--nd-danger) 40%, var(--nd-border));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-danger) 12%, transparent);
  color: var(--nd-danger-text, var(--nd-text-primary));
}
.nt-change-strip__chip--warning {
  border-color: color-mix(in srgb, var(--nd-warning) 40%, var(--nd-border));
}
.nt-change-strip__chip--success {
  border-color: color-mix(in srgb, var(--nd-success) 40%, var(--nd-border));
}
.nt-change-strip__note {
  margin-left: auto;
  font-size: var(--nd-text-11, 11px);
  color: var(--nd-text-muted);
  max-width: 42ch;
}
.nt-health-bar,
.nt-plane-ecg {
  position: relative;
  height: 6px;
  min-width: 48px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-3) 80%, transparent);
  overflow: hidden;
}
.nt-health-bar__fill,
.nt-health-fill,
.nt-plane-ecg__fill {
  display: block;
  height: 100%;
  width: var(--nd-health, 40%);
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 70%, transparent), var(--nd-accent));
}
.nt-fill-danger { background: var(--nd-danger); }
.nt-fill-warning { background: var(--nd-warning); }
.nt-fill-success { background: var(--nd-success); }
.nt-fill-neutral { background: var(--nd-text-muted); }
html[data-nd-theme='light'] .nt-change-strip {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 72%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jt — ** auth wake · incident strip glass ── ** ── */
.nt-auth-panel {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 20% 10%, color-mix(in srgb, var(--nd-accent) 14%, transparent), transparent 42%),
    radial-gradient(circle at 80% 90%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 40%),
    var(--nd-surface-0, var(--nd-surface-1));
}
.nt-auth-card {
  width: min(420px, 100%);
  padding: 28px 26px;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, var(--nd-accent) 14%);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 88%, transparent), var(--nd-surface-1));
  box-shadow:
    var(--nd-shadow-lg, 0 28px 72px color-mix(in srgb, var(--nd-ink, black) 48%, transparent)),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 12%, transparent);
  backdrop-filter: blur(14px) saturate(1.08);
  -webkit-backdrop-filter: blur(14px) saturate(1.08);
}
.nt-auth-card__eyebrow {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
}
.nt-auth-card__title {
  margin: 10px 0 0;
  font-size: clamp(22px, 3vw, 28px);
  letter-spacing: -0.03em;
  color: var(--nd-text-primary);
  line-height: 1.15;
}
.nt-auth-card__body {
  margin: 10px 0 0;
  color: var(--nd-text-secondary);
  font-size: var(--nd-text-13, 13px);
  line-height: 1.5;
}
.nt-auth-wake-bar {
  height: 10px;
  border-radius: 999px;
  margin-top: 14px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-surface-3) 80%, transparent), color-mix(in srgb, var(--nd-accent) 22%, transparent));
  animation: nt-war-skeleton 1.4s ease-in-out infinite;
}
.nt-auth-wake-bar--short { width: 58%; }
.nt-auth-wake-bar--mid { width: 78%; }
.nt-auth-panel__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}
.nt-logo-mark {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--nd-accent-text, var(--nd-text-primary));
  background: color-mix(in srgb, var(--nd-accent) 18%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 32%, transparent);
  box-shadow: 0 0 18px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}
.nt-incident-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 8px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-surface-2) 70%, transparent), color-mix(in srgb, var(--nd-surface-1) 90%, transparent));
}
.nt-incident-strip__brand {
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent-text, var(--nd-accent)) 80%, var(--nd-text-muted));
}
.nt-incident-strip__label {
  font-size: var(--nd-text-11, 11px);
  color: var(--nd-text-muted);
  font-family: var(--nd-font-mono);
}
.nt-incident-strip__title {
  font-weight: 650;
  color: var(--nd-text-primary);
  font-size: var(--nd-text-12, 12px);
}
.nt-incident-strip__actions {
  margin-left: auto;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
@keyframes nt-war-skeleton {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 1; }
}
html[data-nd-theme='light'] .nt-auth-card,
html[data-nd-theme='light'] .nt-incident-strip {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 75%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20ju — ** assistant section · provider chips ── ** ── */
.nt-assistant-section {
  min-width: 0;
}
.nt-assistant-chip {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 8px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 60%, transparent);
  color: inherit;
  font: inherit;
  cursor: pointer;
  min-width: 120px;
  text-align: left;
  transition: border-color 140ms var(--nd-ease, ease), box-shadow 140ms var(--nd-ease, ease);
}
.nt-assistant-chip:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
}
.nt-assistant-chip--editing,
.nt-assistant-chip[aria-pressed='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-accent);
  background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-2));
}
.nt-assistant-footer {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 4px;
  padding-top: 12px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
}
.nt-grid-2-10 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 10px 14px;
}
.nt-tone-success { color: var(--nd-success); }
.nt-tone-danger { color: var(--nd-danger); }
.nt-danger-12 {
  color: var(--nd-danger-text, var(--nd-danger));
  font-size: var(--nd-text-12, 12px);
}
html[data-nd-theme='light'] .nt-assistant-chip {
  background: color-mix(in srgb, var(--nd-surface-0, white) 70%, var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jv — ** plane shells · war-room wake ── ** ── */
.nt-plane-shell,
.nt-greenlake-shell,
.nt-uxi-shell,
.nt-licenses-shell,
.nt-compliance-shell,
.nt-auth-events-shell {
  min-width: 0;
}
.nt-plane-shell > .nt-plane-theater,
.nt-greenlake-shell > .nt-plane-theater,
.nt-uxi-shell > .nt-plane-theater,
.nt-licenses-shell > .nt-plane-theater,
.nt-compliance-shell > .nt-plane-theater {
  margin-bottom: 2px;
}
.nt-page-skeleton.nt-war-room-wake,
.nd-page-skeleton.nt-page-skeleton {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px 16px 20px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 72%, transparent);
  background:
    radial-gradient(ellipse 70% 50% at 12% 0%, color-mix(in srgb, var(--nd-accent) 12%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  box-shadow: var(--nd-shadow-1, 0 8px 28px color-mix(in srgb, var(--nd-ink, black) 22%, transparent));
  overflow: hidden;
}
.nt-page-skeleton::before,
.nd-page-skeleton.nt-war-room-wake::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: linear-gradient(180deg, var(--nd-accent), transparent 70%);
  opacity: 0.85;
  pointer-events: none;
}
.nd-page-skeleton__kicker {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 70%, var(--nd-text-muted));
  font-weight: 600;
}
.nd-page-skeleton__header {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  align-items: center;
  justify-content: space-between;
}
.nd-page-skeleton__stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 10px;
}
.nd-page-skeleton__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 14px;
}
@media (max-width: 720px) {
  .nd-page-skeleton__grid { grid-template-columns: 1fr; }
}
.nd-page-skeleton__row {
  border-radius: 10px !important;
}
.nt-skeleton-block.nd-skeleton,
.nd-skeleton.nt-skeleton-block {
  border-radius: 8px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-surface-2) 80%, transparent) 0%,
    color-mix(in srgb, var(--nd-surface-3, var(--nd-surface-2)) 90%, var(--nd-accent) 6%) 48%,
    color-mix(in srgb, var(--nd-surface-2) 80%, transparent) 100%
  );
  background-size: 200% 100%;
  animation: nt-skeleton-shimmer 1.4s ease-in-out infinite;
}
@keyframes nt-skeleton-shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .nt-skeleton-block.nd-skeleton,
  .nd-skeleton.nt-skeleton-block { animation: none; }
}
html[data-nd-theme='light'] .nt-page-skeleton.nt-war-room-wake,
html[data-nd-theme='light'] .nd-page-skeleton.nt-page-skeleton {
  background:
    radial-gradient(ellipse 70% 50% at 12% 0%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-0, white) 92%, var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jw — ** breadcrumbs · notify cinema · route wake ── ** ── */
.nt-breadcrumbs.nd-crumbs,
.nd-crumbs.nt-breadcrumbs {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  font-size: var(--nd-text-12, 12px);
  color: var(--nd-text-muted);
  min-width: 0;
}
.nt-breadcrumbs__sep,
.nd-crumbs__sep {
  opacity: 0.45;
  user-select: none;
}
.nt-breadcrumbs__link,
.nd-crumbs__link {
  appearance: none;
  border: 0;
  background: transparent;
  color: color-mix(in srgb, var(--nd-accent) 75%, var(--nd-text));
  font: inherit;
  cursor: pointer;
  padding: 0;
  text-decoration: none;
}
.nt-breadcrumbs__link:hover,
.nd-crumbs__link:hover {
  color: var(--nd-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}
.nt-breadcrumbs__item--current,
.nd-crumbs__item--current {
  color: var(--nd-text);
  font-weight: 600;
}
.nt-notify-popover.nt-panel-glass {
  backdrop-filter: blur(16px) saturate(1.15);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 8%, transparent),
    var(--nd-shadow-3, 0 18px 48px color-mix(in srgb, var(--nd-ink, black) 35%, transparent));
}
.nt-notify-popover--hot {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-danger) 22%, transparent),
    var(--nd-shadow-3, 0 18px 48px color-mix(in srgb, var(--nd-ink, black) 35%, transparent));
}
.nt-notify-item.nt-card-lift {
  border-radius: 10px;
  transition: background 140ms var(--nd-ease, ease), transform 140ms var(--nd-ease, ease);
}
.nt-notify-item.nt-card-lift:hover {
  background: color-mix(in srgb, var(--nd-surface-2) 70%, transparent);
}
.nt-notify-item[data-unread='true'] {
  background: color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nt-notify-dot[data-severity='critical'],
.nt-notify-dot[data-severity='p1'] {
  background: var(--nd-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-danger) 22%, transparent);
}
.nt-notify-dot[data-severity='warning'] {
  background: var(--nd-warning);
}
.nt-route-fallback {
  display: flex;
  align-items: stretch;
  justify-content: center;
  padding: 24px 16px;
  min-height: 40vh;
}
.nt-route-fallback__card {
  width: min(920px, 100%);
  padding: 8px;
  border-radius: 18px;
}
.nt-route-fallback__kicker {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 72%, var(--nd-text-muted));
  font-weight: 600;
  padding: 8px 12px 4px;
}
html[data-nd-theme='light'] .nt-notify-popover.nt-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 88%, transparent);
