    color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
}
.nt-shell__topbar.nd-shell__topbar {
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 75%, transparent);
  backdrop-filter: blur(12px) saturate(1.1);
  -webkit-backdrop-filter: blur(12px) saturate(1.1);
}
.nt-shell__content.nt-main-canvas {
