}
html[data-nd-theme='light'] .nt-shell__topbar.nd-shell__topbar {
  background: color-mix(in srgb, var(--nd-surface-0, white) 82%, transparent);
}

/* ── ** ── ** Wave 20ke — ** SSE · webhooks theater · warn boxes ── ** ── */
.nt-sse-shell,
.nt-webhooks-shell {
  min-width: 0;
}
.nt-sse-banner {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  padding: 10px 12px;
  background: color-mix(in srgb, var(--nd-surface-2) 50%, transparent);
}
.nt-border-success {
  border-color: color-mix(in srgb, var(--nd-success) 40%, var(--nd-border)) !important;
  background: color-mix(in srgb, var(--nd-success) 8%, var(--nd-surface-2));
}
.nt-border-warning {
  border-color: color-mix(in srgb, var(--nd-warning) 40%, var(--nd-border)) !important;
  background: color-mix(in srgb, var(--nd-warning) 8%, var(--nd-surface-2));
}
.nt-warn-box {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-warning) 32%, var(--nd-border));
