  margin: 0;
  padding: 0;
}
.nt-visual-ref__card.nt-panel-glass {
  padding: 10px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 72%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 75%, transparent);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.nt-visual-ref__title {
  font-size: var(--nd-text-13, 13px);
}
.nt-visual-ref__meta {
  font-size: var(--nd-text-11, 11px);
