.nd-progress[data-tone='warning'] .nt-progress-rail__fill,
.nd-progress__fill--warning { color: var(--nd-warning); background: linear-gradient(90deg, color-mix(in srgb, var(--nd-warning) 70%, transparent), var(--nd-warning)); }
.nd-progress[data-tone='danger'] .nt-progress-rail__fill,
.nd-progress__fill--danger { color: var(--nd-danger); background: linear-gradient(90deg, color-mix(in srgb, var(--nd-danger) 70%, transparent), var(--nd-danger)); }
.nd-progress[data-tone='accent'] .nt-progress-rail__fill,
.nd-progress__fill--accent { color: var(--nd-accent); background: linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 65%, transparent), var(--nd-accent)); }
.nt-progress-rail__track,
