/* ── ** ── ** Wave 20kw — ** cmdk cinema · shift chips · screen header band ── ** ── */
.nt-global-search.nt-cmdk-cinema {
  position: relative;
}
.nt-global-search__panel.nt-panel-glass {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 24%, var(--nd-border));
  background:
    radial-gradient(120% 80% at 0% 0%, color-mix(in srgb, var(--nd-accent) 12%, transparent), transparent 50%),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent),
    var(--nd-shadow-4, 0 28px 64px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
  overflow: hidden;
}
.nt-global-search__brand {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 78%, var(--nd-text-muted));
  padding: 10px 14px 0;
}
.nt-global-search__field.nt-cmdk-cinema__input,
.nt-cmdk-cinema__input {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-global-search__field.nt-cmdk-cinema__input:focus {
  outline: none;
  border-color: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-border));
  box-shadow: var(--nd-focus-ring, 0 0 0 3px color-mix(in srgb, var(--nd-accent) 28%, transparent));
}
.nt-global-search__hit {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 10px 14px;
  border-radius: 10px;
