}
.nt-global-search__hit:hover,
.nt-global-search__hit--active {
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-global-search__kind {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  border-radius: 7px;
  padding: 2px 6px;
}
.nt-global-search__kind[data-kind='device'],
.nt-global-search__kind[data-kind='devices'] {
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text));
}
.nt-global-search__meta {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-11, 11px);
}
.nt-global-search__empty,
.nt-global-search__warn {
  padding: 14px;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-global-search__warn {
  color: color-mix(in srgb, var(--nd-warning) 80%, var(--nd-text));
}

.nt-shift-strip__brand {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 72%, var(--nd-text-muted));
}
.nt-shift-strip__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  padding: 3px 9px;
  font-size: var(--nd-text-11, 11px);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 50%, transparent);
}
.nt-shift-strip__dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--nd-text-muted);
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 16%, transparent);
}
.nt-shift-strip__dot--live {
  background: var(--nd-success);
  color: var(--nd-success);
  animation: nt-sync-pulse 1.6s ease-in-out infinite;
}
.nt-shift-strip--hot {
  animation: nt-shift-hot 1.1s ease-out 1;
}
@keyframes nt-shift-hot {
  0% { background-color: color-mix(in srgb, var(--nd-danger) 14%, transparent); }
  100% { background-color: transparent; }
}
@keyframes nt-sync-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.55; transform: scale(0.86); }
}

.nt-screen-header.nt-toolbar-glass {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px 18px;
  padding: 14px 4px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
