  top: 0;
  z-index: 3;
}
.nt-screen-header__brand.nt-screen-kicker,
.nt-screen-kicker {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 78%, var(--nd-text-muted));
  margin: 0 0 4px;
}
.nt-screen-header__overline {
  margin: 0;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-screen-header__subtitle {
  margin: 6px 0 0;
  color: var(--nd-text-muted);
  max-width: 62ch;
  line-height: 1.45;
}

.nt-incident-strip__brand {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-danger) 72%, var(--nd-text-muted));
}
.nt-incident-strip__label {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.04em;
}
.nt-incident-strip__title {
  font-weight: 650;
