  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20kx — ** plane-row ECG glass · stat-band cinema ── ** ── */
.nt-plane-row {
  display: grid;
  grid-template-columns: minmax(140px, 1.2fr) auto minmax(180px, 1.4fr) minmax(120px, 1fr) auto;
  gap: 10px 14px;
  align-items: center;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 78%, transparent);
  transition: border-color 140ms ease, background 140ms ease, box-shadow 140ms ease;
}
.nt-plane-row--link {
  text-decoration: none;
  color: inherit;
  cursor: pointer;
}
.nt-plane-row--link:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 34%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 8%, var(--nd-surface-1));
  box-shadow: 0 10px 28px color-mix(in srgb, var(--nd-ink, black) 18%, transparent);
}
.nt-plane-row--ecg {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
.nt-plane-row__identity {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.nt-plane-row__ecg.nt-plane-ecg,
.nt-plane-ecg.nt-ecg-trace {
  height: 6px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 80%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
}
.nt-plane-ecg__fill {
  height: 100%;
  width: var(--nd-health, 40%);
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 55%, transparent), var(--nd-accent));
  box-shadow: 0 0 10px color-mix(in srgb, var(--nd-accent) 30%, transparent);
}
.nt-plane-ecg[data-tone='danger'] .nt-plane-ecg__fill,
.nt-plane-ecg__fill.nt-tone-danger {
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-danger) 55%, transparent), var(--nd-danger));
  box-shadow: 0 0 10px color-mix(in srgb, var(--nd-danger) 30%, transparent);
}
.nt-plane-ecg[data-tone='warning'] .nt-plane-ecg__fill,
.nt-plane-ecg__fill.nt-tone-warning {
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-warning) 55%, transparent), var(--nd-warning));
}
.nt-plane-ecg[data-tone='success'] .nt-plane-ecg__fill,
.nt-plane-ecg__fill.nt-tone-success {
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-success) 55%, transparent), var(--nd-success));
}
.nt-plane-row__facts {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}
.nt-plane-row__cell {
  min-width: 0;
  font-size: var(--nd-text-12, 12px);
  color: var(--nd-text-muted);
}
.nt-plane-row__cell::before {
  content: attr(data-label);
  display: block;
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  margin-bottom: 2px;
  color: color-mix(in srgb, var(--nd-text-muted) 85%, transparent);
}
.nt-plane-row--num {
  font-variant-numeric: tabular-nums;
}
.nt-plane-row__go {
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text-muted));
  font-weight: 700;
}

.nt-stat-band.nt-stat-band--cinema {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 80%, transparent);
  padding: 14px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
}
.nt-stat-link {
  display: block;
  text-decoration: none;
  color: inherit;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
  padding: 12px;
  transition: border-color 140ms ease, transform 140ms ease, background 140ms ease;
}
.nt-stat-link:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 36%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  transform: translateY(-1px);
}
.nt-stat-band__note {
  margin: 10px 0 0;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}

html[data-nd-theme='light'] .nt-plane-row,
html[data-nd-theme='light'] .nt-stat-band.nt-stat-band--cinema,
html[data-nd-theme='light'] .nt-stat-link {
  background: color-mix(in srgb, var(--nd-surface-0, white) 92%, transparent);
}

/* ── ** ── ** Wave 20ky — ** chat cinema · callout · topo3d glass · pending ── ** ── */
.nt-chat-shell.nt-section-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 82%, transparent);
  padding: 12px;
}
.nt-chat-scroll {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 240px;
  max-height: min(62vh, 720px);
  overflow: auto;
  padding: 8px 4px 12px;
}
.nt-chat-bubble {
  max-width: min(720px, 92%);
  border-radius: 14px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  line-height: 1.45;
  font-size: var(--nd-text-13, 13px);
}
.nt-chat-bubble--assistant {
  background:
    radial-gradient(120% 100% at 0% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 70%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
}
.nt-chat-bubble--user {
  margin-left: auto;
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
}
.nt-chat-tool-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 8px;
  align-items: baseline;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 75%, transparent);
  font-size: var(--nd-text-12, 12px);
}
.nt-chat-tool-row[data-ok='true'] {
  border-color: color-mix(in srgb, var(--nd-success) 34%, var(--nd-border));
}
.nt-chat-tool-row[data-ok='false'] {
  border-color: color-mix(in srgb, var(--nd-danger) 36%, var(--nd-border));
}
.nt-chat-tool-row__tool {
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: var(--nd-text-10, 10px);
  color: color-mix(in srgb, var(--nd-accent) 78%, var(--nd-text-muted));
}
.nt-chat-tool-row__args,
.nt-chat-tool-row__result {
  color: var(--nd-text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nt-chat-composer {
  display: flex;
  gap: 10px;
  align-items: flex-end;
  padding-top: 10px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}
.nt-chat-pending {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nt-chat-pending__pulse {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: var(--nd-accent);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--nd-accent) 45%, transparent);
  animation: nt-pending-pulse 1.4s ease-out infinite;
}
@keyframes nt-pending-pulse {
  0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--nd-accent) 45%, transparent); opacity: 1; }
  70% { box-shadow: 0 0 0 10px transparent; opacity: 0.7; }
  100% { box-shadow: 0 0 0 0 transparent; opacity: 1; }
}
.nt-chat-pending__label {
  letter-spacing: 0.04em;
}

.nt-callout-glass.nd-alert {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 86%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nd-alert--danger.nt-callout-glass {
  border-color: color-mix(in srgb, var(--nd-danger) 42%, var(--nd-border));
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nd-danger) 12%, transparent), transparent 48%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
}
.nd-alert--warning.nt-callout-glass {
  border-color: color-mix(in srgb, var(--nd-warning) 42%, var(--nd-border));
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nd-warning) 12%, transparent), transparent 48%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
}
.nd-alert--success.nt-callout-glass {
  border-color: color-mix(in srgb, var(--nd-success) 40%, var(--nd-border));
}
.nd-alert--info.nt-callout-glass,
.nd-alert--accent.nt-callout-glass {
  border-color: color-mix(in srgb, var(--nd-accent) 36%, var(--nd-border));
}
.nt-callout-glass__title {
  font-weight: 700;
  letter-spacing: 0.01em;
}
.nt-callout-glass__body {
  color: var(--nd-text-muted);
  line-height: 1.45;
}

.nt-topo3d-shell.nt-panel-glass,
.nt-topo3d.nt-topo-host {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
