.nt-topo3d__glass {
  position: absolute;
  z-index: 2;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 86%, transparent);
  backdrop-filter: blur(10px) saturate(1.1);
  -webkit-backdrop-filter: blur(10px) saturate(1.1);
  padding: 10px 12px;
