}
.nt-topo3d__glass--tl { top: 36px; left: 12px; max-width: min(280px, 46%); }
.nt-topo3d__glass--br { right: 12px; bottom: 12px; }
.nt-topo3d__title { font-weight: 700; }
.nt-topo3d__meta,
.nt-topo3d__stat {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  margin-top: 4px;
}

html[data-nd-theme='light'] .nt-chat-shell,
html[data-nd-theme='light'] .nt-chat-bubble,
html[data-nd-theme='light'] .nt-callout-glass.nd-alert,
html[data-nd-theme='light'] .nt-topo3d-shell {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20kz — ** inventory tree · breadcrumbs · saved views ── ** ── */
.nt-inventory-tree.nt-inventory-tree-shell {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 80%, transparent);
  padding: 8px;
}
.nt-inventory-tree__row.nt-inventory-tree__node {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 8px;
  border-radius: 10px;
  border: 1px solid transparent;
  padding-left: calc(8px + (var(--nd-tree-level, 0) * 14px));
}
.nt-inventory-tree__row:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-inventory-tree__row--selected {
  border-color: color-mix(in srgb, var(--nd-accent) 36%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-inventory-tree__toggle {
  width: 22px;
  height: 22px;
  border-radius: 7px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 55%, transparent);
  color: var(--nd-text-muted);
  font-size: 12px;
  line-height: 1;
}
.nt-inventory-tree__toggle:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  color: var(--nd-accent);
}
.nt-inventory-tree__label {
  flex: 1;
  min-width: 0;
  font-weight: 600;
}
.nt-inventory-tree__count {
  font-variant-numeric: tabular-nums;
  font-size: var(--nd-text-11, 11px);
  color: var(--nd-text-muted);
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  padding: 1px 7px;
}
.nt-inventory-tree__error {
  color: color-mix(in srgb, var(--nd-danger) 85%, var(--nd-text));
  padding: 8px;
  font-size: var(--nd-text-12, 12px);
}
.nt-inventory-tree--compact .nt-inventory-tree__row {
  padding-top: 4px;
  padding-bottom: 4px;
}

.nt-breadcrumbs.nd-crumbs,
.nd-crumbs.nt-crumb {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  font-size: var(--nd-text-12, 12px);
}
.nt-breadcrumbs__sep {
  color: color-mix(in srgb, var(--nd-text-muted) 75%, transparent);
}
.nt-breadcrumbs__link {
  background: none;
  border: 0;
  padding: 0;
  color: color-mix(in srgb, var(--nd-accent) 82%, var(--nd-text));
  cursor: pointer;
  font: inherit;
}
.nt-breadcrumbs__link:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.nt-breadcrumbs__item--current {
  color: var(--nd-text);
  font-weight: 650;
}

.nt-saved-views.nd-viewopts {
  position: relative;
}
.nt-saved-menu-left.nt-panel-glass,
.nd-viewopts__panel.nt-panel-glass {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow: var(--nd-shadow-3, 0 18px 44px color-mix(in srgb, var(--nd-ink, black) 34%, transparent));
  min-width: 260px;
  padding: 10px;
}
.nd-viewopts__heading {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 72%, var(--nd-text-muted));
  margin-bottom: 8px;
}
.nt-saved-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 7px 8px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.nt-saved-row:hover {
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 20%, transparent);
}
.nt-saved-footer {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}
.nt-saved-hint {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  padding: 6px 4px;
}

html[data-nd-theme='light'] .nt-inventory-tree.nt-inventory-tree-shell,
html[data-nd-theme='light'] .nt-saved-menu-left.nt-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20la — ** debug wake · severity chips · section panels ── ** ── */
.nt-debug-wake {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border-radius: 14px;
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background:
    radial-gradient(120% 100% at 0% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 82%, transparent);
}
.nt-severity-chips .nt-toggle-chip,
.nt-chip-row .nt-toggle-chip {
  min-height: 28px;
}
.nt-chip-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.nt-chip-row--tight { gap: 6px; }
.nt-chip-row__label {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
  margin-right: 2px;
}
.nt-chip__count {
  margin-left: 6px;
  font-variant-numeric: tabular-nums;
  opacity: 0.8;
}
.nt-section-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 72%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nt-plane-shell.nt-section-panel {
  padding: 14px;
}
.nt-plane-theater {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 74%, var(--nd-text-muted));
  margin-bottom: 10px;
}
.nt-plane-theater--compact {
  margin-bottom: 6px;
}
.nt-service-note {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.45;
}
.nt-systems-brand {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 9px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background:
    radial-gradient(120% 120% at 30% 20%, color-mix(in srgb, var(--nd-accent) 24%, transparent), transparent 60%),
    color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 70%, transparent);
  color: color-mix(in srgb, var(--nd-accent) 82%, var(--nd-text));
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

html[data-nd-theme='light'] .nt-debug-wake,
html[data-nd-theme='light'] .nt-section-panel {
  background: color-mix(in srgb, var(--nd-surface-0, white) 92%, transparent);
}

/* ── ** ── ** Wave 20lb — ** visual-ref · rec cards · diagnostics wake ── ** ── */
.nt-visual-ref,
.nt-visual-ref-panel,
.nt-vref-card {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 82%, transparent);
  padding: 12px;
}
.nt-visual-ref__title,
.nt-vref-card__title {
  font-weight: 700;
  letter-spacing: 0.01em;
}
.nt-visual-ref__meta,
.nt-vref-card__meta {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  margin-top: 4px;
}
.nt-rec-card,
.nt-config-rec,
.nt-recommendation-card {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 84%, transparent);
  padding: 12px 14px;
  transition: border-color 140ms ease, transform 140ms ease;
}
.nt-rec-card:hover,
.nt-config-rec:hover,
.nt-recommendation-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 32%, var(--nd-border));
  transform: translateY(-1px);
}
.nt-rec-card__kicker,
.nt-config-rec__kicker {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 74%, var(--nd-text-muted));
  margin-bottom: 6px;
}
.nt-nothing-reported {
  border-radius: 12px;
  border: 1px dashed color-mix(in srgb, var(--nd-border) 90%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 70%, transparent);
  color: var(--nd-text-muted);
}
.nt-nothing-reported__mark {
  display: inline-flex;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  align-items: center;
  justify-content: center;
  margin-right: 8px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 24%, var(--nd-border));
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text));
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
}
.nt-diff-line--del {
  background: color-mix(in srgb, var(--nd-danger) 10%, transparent);
  color: color-mix(in srgb, var(--nd-danger) 88%, var(--nd-text));
}
.nt-diff-line--add {
  background: color-mix(in srgb, var(--nd-success) 10%, transparent);
  color: color-mix(in srgb, var(--nd-success) 88%, var(--nd-text));
}
.nt-diff-line--ctx {
  color: var(--nd-text-muted);
}

html[data-nd-theme='light'] .nt-visual-ref,
html[data-nd-theme='light'] .nt-rec-card,
html[data-nd-theme='light'] .nt-config-rec {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20lc — ** visual-ref shell · rec list · diag probes ── ** ── */
.nt-visual-ref-shell.nt-section-panel,
.nt-visual-ref.nt-section-panel {
  padding: 12px;
}
.nt-visual-ref__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}
.nt-visual-ref__card.nt-panel-glass {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 86%, transparent);
  padding: 12px;
}
.nt-visual-ref__card-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}
.nt-visual-ref__img {
  display: block;
  width: 100%;
  max-height: 220px;
  object-fit: contain;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 50%, transparent);
}
.nt-visual-ref__link {
  color: color-mix(in srgb, var(--nd-accent) 82%, var(--nd-text));
  font-size: var(--nd-text-12, 12px);
}
.nt-visual-ref__composer {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  display: grid;
  gap: 8px;
}
.nt-visual-ref__composer-label {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 72%, var(--nd-text-muted));
}
.nt-visual-ref__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.nt-recs-shell.nt-section-panel {
  padding: 12px;
}
.nt-rec-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}
.nt-rec-card {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 84%, transparent);
  padding: 12px 14px;
}
.nt-rec-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 32%, var(--nd-border));
}
.nt-rec-card[data-sev='critical'],
.nt-rec-card[data-tone='danger'] {
  border-color: color-mix(in srgb, var(--nd-danger) 36%, var(--nd-border));
}
.nt-rec-card[data-sev='high'],
.nt-rec-card[data-tone='warning'] {
  border-color: color-mix(in srgb, var(--nd-warning) 36%, var(--nd-border));
}

.nt-diag {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 82%, transparent);
  padding: 12px;
  display: grid;
  gap: 12px;
}
.nt-diag__row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: baseline;
}
.nt-diag__reason {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-diag__review {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-warning) 34%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-warning) 8%, transparent);
  padding: 12px;
}
.nt-diag__review-title {
  font-weight: 700;
  margin-bottom: 6px;
}
.nt-diag__review-body {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.45;
}
.nt-diag__review-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.nt-diag__job {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  padding: 10px 12px;
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
}
.nt-diag__job-head {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}
.nt-diag__mono {
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nd-text-12, 12px);
  white-space: pre-wrap;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 55%, transparent);
}
.nt-diag__mono--pad6 { padding: 6px 8px; }
.nt-diag__mono--pad8 { padding: 8px 10px; }
.nt-diag__hop {
  display: grid;
  grid-template-columns: 40px 1fr auto;
  gap: 8px;
  align-items: baseline;
  padding: 6px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  font-size: var(--nd-text-12, 12px);
}
.nt-diag__hop-n {
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-muted);
  font-weight: 700;
}
.nt-diag__hop-rtt {
  font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--nd-accent) 70%, var(--nd-text-muted));
}
.nt-diag__audit-label {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
  margin-bottom: 6px;
}
.nt-diag__audit-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  padding: 6px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  font-size: var(--nd-text-12, 12px);
}

html[data-nd-theme='light'] .nt-visual-ref__card,
html[data-nd-theme='light'] .nt-rec-card,
html[data-nd-theme='light'] .nt-diag {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20ld — ** configure rows · tickets · incident spine · device hero ── ** ── */
.nt-configure-shell.nt-section-panel {
  padding: 14px;
}
.nt-configure__layout {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.9fr);
  gap: 14px;
}
@media (max-width: 1100px) {
  .nt-configure__layout { grid-template-columns: 1fr; }
}
.nt-configure-row {
  display: grid;
  grid-template-columns: minmax(120px, 1.1fr) minmax(100px, 0.9fr) minmax(120px, 1.2fr) auto;
  gap: 8px 12px;
  align-items: center;
  width: 100%;
  text-align: left;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 78%, transparent);
  padding: 10px 12px;
  color: inherit;
  cursor: pointer;
}
.nt-configure-row:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 34%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 8%, var(--nd-surface-1));
}
.nt-configure-row__name-primary {
  font-weight: 700;
}
.nt-configure-row__name-meta,
.nt-configure-row__secondary,
.nt-configure-row__summary,
.nt-configure-row__note {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-configure-row__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
}
.nt-configure__queue.nt-write-ritual,
.nt-config-queue.nt-write-ritual {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 26%, var(--nd-border));
  background:
    radial-gradient(120% 80% at 0% 0%, color-mix(in srgb, var(--nd-accent) 12%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  padding: 12px;
}
.nt-configure__queue-title.nt-write-ritual__title {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 800;
  color: color-mix(in srgb, var(--nd-accent) 82%, var(--nd-text));
  margin-bottom: 10px;
}
.nt-configure-capability {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 8px 12px;
  padding: 8px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  font-size: var(--nd-text-12, 12px);
}
.nt-configure-capability__plane {
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: var(--nd-text-10, 10px);
  color: var(--nd-text-muted);
}
.nt-configure-capability__note { color: var(--nd-text-muted); }

.nt-tickets-shell.nt-section-panel {
  padding: 14px;
}
.nt-incident-spine {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: 0 0 12px;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 78%, transparent);
}
.nt-incident-spine__step {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
}
.nt-incident-spine__step[data-active='true'] {
  color: color-mix(in srgb, var(--nd-accent) 88%, var(--nd-text));
}
.nt-incident-spine__chev {
  color: color-mix(in srgb, var(--nd-text-muted) 70%, transparent);
}

.nt-device-detail-shell.nt-section-panel {
  padding: 14px;
}
.nt-device-hero.nt-panel-glass,
.nt-hero-split.nt-device-hero {
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 20%, var(--nd-border));
  background:
    radial-gradient(120% 100% at 0% 0%, color-mix(in srgb, var(--nd-accent) 14%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
  padding: 16px 18px;
  box-shadow: var(--nd-shadow-2, 0 12px 32px color-mix(in srgb, var(--nd-ink, black) 22%, transparent));
}
.nt-device-hero__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-device-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(240px, 0.75fr);
  gap: 14px;
  margin-top: 14px;
}
@media (max-width: 1100px) {
  .nt-device-layout { grid-template-columns: 1fr; }
}
.nt-device-fact.nt-fact-row {
  display: grid;
