.nt-ticket-row.is-selected {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-ticket-workspace {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 84%, transparent);
  padding: 14px;
}
.nt-switch-tree__port {
  margin-left: 12px;
}
.nt-configure-history,
.nt-history-list {
  display: grid;
  gap: 8px;
}
.nt-history-item {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  padding: 10px 12px;
  background: color-mix(in srgb, var(--nd-surface-1) 80%, transparent);
}
.nt-history-item__meta {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-11, 11px);
  margin-top: 4px;
}

html[data-nd-theme='light'] .nt-ticket-queue-item,
html[data-nd-theme='light'] .nt-ticket-workspace,
html[data-nd-theme='light'] .nt-history-item {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20lo — ** ticket workspace facts · evidence gutter · note ── ** ── */
.nt-ticket-workspace {
  display: grid;
  gap: 12px;
}
.nt-ticket-meta-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  padding: 10px 0;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}
@media (max-width: 900px) {
  .nt-ticket-meta-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
.nt-ticket-meta-grid__label {
  display: block;
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
  margin-bottom: 2px;
}
.nt-evidence-list {
  display: grid;
  gap: 8px;
}
.nt-evidence-row {
  display: grid;
  grid-template-columns: 64px auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
  padding: 8px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  font-size: var(--nd-text-12, 12px);
}
.nt-evidence-row__time {
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-muted);
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nd-text-11, 11px);
}
.nt-ticket-note {
  display: grid;
  gap: 8px;
  margin-top: 8px;
}
.nt-ticket-note__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

html[data-nd-theme='light'] .nt-ticket-workspace {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20lp — ** tickets grid · queue item · meta · SLA ── ** ── */
.nt-tickets__grid {
  display: grid;
  grid-template-columns: minmax(280px, 320px) minmax(0, 1fr);
  gap: 14px;
  margin-top: 12px;
  align-items: start;
}
@media (max-width: 1000px) {
  .nt-tickets__grid { grid-template-columns: 1fr; }
}
.nt-tickets__queue {
  display: grid;
  gap: 8px;
}
.nt-tickets__queue-item.nt-queue-row,
.nt-queue-row.nt-tickets__queue-item {
  display: grid;
  gap: 4px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 80%, transparent);
  padding: 10px 12px;
  color: inherit;
  cursor: pointer;
  text-align: left;
  width: 100%;
}
.nt-tickets__queue-item--active,
.nt-tickets__queue-item[data-selected='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-tickets__workspace.nt-ticket-workspace {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 86%, transparent);
  padding: 14px;
}
.nt-tickets__id.nt-ls-kicker {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 800;
  color: color-mix(in srgb, var(--nd-accent) 78%, var(--nd-text-muted));
}
.nt-tickets__meta-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-top: 10px;
  padding: 10px 0;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}
@media (max-width: 900px) {
  .nt-tickets__meta-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
.nt-tickets__meta-k {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
  margin-bottom: 2px;
}
.nt-tickets__sla.nt-sla-chip,
.nt-sla-chip {
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  padding: 2px 8px;
  font-size: var(--nd-text-11, 11px);
  font-variant-numeric: tabular-nums;
  font-weight: 650;
}
.nt-tickets__sla--open[data-state='at-risk'],
.nt-sla-chip[data-state='at-risk'] {
  color: color-mix(in srgb, var(--nd-danger) 88%, var(--nd-text));
  border-color: color-mix(in srgb, var(--nd-danger) 40%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-danger) 10%, transparent);
}
.nt-tickets__sla--open[data-state='ok'],
.nt-sla-chip[data-state='ok'] {
  color: color-mix(in srgb, var(--nd-success) 82%, var(--nd-text));
  border-color: color-mix(in srgb, var(--nd-success) 34%, var(--nd-border));
}
.nt-tickets__sla--done,
.nt-sla-chip[data-state='met'] {
  color: var(--nd-text-muted);
}

html[data-nd-theme='light'] .nt-tickets__queue-item,
html[data-nd-theme='light'] .nt-tickets__workspace {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20lq — ** mist/central plane head · recommendations shell ── ** ── */
.nt-plane-head,
.nt-central-plane-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background:
    radial-gradient(120% 100% at 0% 0%, color-mix(in srgb, var(--nd-accent) 12%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  margin-bottom: 12px;
}
.nt-recommendations-shell .nt-rec-list {
  margin-top: 8px;
}
.nt-mist-shell .nt-plane-theater,
.nt-central-shell .nt-plane-theater {
  margin-bottom: 12px;
}
.nt-card-lift {
  transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease;
}
.nt-card-lift:hover {
  transform: translateY(-1px);
  box-shadow: var(--nd-shadow-2, 0 12px 28px color-mix(in srgb, var(--nd-ink, black) 20%, transparent));
}
.nt-panel-glass {
  backdrop-filter: blur(12px) saturate(1.1);
  -webkit-backdrop-filter: blur(12px) saturate(1.1);
}
.nt-toolbar-glass {
  backdrop-filter: blur(10px) saturate(1.08);
  -webkit-backdrop-filter: blur(10px) saturate(1.08);
}

html[data-nd-theme='light'] .nt-plane-head {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20lr — ** auth gate wake · sign-in cinema ── ** ── */
.nt-auth-panel {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background:
    radial-gradient(90% 70% at 50% 0%, color-mix(in srgb, var(--nd-accent) 14%, transparent), transparent 55%),
    var(--nd-surface-0, var(--nd-surface-1));
}
.nt-auth-card.nt-panel-glass {
  width: min(420px, 100%);
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background:
    radial-gradient(120% 100% at 10% 0%, color-mix(in srgb, var(--nd-accent) 14%, transparent), transparent 50%),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 22px 20px;
  box-shadow: var(--nd-shadow-4, 0 28px 64px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
}
.nt-auth-card__eyebrow {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 800;
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text-muted));
  margin-bottom: 10px;
}
.nt-auth-card__title {
  margin: 0 0 8px;
  font-size: clamp(1.35rem, 2vw, 1.7rem);
  letter-spacing: -0.02em;
}
.nt-auth-card__body {
  margin: 0;
  color: var(--nd-text-muted);
  line-height: 1.5;
}
.nt-auth-panel__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.nt-auth-wake-bar {
  height: 10px;
  border-radius: 999px;
  margin: 10px 0;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 80%, transparent),
    color-mix(in srgb, var(--nd-accent) 22%, transparent),
    color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 80%, transparent)
  );
  background-size: 200% 100%;
  animation: nt-skeleton-shimmer 1.4s ease-in-out infinite;
}
.nt-auth-wake-bar--short { width: 62%; }
.nt-auth-wake-bar--mid { width: 78%; }

html[data-nd-theme='light'] .nt-auth-card.nt-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20ls — ** overview war-room · configure queue items · recon ── ** ── */
.nt-overview-shell .nt-stat-band {
  margin-bottom: 12px;
}
.nt-configure-queue__what {
  font-weight: 650;
}
.nt-config-queue .nt-configure-queue__item,
.nt-configure__queue .nt-queue-item {
  display: grid;
  gap: 4px;
  padding: 8px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  font-size: var(--nd-text-12, 12px);
}
.nt-recon-reveal {
  animation: nt-recon-in 280ms var(--nd-ease-out, ease) both;
}
@keyframes nt-recon-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
@media (prefers-reduced-motion: reduce) {
  .nt-recon-reveal,
  .nt-auth-wake-bar,
  .nt-chat-pending__pulse,
  .nt-shift-strip__dot--live {
    animation: none !important;
  }
}
.nt-empty-cinema.nt-empty-wake {
  text-align: center;
  padding: 28px 18px;
  border-radius: 16px;
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 24%, var(--nd-border));
  background:
    radial-gradient(120% 100% at 50% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 78%, transparent);
}
.nt-empty-wake__mark {
  display: inline-grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  margin-bottom: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  color: color-mix(in srgb, var(--nd-accent) 86%, var(--nd-text));
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
.nt-empty-cinema__kicker {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: color-mix(in srgb, var(--nd-accent) 72%, var(--nd-text-muted));
  margin-bottom: 6px;
}
.nt-empty-cinema__title {
  font-weight: 800;
  letter-spacing: -0.01em;
  margin-bottom: 6px;
}
.nt-empty-cinema__body {
  color: var(--nd-text-muted);
  line-height: 1.45;
  max-width: 46ch;
  margin: 0 auto 12px;
}

html[data-nd-theme='light'] .nt-empty-cinema.nt-empty-wake {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20lt — ** notify cinema · workspace chip · rail toggle ── ** ── */
.nt-notify-anchor {
  position: relative;
}
.nt-notify-bell--hot {
  color: color-mix(in srgb, var(--nd-danger) 88%, var(--nd-text));
}
.nt-notify-popover.nt-panel-glass {
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  width: min(360px, 92vw);
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-4, 0 28px 64px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
  padding: 10px;
  z-index: 40;
}
.nt-notify-popover--hot {
  border-color: color-mix(in srgb, var(--nd-danger) 34%, var(--nd-border));
}
.nt-notify-scroll {
  max-height: 320px;
  overflow: auto;
  display: grid;
  gap: 6px;
}
.nt-notify-empty {
  padding: 16px 10px;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  text-align: center;
}
.nt-notify-item {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
}
.nt-notify-item:hover {
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 16%, transparent);
}
.nt-notify-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  margin-top: 5px;
  background: var(--nd-accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}
.nt-notify-title--unread { font-weight: 750; }
.nt-notify-title--read { color: var(--nd-text-muted); }
.nt-notify-body {
  display: block;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  margin-top: 2px;
}
.nt-badge-count {
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-danger) 88%, transparent);
  color: white;
  font-size: 10px;
  font-weight: 800;
  padding: 1px 6px;
  font-variant-numeric: tabular-nums;
}
.nt-shell-workspace {
  padding: 10px 12px 12px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}
.nt-shell-workspace__name {
  font-weight: 700;
}
.nt-shell-workspace__linked {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-11, 11px);
}
.nt-shell-rail-toggle {
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 50%, transparent);
  color: var(--nd-text-muted);
  padding: 6px 8px;
  cursor: pointer;
}
.nt-shell-rail-toggle:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 36%, var(--nd-border));
  color: var(--nd-accent);
}

html[data-nd-theme='light'] .nt-notify-popover.nt-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}
/* avoid pure white token drift for badge text on light */
html[data-nd-theme='light'] .nt-badge-count {
  color: var(--nd-surface-0, white);
}

/* ── ** ── ** Wave 20lu — ** view-options cinema · floor shell · systems sections ── ** ── */
.nt-view-options {
  position: relative;
}
.nt-view-options__panel.nt-panel-glass {
  min-width: min(280px, 92vw);
  padding: 10px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  box-shadow: var(--nd-shadow-3, 0 18px 40px color-mix(in srgb, var(--nd-ink, black) 36%, transparent));
}
.nt-view-options__heading {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 72%, var(--nd-text-muted));
  font-weight: 750;
  padding: 2px 4px 8px;
}
.nt-view-options__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 4px;
  max-height: 320px;
  overflow: auto;
}
.nt-view-options__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid transparent;
}
.nt-view-options__item:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 14%, transparent);
}
.nt-view-options__check {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  min-width: 0;
}
.nt-view-options__moves {
  display: inline-flex;
  gap: 4px;
}
.nt-view-options__move {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 55%, transparent);
  color: var(--nd-text-muted);
  cursor: pointer;
  font-size: 12px;
  line-height: 1;
}
.nt-view-options__move:hover:not(:disabled),
.nt-view-options__move:focus-visible {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  color: var(--nd-accent);
  outline: none;
  box-shadow: 0 0 0 2px var(--nd-focus-ring, color-mix(in srgb, var(--nd-accent) 28%, transparent));
}
.nt-view-options__move:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}
.nt-view-options__reset {
  margin-top: 8px;
  width: 100%;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
  color: var(--nd-accent);
  font-weight: 650;
  padding: 7px 10px;
  cursor: pointer;
}
.nt-view-options__reset:hover,
.nt-view-options__reset:focus-visible {
  background: color-mix(in srgb, var(--nd-accent) 16%, transparent);
  outline: none;
}

.nt-floor-shell {
  position: relative;
}
.nt-floor-shell::before {
  content: "";
  position: absolute;
  inset: -6px 0 auto 0;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--nd-accent) 55%, transparent),
    transparent
  );
  pointer-events: none;
  opacity: 0.7;
}
.nt-floor-img {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 10%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
}

.nt-systems-section.nt-section-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--nd-accent) 6%, transparent),
      transparent 42%
    ),
    color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  box-shadow: var(--nd-shadow-1, 0 1px 0 color-mix(in srgb, var(--nd-ink, black) 18%, transparent));
  padding: 12px 14px;
}
.nt-systems-section + .nt-systems-section {
  margin-top: 12px;
}

html[data-nd-theme='light'] .nt-view-options__panel.nt-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}
html[data-nd-theme='light'] .nt-systems-section.nt-section-panel {
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--nd-accent) 5%, transparent),
      transparent 42%
    ),
    color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20lv — ** central/mist/device/site section cinema shells ── ** ── */
.nt-central-section.nt-section-panel,
.nt-mist-section.nt-section-panel,
.nt-device-section.nt-section-panel,
.nt-site-section.nt-section-panel {
  position: relative;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    linear-gradient(
      160deg,
