}

/* ── ** ── ** Wave 20ma — ** screen-header band · sticky filters · bulk glass ── ** ── */
.nt-screen-header.nt-toolbar-glass {
  position: sticky;
  top: 0;
  z-index: 12;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px 18px;
  align-items: end;
  padding: 12px 4px 14px;
  margin: 0 0 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-surface-0, var(--nd-surface-1)) 92%, transparent),
      color-mix(in srgb, var(--nd-surface-1) 78%, transparent)
    );
  backdrop-filter: blur(14px) saturate(1.08);
  -webkit-backdrop-filter: blur(14px) saturate(1.08);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 10%, transparent),
    0 10px 28px color-mix(in srgb, var(--nd-ink, black) 12%, transparent);
}
.nt-screen-header__brand {
  margin: 0 0 4px;
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
