  color: color-mix(in srgb, var(--nd-accent) 76%, var(--nd-text-muted));
}
.nt-modal-scrim,
.nd-modal-scrim,
.nd-modal__scrim {
  background: color-mix(in srgb, var(--nd-ink, black) 55%, transparent);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.nt-modal,
.nd-modal {
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 20%, var(--nd-border));
  background:
    linear-gradient(
      155deg,
      color-mix(in srgb, var(--nd-accent) 9%, transparent),
      transparent 42%
    ),
    color-mix(in srgb, var(--nd-surface-1) 97%, transparent);
  box-shadow: var(--nd-shadow-4, 0 28px 72px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
}
