}
.nt-hotkey-overlay.nt-panel-glass {
  position: relative;
  width: min(440px, 100%);
  max-height: min(72vh, 640px);
  overflow: auto;
  padding: 14px 16px 16px;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 20%, var(--nd-border));
  box-shadow: var(--nd-shadow-4, 0 28px 72px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
}
.nt-hotkey-overlay__header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 12px;
  align-items: start;
  margin-bottom: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}
.nt-hotkey-overlay__brand {
  grid-column: 1 / -1;
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 800;
  color: color-mix(in srgb, var(--nd-accent) 78%, var(--nd-text-muted));
}
.nt-hotkey-overlay__title {
  font-size: var(--nd-text-16, 16px);
  font-weight: 750;
  letter-spacing: -0.01em;
}
.nt-hotkey-overlay__close {
  border: 0;
  background: transparent;
  color: var(--nd-text-muted);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  border-radius: 8px;
  padding: 2px 8px;
}
.nt-hotkey-overlay__close:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
.nt-hotkey-overlay__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}
.nt-hotkey-overlay__item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid transparent;
}
.nt-hotkey-overlay__item:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 14%, transparent);
}

.nt-page-skeleton.nt-war-room-wake {
  display: grid;
  gap: 14px;
  padding: 8px 2px 18px;
}
.nt-page-skeleton__kicker {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 800;
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text-muted));
}
.nt-page-skeleton__header {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  align-items: center;
  justify-content: space-between;
}
.nt-page-skeleton__stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
}
.nt-page-skeleton__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
.nt-page-skeleton__row {
  border-radius: 12px !important;
}
@media (max-width: 820px) {
  .nt-page-skeleton__grid { grid-template-columns: 1fr; }
}

html[data-nd-theme='light'] .nt-hotkey-overlay.nt-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20md — ** inventory tree cinema · site topo surface ── ** ── */
.nt-inventory-tree-shell,
.nt-inventory-tree {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--nd-accent) 5%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 8px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-inventory-tree__error {
  margin: 4px 6px 8px;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-danger) 30%, var(--nd-border));
  color: color-mix(in srgb, var(--nd-danger) 88%, var(--nd-text));
  background: color-mix(in srgb, var(--nd-danger) 8%, transparent);
  font-size: var(--nd-text-12, 12px);
}
.nt-inventory-tree__row,
.nt-inventory-tree__node {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  gap: 6px;
  align-items: center;
  padding: 6px 8px;
  padding-left: calc(8px + (var(--nd-tree-level, 0) * 14px));
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
}
.nt-inventory-tree__row:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-inventory-tree__row--selected {
  background: color-mix(in srgb, var(--nd-accent) 14%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 16%, transparent);
}
.nt-inventory-tree__toggle {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 50%, transparent);
  color: var(--nd-text-muted);
  cursor: pointer;
}
.nt-inventory-tree__toggle:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 36%, var(--nd-border));
  color: var(--nd-accent);
}
.nt-inventory-tree__label {
  min-width: 0;
  font-weight: 650;
}
.nt-inventory-tree__count {
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-11, 11px);
  font-weight: 700;
}
.nt-inventory-tree__loading,
.nt-inventory-tree__more {
  padding-left: calc(36px + (var(--nd-tree-level, 0) * 14px));
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-inventory-tree--compact .nt-inventory-tree__row {
  padding-top: 4px;
  padding-bottom: 4px;
}

.nt-site-topo-shell.nt-section-panel,
.nt-topo-surface {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    radial-gradient(
      120% 80% at 10% 0%,
      color-mix(in srgb, var(--nd-accent) 10%, transparent),
      transparent 55%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 12px 14px;
}
.nt-topo-lane {
  position: relative;
  min-height: var(--nd-topo-h, 320px);
  border-radius: 14px;
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 35%, transparent),
      transparent
    );
  overflow: hidden;
}
.nt-topo-layer-label {
  position: absolute;
  left: 10px;
  top: var(--nd-topo-y, 0);
  transform: translateY(-50%);
  z-index: 1;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 10px;
  color: color-mix(in srgb, var(--nd-accent) 70%, var(--nd-text-muted));
  font-weight: 800;
  pointer-events: none;
}
.nt-topo-diagram {
  position: relative;
  width: 100%;
  height: 100%;
}
.nt-topo-node-card {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow: 0 8px 22px color-mix(in srgb, var(--nd-ink, black) 18%, transparent);
  padding: 8px 10px;
  transition: border-color 120ms ease, box-shadow 120ms ease, transform 120ms ease;
}
.nt-topo-node-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 34%, var(--nd-border));
  box-shadow: 0 12px 28px color-mix(in srgb, var(--nd-ink, black) 24%, transparent);
  transform: translateY(-1px);
}
.nt-topo-node-card--danger {
  border-color: color-mix(in srgb, var(--nd-danger) 36%, var(--nd-border));
}
.nt-topo-node-card--warning {
  border-color: color-mix(in srgb, var(--nd-warning) 36%, var(--nd-border));
}
.nt-topo-dot-9 {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--nd-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-accent) 18%, transparent);
  flex-shrink: 0;
}
.nt-topo-edge-tag {
  font-size: 10px;
  letter-spacing: 0.04em;
  padding: 1px 5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}

html[data-nd-theme='light'] .nt-inventory-tree-shell,
html[data-nd-theme='light'] .nt-site-topo-shell.nt-section-panel,
html[data-nd-theme='light'] .nt-topo-surface {
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--nd-accent) 4%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20me — ** table sort/resize cinema · virtual spacer ── ** ── */
.nt-table__sort {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  padding: 0;
}
.nt-table__sort:hover {
  color: var(--nd-accent);
}
.nt-table__resize {
  position: absolute;
  top: 0;
  right: 0;
  width: 5px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
}
.nt-table__resize::after {
  content: "";
  position: absolute;
  top: 20%;
  bottom: 20%;
  left: 2px;
  width: 1px;
  background: color-mix(in srgb, var(--nd-accent) 28%, transparent);
  opacity: 0;
  transition: opacity 120ms ease;
}
.nt-table__resize:hover::after,
.nt-table__resize:active::after {
  opacity: 1;
}
.nt-table-spacer {
  padding: 0 !important;
  border: 0 !important;
  line-height: 0;
}

/* cmdk residual cinema */
.nt-global-search,
.nt-cmdk {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 20%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-4, 0 28px 72px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}
.nt-global-search__input,
.nt-cmdk__input {
  border: 0;
  background: transparent;
  color: var(--nd-text);
  font: inherit;
  width: 100%;
  outline: none;
}
.nt-global-search__input:focus-visible,
.nt-cmdk__input:focus-visible {
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--nd-accent) 55%, transparent);
}
.nt-global-search__item[data-active='true'],
.nt-cmdk__item[aria-selected='true'] {
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 22%, transparent);
}

html[data-nd-theme='light'] .nt-global-search,
html[data-nd-theme='light'] .nt-cmdk {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20mf — ** chat cinema · diagnostics probes · overview war room ── ** ── */
.nt-chat-shell.nt-section-panel,
.nt-chat-col.nt-chat-shell {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 6%, transparent),
      transparent 42%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  overflow: hidden;
}
.nt-chat-scroll {
  min-height: 240px;
}
.nt-chat-bubble {
  border-radius: 14px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  max-width: min(560px, 92%);
  line-height: 1.45;
}
.nt-chat-bubble--user {
  background: color-mix(in srgb, var(--nd-accent) 14%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  margin-left: auto;
}
.nt-chat-bubble--assistant {
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 55%, transparent);
}
.nt-chat-tool-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(0, 1.2fr);
  gap: 8px;
  align-items: baseline;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  font-size: var(--nd-text-11, 11px);
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
}
.nt-chat-tool-row[data-ok='false'] {
  border-color: color-mix(in srgb, var(--nd-danger) 32%, var(--nd-border));
}
.nt-chat-tool-row__tool {
  font-weight: 750;
  color: var(--nd-accent);
}
.nt-chat-pending__pulse {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: var(--nd-accent);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--nd-accent) 45%, transparent);
  animation: nt-pending-pulse 1.4s ease-out infinite;
}
@keyframes nt-pending-pulse {
  0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--nd-accent) 42%, transparent); opacity: 1; }
  70% { box-shadow: 0 0 0 10px transparent; opacity: 0.85; }
  100% { box-shadow: 0 0 0 0 transparent; opacity: 0.7; }
}
@media (prefers-reduced-motion: reduce) {
  .nt-chat-pending__pulse { animation: none; }
}

.nt-diag.nt-diagnostics-shell,
.nt-diag-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 12px 14px;
}
.nt-diag__row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: baseline;
  padding: 8px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
}
.nt-diag__reason {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-diag__review {
  margin-top: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-warning) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-warning) 8%, transparent);
}
.nt-diag__review-title {
  font-weight: 750;
  letter-spacing: 0.02em;
  margin-bottom: 4px;
}

.nt-overview-shell.nt-section-panel {
  position: relative;
}
.nt-overview-shell.nt-section-panel::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--nd-accent) 60%, transparent),
    transparent
  );
  opacity: 0.65;
  pointer-events: none;
}
.nt-overview__layout {
  display: grid;
  gap: 14px;
}

.nt-facet-filter.nt-view-options {
  position: relative;
}

html[data-nd-theme='light'] .nt-chat-shell.nt-section-panel,
html[data-nd-theme='light'] .nt-diag.nt-diagnostics-shell,
html[data-nd-theme='light'] .nt-chat-bubble--assistant {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mg — ** DS gallery copper theater · swatches · form grid ── ** ── */
.nt-dsg-shell {
  --nd-dsg-glow: color-mix(in srgb, var(--nd-accent) 14%, transparent);
}
.nt-dsg-content.nt-section-panel {
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  background:
    radial-gradient(90% 60% at 0% 0%, var(--nd-dsg-glow, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 16px 18px 22px;
  box-shadow: var(--nd-shadow-2, 0 12px 32px color-mix(in srgb, var(--nd-ink, black) 18%, transparent));
}
.nt-dsg-brand-kicker {
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 800;
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text-muted));
}
.nt-dsg-brand-title {
  font-weight: 800;
  letter-spacing: -0.02em;
  font-size: var(--nd-text-18, 18px);
}
.nt-dsg-nav-label {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 750;
  color: var(--nd-text-muted);
}
.nt-dsg-workspace {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
}
.nt-dsg-search {
  position: relative;
  min-width: min(280px, 42vw);
}
.nt-dsg-search__input {
  width: 100%;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
  padding: 8px 74px 8px 12px;
  color: var(--nd-text);
}
.nt-dsg-search__input:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  box-shadow: 0 0 0 3px var(--nd-focus-ring, color-mix(in srgb, var(--nd-accent) 24%, transparent));
}
.nt-dsg-search__kbd {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  gap: 4px;
  pointer-events: none;
}
.nt-dsg-subtitle {
  color: var(--nd-text-muted);
  max-width: 54ch;
  line-height: 1.45;
}
.nt-dsg-sync {
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
}
.nt-dsg-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 14px 0;
}
.nt-dsg-main {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.9fr);
  gap: 14px;
}
.nt-dsg-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.nt-dsg-swatch-card {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent);
  padding: 12px;
  display: grid;
  gap: 8px;
}
.nt-dsg-device-name { font-weight: 750; }
.nt-dsg-device-model { color: var(--nd-text-muted); font-size: var(--nd-text-12, 12px); }

@media (max-width: 960px) {
  .nt-dsg-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .nt-dsg-main,
  .nt-dsg-form-grid { grid-template-columns: 1fr; }
}

html[data-nd-theme='light'] .nt-dsg-content.nt-section-panel {
  background:
    radial-gradient(90% 60% at 0% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mh — ** SSE / webhooks shells · banner rails ── ** ── */
.nt-sse-shell.nt-section-panel,
.nt-webhooks-shell.nt-section-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 5%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 12px 14px;
}
.nt-sse-banner {
  border-radius: 12px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.45;
}
.nt-sse-banner.nt-border-success {
  border-color: color-mix(in srgb, var(--nd-success) 36%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-success) 8%, transparent);
}
.nt-sse-banner.nt-border-warning {
  border-color: color-mix(in srgb, var(--nd-warning) 36%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-warning) 8%, transparent);
}
.nt-webhook-pre {
  display: block;
  white-space: pre-wrap;
  word-break: break-word;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 50%, transparent);
  padding: 10px 12px;
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nd-text-11, 11px);
  line-height: 1.45;
}

html[data-nd-theme='light'] .nt-sse-shell.nt-section-panel,
html[data-nd-theme='light'] .nt-webhooks-shell.nt-section-panel {
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 4%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mi — ** callout glass · api-error · backend banner residual ── ** ── */
.nt-callout,
.nd-callout {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  padding: 12px 14px;
