  border: 1px solid color-mix(in srgb, var(--nd-warning) 32%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-warning) 10%, transparent);
  padding: 10px 12px;
  font-size: var(--nd-text-12, 12px);
}

html[data-nd-theme='light'] .nt-callout,
html[data-nd-theme='light'] .nt-api-error,
html[data-nd-theme='light'] .nt-api-error-state {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mj — ** heading dual · topo3d glass cinema · root ── ** ── */
.nt-root {
  min-height: 100%;
  color: var(--nd-text);
  background: var(--nd-surface-0, var(--nd-surface-1));
}
.nt-heading {
  margin: 0;
  letter-spacing: -0.02em;
  font-weight: 750;
  color: var(--nd-text);
}
.nt-heading--1 { font-size: var(--nd-text-28, 1.75rem); line-height: 1.15; }
.nt-heading--2 { font-size: var(--nd-text-22, 1.375rem); line-height: 1.2; }
.nt-heading--3 { font-size: var(--nd-text-18, 1.125rem); line-height: 1.25; }
.nt-heading--4 { font-size: var(--nd-text-16, 1rem); line-height: 1.3; }

.nt-topo3d-shell.nt-panel-glass,
.nt-topo3d.nt-topo-host {
  position: relative;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background:
    radial-gradient(
      80% 70% at 20% 0%,
      color-mix(in srgb, var(--nd-accent) 12%, transparent),
      transparent 60%
    ),
    color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  overflow: hidden;
  min-height: 420px;
  box-shadow: var(--nd-shadow-3, 0 18px 48px color-mix(in srgb, var(--nd-ink, black) 28%, transparent));
}
.nt-topo3d__brand {
  position: absolute;
  top: 12px;
  left: 14px;
  z-index: 2;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 800;
  color: color-mix(in srgb, var(--nd-accent) 78%, var(--nd-text-muted));
  pointer-events: none;
}
.nt-topo3d__canvas {
  width: 100%;
  height: 100%;
  min-height: 420px;
}
.nt-topo3d__glass {
  position: absolute;
  z-index: 2;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  backdrop-filter: blur(12px) saturate(1.08);
  -webkit-backdrop-filter: blur(12px) saturate(1.08);
  padding: 10px 12px;
  box-shadow: 0 12px 28px color-mix(in srgb, var(--nd-ink, black) 22%, transparent);
  max-width: min(280px, 70%);
}
.nt-topo3d__glass--tl { top: 36px; left: 14px; }
.nt-topo3d__glass--br { bottom: 14px; right: 14px; }
.nt-topo3d__title {
  font-weight: 750;
  letter-spacing: -0.01em;
}
.nt-topo3d__meta,
.nt-topo3d__stat {
  margin-top: 4px;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.4;
}

html[data-nd-theme='light'] .nt-topo3d-shell.nt-panel-glass,
html[data-nd-theme='light'] .nt-topo3d__glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 92%, transparent);
}

/* ── ** ── ** Wave 20mk — ** spinner copper · incident spine cinema ── ** ── */
.nt-spinner,
.nd-spinner.nt-spinner {
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 999px;
  border: 2px solid color-mix(in srgb, var(--nd-accent) 22%, transparent);
  border-top-color: var(--nd-accent);
  animation: nt-spin 0.7s linear infinite;
  vertical-align: middle;
}
.nd-spinner--sm.nt-spinner,
.nt-spinner.nd-spinner--sm { width: 14px; height: 14px; border-width: 2px; }
.nd-spinner--md.nt-spinner,
.nt-spinner.nd-spinner--md { width: 22px; height: 22px; border-width: 2.5px; }
@keyframes nt-spin {
  to { transform: rotate(360deg); }
}
@media (prefers-reduced-motion: reduce) {
  .nt-spinner,
  .nd-spinner.nt-spinner {
    animation: none;
    border-top-color: var(--nd-text-muted);
    opacity: 0.75;
  }
}

.nt-incident-spine {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-accent) 10%, transparent),
      transparent 55%
    ),
    color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 12%, transparent);
  margin: 0 0 12px;
}
.nt-incident-spine__step {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 750;
  color: var(--nd-text-muted);
}
.nt-incident-spine__step[data-active='true'] {
  color: var(--nd-accent);
  text-shadow: 0 0 18px color-mix(in srgb, var(--nd-accent) 35%, transparent);
}
.nt-incident-spine__chev {
  color: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-text-muted));
  opacity: 0.8;
  user-select: none;
}
.nt-alert-spine.nt-incident-spine {
  border-color: color-mix(in srgb, var(--nd-danger) 24%, var(--nd-border));
}

html[data-nd-theme='light'] .nt-incident-spine {
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-accent) 8%, transparent),
      transparent 55%
    ),
    color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20ml — ** overview bulk glass · sites preview · launchpad ── ** ── */
.nt-overview__layout {
  display: grid;
  gap: 16px;
}
.nt-overview .nt-configure-bulk-bar {
  margin-top: 8px;
}
.nt-overview .nt-chip-row {
  margin: 6px 0 10px;
}
.nt-launchpad,
.nt-overview-launchpad {
  display: grid;
  gap: 8px;
}
.nt-launchpad__row,
.nt-overview-launchpad__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent);
  cursor: pointer;
  text-align: left;
}
.nt-launchpad__row:hover,
.nt-overview-launchpad__row:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-health-bar.nt-plane-ecg {
  width: 72px;
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 70%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
}
.nt-health-bar__fill,
.nt-health-fill {
  display: block;
  height: 100%;
  width: var(--nd-health, 50%);
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-accent) 70%, transparent),
    var(--nd-accent)
  );
  box-shadow: 0 0 12px color-mix(in srgb, var(--nd-accent) 35%, transparent);
}
.nt-fill-success { background: linear-gradient(90deg, color-mix(in srgb, var(--nd-success) 60%, transparent), var(--nd-success)); }
.nt-fill-warning { background: linear-gradient(90deg, color-mix(in srgb, var(--nd-warning) 60%, transparent), var(--nd-warning)); }
.nt-fill-danger { background: linear-gradient(90deg, color-mix(in srgb, var(--nd-danger) 60%, transparent), var(--nd-danger)); }
.nt-fill-neutral { background: linear-gradient(90deg, color-mix(in srgb, var(--nd-text-muted) 40%, transparent), var(--nd-text-muted)); }

html[data-nd-theme='light'] .nt-launchpad__row {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20mm — ** global search recent bulk · cmdk cinema residual ── ** ── */
.nt-global-search__recent {
  display: grid;
  gap: 6px;
  padding: 8px 10px 10px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 82%, transparent);
}
.nt-global-search__recent-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid transparent;
}
.nt-global-search__recent-row:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-global-search__recent-bulk {
  margin-top: 6px;
}
.nt-global-search__kind[data-kind='recent'] {
  color: color-mix(in srgb, var(--nd-accent) 75%, var(--nd-text-muted));
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 10px;
  font-weight: 800;
}

/* compliance residual densify */
.nt-compliance-shell,
.nt-compliance {
  position: relative;
}
.nt-compliance-shell::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--nd-warning) 50%, var(--nd-accent)),
    transparent
  );
