}

/* alerts toolbar residual */
.nt-alerts__toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  padding: 10px 12px;
  margin: 0 0 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
