  color: var(--nd-text);
}
.nt-tickets__site {
  font-size: 11px;
  color: var(--nd-text-secondary);
}
.nt-tickets__pager {
  padding: 8px 4px 4px;
}

html[data-nd-theme='light'] .nt-alerts__toolbar,
html[data-nd-theme='light'] .nt-ticket-body,
html[data-nd-theme='light'] .nt-ticket-note {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mq — ** configure switch-tree · write ritual · chip-row cinema ── ** ── */
.nt-configure__layout {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
@media (max-width: 1100px) {
  .nt-configure__layout { grid-template-columns: 1fr; }
}
.nt-configure__col {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--nd-accent) 6%, transparent),
      transparent 48%
    ),
    color-mix(in srgb, var(--nd-surface-1) 93%, transparent);
  padding: 12px 12px 14px;
  min-width: 0;
}
.nt-configure-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px 12px;
  align-items: start;
  padding: 10px 10px;
  border-radius: 12px;
  border: 1px solid transparent;
  cursor: pointer;
}
.nt-configure-row:hover,
.nt-configure-row:focus-visible {
  border-color: color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 7%, transparent);
  outline: none;
}
.nt-configure-row__name-primary {
  font-weight: 650;
  color: var(--nd-text);
}
.nt-configure-row__name-meta,
.nt-configure-row__secondary,
.nt-configure-row__summary,
.nt-configure-row__note {
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-configure-row__actions {
  display: inline-flex;
  gap: 6px;
  align-items: center;
}

/* switch tree */
.nt-switch-tree {
  display: grid;
  gap: 6px;
  margin-top: 8px;
}
.nt-switch-tree__toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 8px;
}
.nt-switch-tree__group {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 35%, transparent);
  overflow: hidden;
}
.nt-switch-tree__switch {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: 0;
  background: transparent;
  color: var(--nd-text);
  text-align: left;
  padding: 10px 12px;
  cursor: pointer;
  font: inherit;
}
.nt-switch-tree__switch:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-switch-tree__chevron {
  width: 16px;
  text-align: center;
  color: var(--nd-accent);
  font-weight: 700;
}
.nt-switch-tree__identity {
  min-width: 0;
  font-weight: 600;
}

/* write ritual banner residual */
.nt-card--write-ritual,
.nd-card.nt-card--write-ritual {
  position: relative;
  overflow: hidden;
  border-color: color-mix(in srgb, var(--nd-warning) 30%, var(--nd-border)) !important;
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-warning) 12%, transparent),
    var(--nd-shadow-2, 0 10px 28px color-mix(in srgb, var(--nd-ink, black) 28%, transparent));
}
.nt-write-ritual--banner {
  height: 3px;
  margin: -4px -4px 10px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--nd-warning) 70%, var(--nd-accent)),
    color-mix(in srgb, var(--nd-accent) 65%, transparent),
    transparent
  );
  opacity: 0.9;
}

/* chip row residual */
.nt-chip-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 6px 0;
}
.nt-chip-row__label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-muted, var(--nd-text-secondary));
  margin-right: 4px;
}
.nt-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent);
  color: var(--nd-text-secondary);
  padding: 4px 10px;
  font-size: 12px;
  cursor: pointer;
}
.nt-chip--active,
.nt-chip[data-active='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 14%, transparent);
  color: var(--nd-accent);
  font-weight: 650;
}
.nt-chip__count {
  font-variant-numeric: tabular-nums;
  font-size: 10px;
  opacity: 0.85;
}

/* plane theater residual pulse */
.nt-plane-theater {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  padding: 4px 2px 10px;
  font-size: 11px;
  letter-spacing: 0.04em;
  color: color-mix(in srgb, var(--nd-text-secondary) 92%, var(--nd-accent));
}
.nt-plane-theater::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--nd-accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--nd-accent) 16%, transparent);
  animation: nt-plane-ecg 2.4s ease-in-out infinite;
}
@keyframes nt-plane-ecg {
  0%, 100% { transform: scale(1); opacity: 0.85; }
  50% { transform: scale(1.25); opacity: 1; }
}

html[data-nd-theme='light'] .nt-configure__col,
html[data-nd-theme='light'] .nt-switch-tree__group {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .nt-plane-theater::before { animation: none; }
}

/* ── ** ── ** Wave 20mr — ** inventory tree · clients · sites health residual ── ** ── */
.nt-inventory-shell.nt-section-panel,
.nt-clients-shell.nt-section-panel,
.nt-sites-shell.nt-section-panel {
  position: relative;
}
.nt-inventory-shell.nt-section-panel::after,
.nt-clients-shell.nt-section-panel::after,
.nt-sites-shell.nt-section-panel::after {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0 0 auto 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 4%,
    color-mix(in srgb, var(--nd-accent) 45%, transparent),
    transparent 96%
  );
  opacity: 0.55;
}

/* inventory tree residual */
.nt-inventory-tree,
.nt-tree {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  padding: 8px;
}
.nt-tree__node,
.nt-inventory-tree__node {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  gap: 6px;
  align-items: center;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid transparent;
}
.nt-tree__node:hover,
.nt-inventory-tree__node:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-tree__node[data-selected='true'],
.nt-inventory-tree__node[aria-selected='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
}

/* clients residual */
.nt-clients__toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 8px 10px;
  margin-bottom: 10px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
}

/* sites health bars via token */
.nt-sites-shell .nt-progress-rail,
.nt-sites-shell .nd-progress {
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--nd-border) 55%, transparent);
}
.nt-sites-shell .nt-progress-rail__fill,
.nt-sites-shell .nd-progress__fill {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-success) 80%, var(--nd-accent)),
    var(--nd-accent)
  );
}

/* mono link residual */
.nt-mono-link,
.nt-micro-link {
  color: color-mix(in srgb, var(--nd-accent) 88%, var(--nd-text));
  text-decoration: none;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 28%, transparent);
}
.nt-mono-link:hover,
.nt-micro-link:hover {
  color: var(--nd-accent);
  border-bottom-color: color-mix(in srgb, var(--nd-accent) 55%, transparent);
}

/* filter field residual */
.nt-filter-field {
  display: grid;
  gap: 4px;
  min-width: 0;
}
.nt-filter-field--md { min-width: 160px; }
.nt-filter-bar.nt-sticky-filters {
  position: sticky;
  top: var(--nd-sticky-top, 0px);
  z-index: var(--nd-z-sticky, 20);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  padding: 10px 12px;
  margin-bottom: 12px;
}

html[data-nd-theme='light'] .nt-inventory-tree,
html[data-nd-theme='light'] .nt-tree,
html[data-nd-theme='light'] .nt-clients__toolbar,
html[data-nd-theme='light'] .nt-filter-bar.nt-sticky-filters {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20ms — ** shift strip · incident strip · auth gate residual ── ** ── */
.nt-shift-strip,
.nd-shift-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  min-height: 34px;
  padding: 6px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-accent) 8%, transparent),
      transparent 40%,
      color-mix(in srgb, var(--nd-danger, var(--nd-accent)) 6%, transparent)
    ),
    color-mix(in srgb, var(--nd-surface-0, var(--nd-surface-1)) 92%, transparent);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  font-size: 11px;
  letter-spacing: 0.04em;
}
.nt-shift-strip[data-p1='true'],
.nd-shift-strip[data-p1='true'] {
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--nd-danger) 55%, transparent);
}
.nt-shift-strip[data-degraded='true'] {
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--nd-warning) 50%, transparent);
}
.nt-shift-strip__chip,
.nt-shift-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 70%, transparent);
  color: var(--nd-text-secondary);
  font-variant-numeric: tabular-nums;
}

.nt-incident-strip,
.nd-incident-strip {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-danger) 28%, var(--nd-border));
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-danger) 16%, transparent),
      color-mix(in srgb, var(--nd-danger) 4%, transparent) 55%,
      transparent
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
}
.nt-incident-strip__pulse {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--nd-danger);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--nd-danger) 18%, transparent);
}

.nt-auth-panel {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(60% 50% at 50% 0%, color-mix(in srgb, var(--nd-accent) 14%, transparent), transparent 70%),
    var(--nd-surface-0, var(--nd-surface-1));
}
.nt-auth-card {
  width: min(420px, 100%);
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-3, 0 22px 50px color-mix(in srgb, var(--nd-ink, black) 40%, transparent));
  padding: 22px 22px 20px;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}
.nt-auth-wake-bar {
  display: block;
  height: 3px;
  border-radius: 999px;
  margin: 0 0 16px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--nd-accent),
    color-mix(in srgb, var(--nd-warning) 50%, var(--nd-accent)),
    transparent
  );
}

.nt-topbar,
.nd-topbar,
.nt-app-topbar {
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0, var(--nd-surface-1)) 82%, transparent);
  backdrop-filter: blur(16px) saturate(1.15);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
}

html[data-nd-theme='light'] .nt-shift-strip,
html[data-nd-theme='light'] .nt-incident-strip,
html[data-nd-theme='light'] .nt-auth-card,
html[data-nd-theme='light'] .nt-topbar {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mt — ** platforms group · sidebar nav · shell residual ── ** ── */
.nt-shell-navgroup,
.nt-sidebar-nav {
  display: grid;
  gap: 2px;
  padding: 6px 8px 10px;
}
.nt-shell-navgroup--platforms.nt-platforms-group {
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
}
.nt-shell-navgroup__label,
.nt-shell-navgroup__toggle,
.nt-platforms-group__toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  border: 0;
  background: transparent;
  color: var(--nd-text-muted, var(--nd-text-secondary));
  text-align: left;
  padding: 6px 8px;
  border-radius: 8px;
  cursor: pointer;
  font: inherit;
}
.nt-shell-navgroup__toggle:hover,
.nt-platforms-group__toggle:hover {
  color: var(--nd-accent);
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-shell-navgroup--collapsed .nt-shell-navlink:not([aria-current='page']) {
  display: none;
}
.nt-shell-navlink,
.nt-nav-link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  color: var(--nd-text-secondary);
  text-decoration: none;
  border: 1px solid transparent;
  font-size: 13px;
}
.nt-shell-navlink:hover,
.nt-nav-link:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-shell-navlink[aria-current='page'],
.nt-shell-navlink[data-active='true'],
.nt-nav-link[aria-current='page'] {
  color: var(--nd-accent);
  border-color: color-mix(in srgb, var(--nd-accent) 22%, transparent);
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-accent) 14%, transparent),
      color-mix(in srgb, var(--nd-accent) 4%, transparent)
    );
  font-weight: 650;
  box-shadow: inset 2px 0 0 var(--nd-accent);
}

/* brand mark residual */
.nt-shell-brand,
.nt-app-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px 10px;
  color: var(--nd-text);
  text-decoration: none;
}
.nt-shell-brand__mark {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: color-mix(in srgb, var(--nd-surface-0, black) 20%, white);
  background: linear-gradient(
    145deg,
    color-mix(in srgb, var(--nd-accent) 88%, white),
    color-mix(in srgb, var(--nd-accent) 55%, var(--nd-warning))
  );
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--nd-accent) 30%, transparent),
    0 8px 18px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}
.nt-shell-brand__name {
  font-weight: 750;
  letter-spacing: 0.02em;
  font-size: 15px;
  color: var(--nd-text);
}
.nt-shell-brand__kicker {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 75%, var(--nd-text-secondary));
}
.nt-shell-brand__tagline {
  font-size: 11px;
  color: var(--nd-text-secondary);
}
.nt-shell-brand__copy {
  display: grid;
  gap: 1px;
  min-width: 0;
}

/* sidebar shell glass */
.nt-shell-sidebar,
.nt-app-sidebar {
  border-right: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-accent) 6%, transparent),
      transparent 28%
    ),
    color-mix(in srgb, var(--nd-surface-0, var(--nd-surface-1)) 94%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

html[data-nd-theme='light'] .nt-shell-sidebar,
html[data-nd-theme='light'] .nt-app-sidebar,
html[data-nd-theme='light'] .nt-shell-navlink[aria-current='page'] {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20mu — ** mobile nav · bulk bar · empty wake residual ── ** ── */
.nt-mobile-nav {
  position: fixed;
  inset: 0;
  z-index: var(--nd-z-modal, 80);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  background: color-mix(in srgb, var(--nd-surface-0, var(--nd-surface-1)) 96%, transparent);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}
.nt-mobile-nav__brand {
  padding: 14px 16px 8px;
  font-weight: 750;
  letter-spacing: 0.04em;
  color: var(--nd-accent);
}
.nt-mobile-nav__list {
  overflow: auto;
  padding: 8px 12px 24px;
  display: grid;
  gap: 4px;
}

/* bulk selection bar cinema */
.nt-bulk-bar,
.nd-bulk-bar,
.nt-selection-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-accent) 12%, transparent),
      color-mix(in srgb, var(--nd-accent) 4%, transparent)
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow: var(--nd-shadow-2, 0 10px 24px color-mix(in srgb, var(--nd-ink, black) 24%, transparent));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.nt-bulk-bar__count {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--nd-accent);
}

/* empty state wake residual */
.nt-empty,
.nd-empty,
.nt-empty-state {
  display: grid;
  justify-items: center;
  gap: 10px;
  text-align: center;
  padding: 36px 18px;
  border-radius: 16px;
  border: 1px dashed color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    radial-gradient(50% 60% at 50% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 70%),
    color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
}
.nt-empty__mark,
.nt-empty-wake__mark,
.nt-empty-cinema .nt-empty-wake__mark {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: color-mix(in srgb, var(--nd-surface-0, black) 15%, white);
  background: linear-gradient(
    145deg,
    color-mix(in srgb, var(--nd-accent) 85%, white),
    color-mix(in srgb, var(--nd-accent) 50%, var(--nd-warning))
  );
  box-shadow: 0 10px 24px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}
.nt-empty__title {
  font-weight: 700;
  color: var(--nd-text);
}
.nt-empty__body {
  max-width: 36ch;
  color: var(--nd-text-secondary);
  font-size: 13px;
}

/* selection deep-link chip residual */
.nt-selection-chip,
.nt-ids-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  color: var(--nd-accent);
  font-size: 12px;
  font-weight: 650;
}

html[data-nd-theme='light'] .nt-mobile-nav,
html[data-nd-theme='light'] .nt-bulk-bar,
html[data-nd-theme='light'] .nt-empty {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20mv — ** cmdk cinema · notify drawer · toast stack residual ── ** ── */
.nt-cmdk,
.nt-global-search,
.nd-cmdk {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-4, 0 28px 64px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  overflow: hidden;
}
.nt-cmdk__input,
.nt-global-search__input {
  width: 100%;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: transparent;
  color: var(--nd-text);
  padding: 14px 16px;
  font: inherit;
  font-size: 15px;
}
.nt-cmdk__input:focus,
.nt-global-search__input:focus {
  outline: none;
}
.nt-cmdk__group-label {
  padding: 8px 14px 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted, var(--nd-text-secondary));
}
.nt-cmdk__item,
.nt-global-search__item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px 14px;
  cursor: pointer;
  border: 0;
  width: 100%;
  background: transparent;
  color: var(--nd-text);
  text-align: left;
  font: inherit;
}
.nt-cmdk__item[data-active='true'],
.nt-cmdk__item:hover,
.nt-global-search__item[data-active='true'],
.nt-global-search__item:hover {
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  color: var(--nd-accent);
}

/* notify drawer residual */
.nt-notify-drawer,
.nt-notifications-panel {
  display: grid;
  gap: 8px;
  padding: 8px;
}
.nt-notify-item {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent);
  padding: 10px 12px;
}
.nt-notify-item[data-tone='danger'] {
  border-color: color-mix(in srgb, var(--nd-danger) 30%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-notify-item[data-tone='warning'] {
  border-color: color-mix(in srgb, var(--nd-warning) 30%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-warning);
}

/* toast stack residual */
.nt-toast-stack,
.nd-toast-viewport {
  display: grid;
  gap: 8px;
  padding: 12px;
}
.nt-toast,
.nd-toast {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-2, 0 12px 28px color-mix(in srgb, var(--nd-ink, black) 28%, transparent));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 10px 12px;
}
.nt-toast--success { border-color: color-mix(in srgb, var(--nd-success) 35%, var(--nd-border)); }
.nt-toast--warning { border-color: color-mix(in srgb, var(--nd-warning) 35%, var(--nd-border)); }
.nt-toast--danger,
.nt-toast--error { border-color: color-mix(in srgb, var(--nd-danger) 35%, var(--nd-border)); }

html[data-nd-theme='light'] .nt-cmdk,
html[data-nd-theme='light'] .nt-global-search,
html[data-nd-theme='light'] .nt-toast,
html[data-nd-theme='light'] .nt-notify-item {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20mw — ** badge monochrome planes · status hue residual ── ** ── */
/* State owns hue; planes stay monochrome chips */
.nt-plane-chip,
.nt-badge--plane,
.nd-badge--plane {
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 55%, transparent);
  color: var(--nd-text-secondary);
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 10px;
  padding: 2px 8px;
}
.nt-plane-chip[data-plane='central'],
.nt-plane-chip[data-plane='mist'],
.nt-plane-chip[data-plane='clearpass'],
.nt-plane-chip[data-plane='sse'],
.nt-plane-chip[data-plane='greenlake'] {
  /* monochrome — no plane-colored fill */
  filter: none;
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 60%, transparent);
  color: var(--nd-text-secondary);
  border-color: color-mix(in srgb, var(--nd-border) 92%, transparent);
}

/* health/status owns hue */
.nt-badge--success,
.nd-badge--success,
[data-tone='success'].nt-badge,
[data-tone='healthy'].nt-badge {
  color: var(--nd-success);
  border-color: color-mix(in srgb, var(--nd-success) 35%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-success) 12%, transparent);
}
.nt-badge--warning,
.nd-badge--warning,
[data-tone='warning'].nt-badge,
[data-tone='degraded'].nt-badge {
  color: var(--nd-warning);
  border-color: color-mix(in srgb, var(--nd-warning) 35%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-warning) 12%, transparent);
}
.nt-badge--danger,
.nd-badge--danger,
[data-tone='danger'].nt-badge,
[data-tone='critical'].nt-badge {
  color: var(--nd-danger);
  border-color: color-mix(in srgb, var(--nd-danger) 35%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-danger) 12%, transparent);
}
.nt-badge--info,
.nd-badge--info,
[data-tone='info'].nt-badge {
  color: var(--nd-info, var(--nd-accent));
  border-color: color-mix(in srgb, var(--nd-info, var(--nd-accent)) 35%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-info, var(--nd-accent)) 12%, transparent);
}

/* firmware chips stay neutral */
.nt-badge--firmware,
.nt-firmware-chip {
  color: var(--nd-text-secondary);
  border-color: color-mix(in srgb, var(--nd-border) 90%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
  font-family: var(--nd-font-mono, ui-monospace, monospace);
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
}

/* ── ** ── ** Wave 20mx — ** bulk glass · configure bulk bar residual ── ** ── */
.nt-configure-bulk-bar,
.nt-bulk-glass,
.nt-configure-bulk-bar.nt-bulk-glass {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 12px;
  margin-top: 10px;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background:
    linear-gradient(
      100deg,
      color-mix(in srgb, var(--nd-accent) 14%, transparent),
      color-mix(in srgb, var(--nd-accent) 4%, transparent) 55%,
      transparent
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow: var(--nd-shadow-2, 0 12px 28px color-mix(in srgb, var(--nd-ink, black) 26%, transparent));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.nt-configure-bulk-bar__count {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--nd-accent);
  font-variant-numeric: tabular-nums;
}
.nt-configure-bulk-bar__hint {
  flex: 1 1 180px;
  min-width: 0;
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-configure-bulk-bar__actions {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  margin-left: auto;
}

/* greenlake shell residual */
.nt-greenlake-shell.nt-section-panel {
  position: relative;
}
.nt-greenlake-shell .nt-plane-theater {
  margin-bottom: 4px;
}

html[data-nd-theme='light'] .nt-configure-bulk-bar,
html[data-nd-theme='light'] .nt-bulk-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20my — ** button copper residual · focus ladder ── ** ── */
.nd-btn,
.nt-btn {
  border-radius: 10px;
  font-weight: 650;
  letter-spacing: 0.01em;
  transition: background 120ms ease, border-color 120ms ease, box-shadow 120ms ease, color 120ms ease;
}
.nd-btn:focus-visible,
.nt-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--nd-focus-ring, color-mix(in srgb, var(--nd-accent) 28%, transparent));
}
.nd-btn--primary,
.nt-btn--primary {
  background: linear-gradient(
    165deg,
    color-mix(in srgb, var(--nd-accent) 92%, white),
    color-mix(in srgb, var(--nd-accent) 72%, var(--nd-warning))
  );
  border-color: color-mix(in srgb, var(--nd-accent) 55%, transparent);
  color: color-mix(in srgb, var(--nd-surface-0, black) 12%, white);
  box-shadow: 0 8px 18px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}
.nd-btn--primary:hover,
.nt-btn--primary:hover {
  filter: brightness(1.05);
}
.nd-btn--secondary,
.nt-btn--secondary {
  border-color: color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
  color: var(--nd-text);
}
.nd-btn--ghost,
.nt-btn--ghost {
  background: transparent;
  border-color: transparent;
  color: var(--nd-text-secondary);
}
.nd-btn--ghost:hover,
.nt-btn--ghost:hover {
  color: var(--nd-accent);
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
}

/* card elevation residual */
.nd-card,
.nt-card {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow: var(--nd-shadow-1, 0 6px 16px color-mix(in srgb, var(--nd-ink, black) 18%, transparent));
}

/* section header residual */
.nd-section-header,
.nt-section-header,
.nt-table-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
}
.nd-section-header__meta,
.nt-table-toolbar__meta {
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-secondary);
  font-variant-numeric: tabular-nums;
}

html[data-nd-theme='light'] .nd-card,
html[data-nd-theme='light'] .nt-card,
html[data-nd-theme='light'] .nd-btn--secondary {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20mz — ** device detail · compliance · fact grid residual ── ** ── */
.nt-device-shell.nt-section-panel,
.nt-compliance-shell.nt-section-panel {
  position: relative;
}
.nt-device-shell .nt-incident-spine,
.nt-device-detail .nt-incident-spine {
  margin: 4px 0 12px;
}

/* fact grid residual */
.nt-fact-grid,
.nt-facts {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 10px 14px;
  padding: 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
}
.nt-fact,
.nt-fact-row {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.nt-fact__k,
.nt-fact-key {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-muted, var(--nd-text-secondary));
}
.nt-fact__v,
.nt-fact-val {
  font-size: 13px;
  font-weight: 600;
  color: var(--nd-text);
  font-variant-numeric: tabular-nums;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* compliance baseline residual */
.nt-baseline-bar {
  display: grid;
  gap: 4px;
}
.nt-baseline-bar .nt-progress-rail,
.nt-baseline-bar .nd-progress {
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--nd-border) 55%, transparent);
}
.nt-baseline-bar .nt-progress-rail__fill,
.nt-baseline-bar .nd-progress__fill {
  height: 100%;
  width: var(--nd-health, 0%);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-success) 70%, var(--nd-accent)),
    var(--nd-accent)
  );
  border-radius: inherit;
}

/* bar fill residual */
.nt-bar-track {
  height: 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-border) 55%, transparent);
  overflow: hidden;
}
.nt-bar-fill,
.nt-trend-fill {
  display: block;
  height: 100%;
  width: var(--nd-health, 0%);
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-accent) 75%, transparent),
    var(--nd-accent)
  );
}

/* recon reveal residual */
.nt-recon-reveal {
  animation: nt-recon-in 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes nt-recon-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .nt-recon-reveal { animation: none; }
}

html[data-nd-theme='light'] .nt-fact-grid,
html[data-nd-theme='light'] .nt-facts {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20na — ** tabs underline copper · checkbox · radio residual ── ** ── */
.nd-tabs__list,
.nt-tabs__list {
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  margin-bottom: 12px;
}
.nd-tabs__tab,
.nt-tabs__tab {
  position: relative;
  border: 0;
  background: transparent;
  color: var(--nd-text-secondary);
  padding: 10px 12px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  border-radius: 10px 10px 0 0;
}
.nd-tabs__tab:hover,
.nt-tabs__tab:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nd-tabs__tab[data-state='active'],
.nd-tabs__tab[aria-selected='true'],
.nt-tabs__tab[data-state='active'],
.nt-tabs__tab[aria-selected='true'] {
  color: var(--nd-accent);
}
.nd-tabs__tab[data-state='active']::after,
.nd-tabs__tab[aria-selected='true']::after,
.nt-tabs__tab[data-state='active']::after,
.nt-tabs__tab[aria-selected='true']::after {
  content: "";
  position: absolute;
  left: 10px;
  right: 10px;
  bottom: -1px;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, var(--nd-accent), transparent);
}

/* form checkbox residual */
.nd-checkbox,
.nt-checkbox {
  accent-color: var(--nd-accent);
}

/* toggle chip residual densify */
.nt-toggle-chip {
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent);
  color: var(--nd-text-secondary);
  padding: 5px 12px;
  font-size: 12px;
  font-weight: 650;
  cursor: pointer;
}
.nt-toggle-chip[data-on='true'],
.nt-toggle-chip[aria-pressed='true'],
.nt-toggle-chip.nt-toggle-chip--on {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 14%, transparent);
  color: var(--nd-accent);
}

/* density compact residual */
html[data-nd-density='compact'] .nd-table td,
html[data-nd-density='compact'] .nd-table th,
.nd-table--compact td,
.nd-table--compact th {
  padding-top: 6px;
  padding-bottom: 6px;
}

/* z-ladder sanity */
.nt-topbar,
.nd-topbar { z-index: var(--nd-z-topbar, 40); }
.nt-shift-strip { z-index: var(--nd-z-shift, 41); }
.nt-incident-strip { z-index: var(--nd-z-incident, 42); }

html[data-nd-theme='light'] .nt-toggle-chip {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20nb — ** drawer write ritual · modal glass residual ── ** ── */
.nd-drawer.nt-write-ritual,
.nd-drawer--write-ritual,
.nt-drawer.nt-write-ritual {
  box-shadow:
    inset 3px 0 0 color-mix(in srgb, var(--nd-warning) 70%, var(--nd-accent)),
    var(--nd-shadow-4, 0 24px 56px color-mix(in srgb, var(--nd-ink, black) 40%, transparent));
}
.nd-drawer__panel,
.nt-drawer__panel {
  border-left: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-accent) 7%, transparent),
      transparent 28%
    ),
    color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}
.nd-modal__panel,
.nt-modal__panel {
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 97%, transparent);
  box-shadow: var(--nd-shadow-4, 0 28px 64px color-mix(in srgb, var(--nd-ink, black) 42%, transparent));
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}
.nd-modal__backdrop,
.nt-modal__backdrop,
.nd-drawer__backdrop {
  background: color-mix(in srgb, var(--nd-ink, black) 55%, transparent);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

/* scrollbars subtle */
.nt-shell-sidebar,
.nt-chat-scroll,
.nt-tickets__queue,
.nt-cmdk__list {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--nd-accent) 35%, transparent) transparent;
}

/* kbd residual */
.nt-kbd,
kbd.nt-kbd {
  display: inline-flex;
  align-items: center;
  min-height: 18px;
  padding: 0 6px;
  border-radius: 6px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 50%, transparent);
  font-family: var(--nd-font-mono, ui-monospace, monospace);
  font-size: 10px;
  color: var(--nd-text-secondary);
}

/* link residual */
a.nt-link,
.nt-link {
  color: color-mix(in srgb, var(--nd-accent) 88%, var(--nd-text));
  text-decoration-color: color-mix(in srgb, var(--nd-accent) 35%, transparent);
}
a.nt-link:hover,
.nt-link:hover {
  color: var(--nd-accent);
}

html[data-nd-theme='light'] .nd-drawer__panel,
html[data-nd-theme='light'] .nd-modal__panel {
  background: color-mix(in srgb, var(--nd-surface-0, white) 98%, transparent);
}

/* ── ** ── ** Wave 20nc — ** overview launchpad · health bars residual ── ** ── */
.nt-overview-shell .nt-launchpad,
.nt-launchpad {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 12px;
}
.nt-launchpad__card,
.nt-launch-card {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    linear-gradient(
      155deg,
      color-mix(in srgb, var(--nd-accent) 10%, transparent),
      transparent 50%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 14px 14px 12px;
  text-decoration: none;
  color: inherit;
  transition: border-color 140ms ease, transform 140ms ease, box-shadow 140ms ease;
}
.nt-launchpad__card:hover,
.nt-launch-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 32%, var(--nd-border));
  box-shadow: var(--nd-shadow-2, 0 12px 28px color-mix(in srgb, var(--nd-ink, black) 24%, transparent));
  transform: translateY(-1px);
}
.nt-launchpad__card:focus-visible,
.nt-launch-card:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--nd-focus-ring, color-mix(in srgb, var(--nd-accent) 28%, transparent));
}
.nt-launchpad__title {
  font-weight: 700;
  color: var(--nd-text);
}
.nt-launchpad__meta {
  margin-top: 4px;
  font-size: 12px;
  color: var(--nd-text-secondary);
}

/* overview health bar row */
.nt-overview-health,
.nt-health-row {
  display: grid;
  gap: 8px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
}

/* war-room skeleton residual */
.nt-page-skeleton,
.nt-war-room-skeleton {
  display: grid;
  gap: 12px;
  padding: 8px 2px;
}
.nt-page-skeleton__hero {
  height: 72px;
  border-radius: 16px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent),
    color-mix(in srgb, var(--nd-accent) 10%, transparent),
    color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent)
  );
  background-size: 200% 100%;
  animation: nt-skeleton-shimmer 1.4s ease-in-out infinite;
}
.nt-page-skeleton__row {
  height: 40px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
}
@keyframes nt-skeleton-shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .nt-page-skeleton__hero { animation: none; }
  .nt-launchpad__card:hover,
  .nt-launch-card:hover { transform: none; }
}

html[data-nd-theme='light'] .nt-launchpad__card,
html[data-nd-theme='light'] .nt-overview-health {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20nd — ** site detail · clients shell · mono residual ── ** ── */
.nt-site-shell.nt-section-panel,
.nt-clients-shell.nt-section-panel,
.nt-site-detail-shell.nt-section-panel {
  position: relative;
}

.nt-mono-11,
.nt-mono-label,
.nt-mono {
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
