  letter-spacing: 0.01em;
}
.nt-mono-11 { font-size: 11px; }
.nt-mono-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-secondary);
}

.nt-hint-muted,
.nt-body-sec {
  color: var(--nd-text-secondary);
  font-size: 12.5px;
}
.nt-body-sm { font-size: 12.5px; line-height: 1.45; }
.nt-tone-warning { color: var(--nd-warning); }
.nt-tone-muted { color: var(--nd-text-muted, var(--nd-text-secondary)); }
.nt-danger-text { color: var(--nd-danger); }

/* site floor shell residual */
.nt-floor-shell {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    radial-gradient(
      80% 60% at 50% 0%,
      color-mix(in srgb, var(--nd-accent) 8%, transparent),
      transparent 60%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 12px;
  overflow: auto;
}

/* clients toolbar residual densify */
.nt-clients-shell .nt-filter-bar,
.nt-site-shell .nt-filter-bar {
  margin-bottom: 10px;
}

/* status dot residual */
.nt-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  display: inline-block;
  background: var(--nd-text-secondary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-text-secondary) 14%, transparent);
}
.nt-status-dot[data-tone='success'],
.nt-status-dot--ok {
  background: var(--nd-success);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-success) 16%, transparent);
}
.nt-status-dot[data-tone='warning'] {
  background: var(--nd-warning);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-warning) 16%, transparent);
}
.nt-status-dot[data-tone='danger'] {
  background: var(--nd-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-danger) 16%, transparent);
}

html[data-nd-theme='light'] .nt-floor-shell {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20ne — ** DS gallery residual · callout glass ── ** ── */
.nt-ds-gallery,
.nt-design-system {
  display: grid;
  gap: 16px;
}
.nt-ds-gallery__section {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 93%, transparent);
  padding: 14px 16px;
}
.nt-ds-gallery__swatch {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, white 6%, transparent);
}

/* callout glass residual densify */
.nd-alert.nt-callout-glass,
.nt-callout-glass {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  padding: 12px 14px;
}
.nd-alert--danger.nt-callout-glass,
.nt-callout-glass[data-tone='danger'] {
  border-color: color-mix(in srgb, var(--nd-danger) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nd-alert--warning.nt-callout-glass,
.nt-callout-glass[data-tone='warning'] {
  border-color: color-mix(in srgb, var(--nd-warning) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nd-alert--success.nt-callout-glass,
.nt-callout-glass[data-tone='success'] {
  border-color: color-mix(in srgb, var(--nd-success) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-success);
}

/* api error residual */
.nt-api-error,
.nt-backend-banner {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-danger) 30%, var(--nd-border));
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-danger) 12%, transparent),
      transparent 55%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 10px 12px;
}

html[data-nd-theme='light'] .nt-ds-gallery__section,
html[data-nd-theme='light'] .nt-callout-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20nf — ** systems roster · plane cards residual ── ** ── */
.nt-systems-shell .nt-plane-card,
.nt-plane-card {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 7%, transparent),
      transparent 48%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 12px 14px;
  transition: border-color 140ms ease, box-shadow 140ms ease;
}
.nt-plane-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  box-shadow: var(--nd-shadow-1, 0 8px 20px color-mix(in srgb, var(--nd-ink, black) 18%, transparent));
}
.nt-plane-card[data-selected='true'],
.nt-plane-card[aria-selected='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}
.nt-plane-card__name {
  font-weight: 700;
  color: var(--nd-text);
}
.nt-plane-card__meta {
  font-size: 12px;
  color: var(--nd-text-secondary);
}

/* systems roster empty residual */
.nt-systems-shell .nt-empty,
.nt-systems-shell .nt-empty-cinema {
  margin-top: 8px;
}

/* connected badge residual */
.nt-linked-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  color: var(--nd-text-secondary);
}
.nt-linked-pill[data-linked='true'] {
  color: var(--nd-success);
  border-color: color-mix(in srgb, var(--nd-success) 35%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-success) 10%, transparent);
}
.nt-linked-pill[data-linked='false'] {
  color: var(--nd-text-muted, var(--nd-text-secondary));
}

html[data-nd-theme='light'] .nt-plane-card {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20ng — ** topology glass · chat bubble residual ── ** ── */
.nt-topo-host,
.nt-topo3d-shell,
.nt-topology-shell {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  background:
    radial-gradient(
      70% 50% at 50% 0%,
      color-mix(in srgb, var(--nd-accent) 10%, transparent),
      transparent 65%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  overflow: hidden;
  position: relative;
}
.nt-topo3d__brand {
  position: absolute;
  top: 10px;
  left: 12px;
  z-index: 2;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-text-secondary) 85%, var(--nd-accent));
  pointer-events: none;
}
.nt-topo3d__glass {
  position: absolute;
  z-index: 2;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 10px 12px;
  max-width: min(280px, 42vw);
}
.nt-topo3d__glass--tl { top: 36px; left: 12px; }
.nt-topo3d__glass--br { right: 12px; bottom: 12px; }
.nt-topo3d__title { font-weight: 700; color: var(--nd-text); }
.nt-topo3d__meta,
.nt-topo3d__stat { font-size: 12px; color: var(--nd-text-secondary); }

/* chat residual densify */
.nt-chat-shell.nt-section-panel {
  min-height: 0;
}
.nt-chat-bubble {
  max-width: min(64ch, 100%);
  border-radius: 14px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent);
  color: var(--nd-text);
}
.nt-chat-bubble--user {
  margin-left: auto;
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-chat-bubble--assistant {
  margin-right: auto;
}
.nt-chat-pending {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
  color: var(--nd-text-secondary);
  font-size: 12px;
}
.nt-chat-pending__pulse {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--nd-accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--nd-accent) 16%, transparent);
  animation: nt-plane-ecg 1.6s ease-in-out infinite;
}
.nt-chat-tool-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  font-size: 12px;
}
.nt-chat-tool-row[data-ok='false'] {
  border-color: color-mix(in srgb, var(--nd-danger) 30%, var(--nd-border));
}

html[data-nd-theme='light'] .nt-topo-host,
html[data-nd-theme='light'] .nt-chat-bubble,
html[data-nd-theme='light'] .nt-topo3d__glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .nt-chat-pending__pulse { animation: none; }
}

/* ── ** ── ** Wave 20nh — ** table row tones · selection residual ── ** ── */
.nd-table tbody tr[data-tone='success'] td:first-child,
.nd-table tbody tr[data-tone='healthy'] td:first-child {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--nd-success) 75%, transparent);
}
.nd-table tbody tr[data-tone='warning'] td:first-child,
.nd-table tbody tr[data-tone='degraded'] td:first-child {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--nd-warning) 75%, transparent);
}
.nd-table tbody tr[data-tone='danger'] td:first-child,
.nd-table tbody tr[data-tone='critical'] td:first-child {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--nd-danger) 75%, transparent);
}
.nd-table tbody tr[data-selected='true'],
.nd-table tbody tr[aria-selected='true'] {
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
.nd-table tbody tr:hover {
  background: color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nd-table thead th {
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-secondary);
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.nd-table__td--tint-danger { color: var(--nd-danger); font-weight: 700; }
.nd-table__td--tint-warning { color: var(--nd-warning); font-weight: 700; }
.nd-table__td--tint-info { color: var(--nd-info, var(--nd-accent)); font-weight: 700; }
.nd-table__td--tint-success { color: var(--nd-success); font-weight: 700; }

/* sticky table header residual */
.nd-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
}

/* virtual spacer residual */
.nd-table-spacer,
.nt-table-spacer {
  padding: 0 !important;
  border: 0 !important;
}

html[data-nd-theme='light'] .nd-table thead th {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20ni — ** breadcrumbs · pagination · footer residual ── ** ── */
.nt-crumbs,
.nd-breadcrumbs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--nd-text-secondary);
  margin-bottom: 8px;
}
.nt-crumbs a,
.nd-breadcrumbs a {
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text));
  text-decoration: none;
}
.nt-crumbs a:hover { color: var(--nd-accent); }
.nt-crumbs__sep {
  opacity: 0.45;
  user-select: none;
}
.nt-crumbs__current {
  color: var(--nd-text);
  font-weight: 600;
}

/* pagination residual */
.nt-pager,
.nt-tickets__pager {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-pager__meta {
  font-variant-numeric: tabular-nums;
}

/* app footer residual */
.nt-app-footer,
.nt-shell-footer {
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  padding: 8px 14px;
  font-size: 11px;
  color: var(--nd-text-secondary);
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  background: color-mix(in srgb, var(--nd-surface-0, var(--nd-surface-1)) 90%, transparent);
}

/* scroll to top fab residual */
.nt-scroll-top {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: var(--nd-z-fab, 30);
  width: 40px;
  height: 40px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  color: var(--nd-accent);
  box-shadow: var(--nd-shadow-2, 0 10px 24px color-mix(in srgb, var(--nd-ink, black) 28%, transparent));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  cursor: pointer;
}

html[data-nd-theme='light'] .nt-app-footer,
html[data-nd-theme='light'] .nt-scroll-top {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20nj — ** btn size · viewopts panel residual ── ** ── */
.nd-btn--sm,
.nt-btn--sm {
  font-size: 12px;
  padding: 5px 10px;
  border-radius: 9px;
}
.nd-btn--md,
.nt-btn--md {
  font-size: 13px;
  padding: 7px 12px;
}
.nd-viewopts__panel.nt-view-options__panel,
.nt-view-options__panel {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-3, 0 18px 40px color-mix(in srgb, var(--nd-ink, black) 34%, transparent));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 8px;
  min-width: 220px;
}
.nt-view-options__check {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  cursor: pointer;
}

html[data-nd-theme='light'] .nd-viewopts__panel,
html[data-nd-theme='light'] .nt-view-options__panel {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20nk — ** light-theme elevation ladder pass ── ** ── */
html[data-nd-theme='light'] {
  color-scheme: light;
}
html[data-nd-theme='light'] .nt-root,
html[data-nd-theme='light'] .nd-shell {
  background: var(--nd-surface-0);
}
html[data-nd-theme='light'] .nt-shell-sidebar,
html[data-nd-theme='light'] .nt-app-sidebar {
  border-right-color: color-mix(in srgb, var(--nd-border) 70%, transparent);
}
html[data-nd-theme='light'] .nt-shell-navlink[aria-current='page'] {
  box-shadow: inset 2px 0 0 var(--nd-accent);
}
html[data-nd-theme='light'] .nt-shift-strip[data-p1='true'] {
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--nd-danger) 45%, transparent);
}
html[data-nd-theme='light'] .nd-btn--primary,
html[data-nd-theme='light'] .nt-btn--primary {
  color: color-mix(in srgb, var(--nd-ink, black) 88%, var(--nd-accent));
}
html[data-nd-theme='light'] .nt-empty__mark,
html[data-nd-theme='light'] .nt-empty-wake__mark,
html[data-nd-theme='light'] .nt-shell-brand__mark {
  color: color-mix(in srgb, var(--nd-ink, black) 88%, var(--nd-accent));
}

/* print-ish quiet */
@media print {
  .nt-shift-strip,
  .nt-incident-strip,
  .nt-shell-sidebar,
  .nt-topbar,
  .nt-cmdk,
  .nt-bulk-bar,
  .nt-configure-bulk-bar {
    display: none !important;
  }
  .nt-root,
  .nd-shell {
    background: white !important;
  }
}

/* ── ** ── ** Wave 20nl — ** diff code · sparkline · progress residual ── ** ── */
.nt-diff-code,
.nd-diff {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  overflow: auto;
  font-family: var(--nd-font-mono, ui-monospace, monospace);
  font-size: 12px;
  line-height: 1.45;
}
.nt-diff-line--del {
  background: color-mix(in srgb, var(--nd-danger) 12%, transparent);
  color: color-mix(in srgb, var(--nd-danger) 85%, var(--nd-text));
}
.nt-diff-line--add {
  background: color-mix(in srgb, var(--nd-success) 12%, transparent);
  color: color-mix(in srgb, var(--nd-success) 85%, var(--nd-text));
}
.nt-diff-line--ctx {
  color: var(--nd-text-secondary);
}

.nd-progress,
.nt-progress-rail {
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--nd-border) 55%, transparent);
}
.nd-progress__fill,
.nt-progress-rail__fill {
  height: 100%;
  width: var(--nd-health, 0%);
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-accent) 70%, var(--nd-success)),
    var(--nd-accent)
  );
  transition: width 240ms ease;
}
.nd-progress__fill--danger,
.nt-progress-rail__fill--danger {
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-danger) 70%, var(--nd-accent)), var(--nd-danger));
}
.nd-progress__fill--warning,
.nt-progress-rail__fill--warning {
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-warning) 70%, var(--nd-accent)), var(--nd-warning));
}

.nt-sparkline,
.nd-sparkline {
  color: var(--nd-accent);
  overflow: visible;
}
.nt-sparkline path,
.nd-sparkline path {
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
}

@media (prefers-reduced-motion: reduce) {
  .nd-progress__fill,
  .nt-progress-rail__fill { transition: none; }
}

html[data-nd-theme='light'] .nt-diff-code {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20nm — ** central/mist section panels residual ── ** ── */
.nt-central-section.nt-section-panel,
.nt-mist-section.nt-section-panel,
.nt-central-section:not(.nt-section-panel),
.nt-mist-section:not(.nt-section-panel) {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--nd-accent) 6%, transparent),
      transparent 46%
    ),
    color-mix(in srgb, var(--nd-surface-1) 93%, transparent);
  padding: 12px 14px 14px;
  margin-bottom: 12px;
}
.nt-central-section::before,
.nt-mist-section::before {
  content: "";
  display: block;
  height: 2px;
  margin: 0 0 12px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--nd-accent) 50%, transparent),
    transparent
  );
  opacity: 0.7;
}

.nt-device-section.nt-section-panel,
.nt-site-section.nt-section-panel,
.nt-device-section:not(.nt-section-panel),
.nt-site-section:not(.nt-section-panel) {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 93%, transparent);
  padding: 12px 14px;
  margin-bottom: 10px;
}

html[data-nd-theme='light'] .nt-central-section,
html[data-nd-theme='light'] .nt-mist-section,
html[data-nd-theme='light'] .nt-device-section,
html[data-nd-theme='light'] .nt-site-section {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20nn — ** form field · label · helper residual ── ** ── */
.nd-field,
.nt-field,
.nt-filter-field {
  display: grid;
  gap: 5px;
