  margin-bottom: 12px;
}

/* settings row residual */
.nt-settings-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px 14px;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 82%, transparent);
}
.nt-settings-row:last-child { border-bottom: 0; }
.nt-settings-row__title { font-weight: 650; color: var(--nd-text); }
.nt-settings-row__desc { font-size: 12px; color: var(--nd-text-secondary); }

/* webhook banner residual densify */
.nt-webhooks-banner,
.nt-sse-banner {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-info, var(--nd-accent)) 28%, var(--nd-border));
