    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-info, var(--nd-accent)) 12%, transparent),
      transparent 60%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 10px 12px;
  margin-bottom: 10px;
}

