}

/* ── ** ── ** Wave 20nr — ** selection cinema · rowlink residual ── ** ── */
.nt-rowlink {
  display: block;
  width: 100%;
  text-align: left;
  border: 1px solid transparent;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  border-radius: 12px;
  padding: 8px 10px;
}
.nt-rowlink:hover,
.nt-rowlink:focus-visible {
